/**
 * execute ÔÇö ejecutar un comando contra el estado del juego.
 *
 * Pipeline:
 * 1. isLegal: validar que el comando es legal.
 * 2. plan: consumir RNG si es necesario.
 * 3. execute: resolver efectos y generar eventos.
 * 4. apply: aplicar eventos al estado (reducer puro).
 *
 * El estado devuelto es un nuevo objeto (inmutable).
 */

import type { GameState, GameEvent, Command, PendingChoice } from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import { applyEvent } from '../events/applyEvent.js';
import { taheralEvasionBonus, useHeroAbility } from '../heroes/abilities.js';
import { EffectRegistry, registerCoreEffects } from '../effects/registry.js';
import { EventBus } from '../triggers/index.js';
import { resolveCard, processHordeAttackTriggers } from '../effects/resolver.js';
import { swapStartingCards, openSupportDeck, buySupportCard } from '../modes/solo.js';
import { executeTurnStartEffect } from '../scenarios/index.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

export interface ValidationResult {
  ok: boolean;
  reason?: string;
}

export interface CommandResult {
  accepted: boolean;
  reason?: string;
  events: GameEvent[];
  newState: GameState;
  rng: DeterministicRng;
}

export function isLegal(
  state: GameState,
  playerId: string,
  command: Command,
  catalog?: CatalogLoadResult,
): ValidationResult {
  // Validaciones basicas
  switch (command.type) {
    case 'PLAY_CARD': {
      if (state.phase !== 'PLAYER_ATTACK' && state.phase !== 'RESOLVING_CARD' && state.phase !== 'ATTACK_CHOICE') {
        return { ok: false, reason: 'Not in attack phase' };
      }
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      const player = state.players[playerId];
      const card = player.hand.find(c => c.instanceId === command.cardInstanceId);
      if (!card) {
        return { ok: false, reason: 'Card not in hand' };
      }
      // Verificar costes de la carta (efecto COST)
      if (catalog) {
        const cardDef = catalog.byId.get(card.definitionId);
        if (cardDef?.effects) {
          for (const eff of cardDef.effects) {
            if (eff.type === 'COST' && eff.resource === 'COINS') {
              const amount = eff.amount.kind === 'CONSTANT' ? eff.amount.value : 0;
              if (player.coins < amount) {
                return { ok: false, reason: `Not enough coins (need ${amount}, have ${player.coins})` };
              }
            }
          }
        }
      }
      return { ok: true };
    }

    case 'END_ATTACK': {
      if (state.phase !== 'PLAYER_ATTACK' && state.phase !== 'ATTACK_CHOICE') {
        return { ok: false, reason: 'Not in attack phase' };
      }
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      return { ok: true };
    }

    case 'EVASION': {
      if (state.phase !== 'ATTACK_CHOICE') {
        return { ok: false, reason: 'Not in attack choice phase' };
      }
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      // Especificacion 3.4 Opcion B: descartar minimo 2 cartas de la mano
      if (command.discardedCardInstanceIds.length < 2) {
        return { ok: false, reason: 'Must discard at least 2 cards to evade' };
      }
      // Validar que no haya IDs duplicados (evita inflar bonus de Taheral)
      const uniqueIds = new Set(command.discardedCardInstanceIds);
      if (uniqueIds.size !== command.discardedCardInstanceIds.length) {
        return { ok: false, reason: 'Duplicate card IDs in evasion' };
      }
      const player = state.players[playerId];
      // Verificar que las cartas pertenezcan a la mano del jugador
      for (const cardId of command.discardedCardInstanceIds) {
        const inHand = player.hand.some(c => c.instanceId === cardId);
        if (!inHand) {
          return { ok: false, reason: 'Discarded cards must be from hand' };
        }
      }
      return { ok: true };
    }

    case 'BUY_CARD': {
      if (state.phase !== 'MARKET') {
        return { ok: false, reason: 'Not in market phase' };
      }
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      const card = state.market.find(c => c.instanceId === command.marketCardInstanceId);
      if (!card) {
        return { ok: false, reason: 'Card not in market' };
      }
      // Validar coste y capacidades desde el catalogo
      // D376: Sin catalogo no se puede validar el coste; rechazar
      if (!catalog) {
        return { ok: false, reason: 'Catalog required to validate purchase' };
      }
      const cardDef = catalog.byId.get(card.definitionId);
      if (!cardDef) {
        return { ok: false, reason: 'Card definition not found' };
      }
      {
        const player = state.players[playerId];
        const cost = Math.max(0, (cardDef.printedCost ?? 0) + state.marketCostModifier);
        if (player.coins < cost) {
          return { ok: false, reason: `Not enough coins (need ${cost}, have ${player.coins})` };
        }
        // Validar iconos de capacidad requeridos
        // D: Un heroe puede comprar una carta si tiene todos los requiredCapabilities,
        // o si tiene un penaltyCapability que sustituye al requerido (ej: Picaro con EXPERTISE usa RANGED con -1)
        if (cardDef.requiredCapabilities && cardDef.requiredCapabilities.length > 0) {
          const hasAll = cardDef.requiredCapabilities.every(icon =>
            player.capabilities.includes(icon)
          );
          if (!hasAll) {
            // Verificar si puede usarla con penalizacion
            const canUseWithPenalty = cardDef.requiredCapabilities.every(reqIcon =>
              player.capabilities.includes(reqIcon) ||
              (cardDef.penaltyCapabilities?.some(p => player.capabilities.includes(p.icon)) ?? false)
            );
            if (!canUseWithPenalty) {
              return { ok: false, reason: 'Hero lacks required capabilities' };
            }
          }
        }
      }
      return { ok: true };
    }

    case 'END_TURN': {
      if (state.phase !== 'RESTORATION' && state.phase !== 'MARKET') {
        return { ok: false, reason: 'Not in restoration or market phase' };
      }
      // D392: Validar jugador activo
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      return { ok: true };
    }

    case 'USE_HERO_ABILITY': {
      const player = state.players[playerId];
      if (player.heroUsesRemaining <= 0) {
        return { ok: false, reason: 'No hero ability uses remaining' };
      }
      // D356: Validar fase seg├║n el h├®roe
      // Val├¿rys y Lisavette son reactivos: solo durante HORDE_ATTACK
      const heroDef = catalog?.byId.get(player.heroId);
      const heroId = heroDef?.id ?? '';
      const isReactiveHero = heroId.includes('valerys') || heroId.includes('lisavette');
      if (isReactiveHero && state.phase !== 'HORDE_ATTACK') {
        return { ok: false, reason: 'This hero ability can only be used during Horde Attack' };
      }
      // H├®roes activos: solo durante el turno del jugador (no SETUP, FINISHED, etc.)
      if (!isReactiveHero && (state.phase === 'SETUP' || state.phase === 'FINISHED' || state.phase === 'GAME_END_CHECK')) {
        return { ok: false, reason: 'Cannot use hero ability in this phase' };
      }
      return { ok: true };
    }

    case 'SWAP_STARTING_CARDS': {
      if (state.mode !== 'SOLO') {
        return { ok: false, reason: 'Only available in solo mode' };
      }
      if (state.phase !== 'SETUP' && state.phase !== 'INITIAL_PLAYER_SELECTION') {
        return { ok: false, reason: 'Only during setup or initial selection' };
      }
      if (command.cardInstanceIds.length > 2) {
        return { ok: false, reason: 'Can only swap up to 2 cards' };
      }
      // D399: Validar ids unicos (no duplicados)
      const uniqueIds = new Set(command.cardInstanceIds);
      if (uniqueIds.size !== command.cardInstanceIds.length) {
        return { ok: false, reason: 'Duplicate card ids' };
      }
      // D395: Validar que las cartas est├ín en la mano
      const swapPlayer = state.players[playerId];
      if (swapPlayer) {
        for (const cardId of command.cardInstanceIds) {
          if (!swapPlayer.hand.some(c => c.instanceId === cardId)) {
            return { ok: false, reason: 'Card not in hand' };
          }
        }
      }
      return { ok: true };
    }

    case 'CHOOSE_LEADER_CARDS': {
      if (state.phase !== 'INITIAL_PLAYER_SELECTION') {
        return { ok: false, reason: 'Only during initial player selection' };
      }
      if (command.cardInstanceIds.length < 1 || command.cardInstanceIds.length > 2) {
        return { ok: false, reason: 'Must choose 1 or 2 cards' };
      }
      // Validar que las cartas est├ín en la mano del jugador
      const player = state.players[playerId];
      if (!player) return { ok: false, reason: 'Player not found' };
      const handIds = new Set(player.hand.map(c => c.instanceId));
      for (const cardId of command.cardInstanceIds) {
        if (!handIds.has(cardId)) {
          return { ok: false, reason: 'Card not in hand' };
        }
      }
      // Validar que el jugador tiene una pendingChoice de l├¡der
      const hasLeaderChoice = state.pendingChoices.some(
        c => c.choiceId === `leader-bid-${playerId}` && c.type === 'SELECT_CARDS_FOR_LEADER'
      );
      if (!hasLeaderChoice) {
        return { ok: false, reason: 'Player has no pending leader bid' };
      }
      return { ok: true };
    }

    case 'ACCEPT_TURN_START_EFFECT': {
      if (!state.scenario) {
        return { ok: false, reason: 'No active scenario' };
      }
      return { ok: true };
    }

    case 'OPEN_SUPPORT_DECK': {
      if (state.mode !== 'SOLO') {
        return { ok: false, reason: 'Only available in solo mode' };
      }
      // D361: Apoyos solo durante la Fase de Ataque (spec ┬º4.2)
      if (state.phase !== 'PLAYER_ATTACK' && state.phase !== 'ATTACK_CHOICE') {
        return { ok: false, reason: 'Support decks can only be opened during the Attack phase' };
      }
      // D393: Validar jugador activo
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      return { ok: true };
    }

    case 'BUY_SUPPORT_CARD': {
      if (state.mode !== 'SOLO') {
        return { ok: false, reason: 'Only available in solo mode' };
      }
      // D361: Apoyos solo durante la Fase de Ataque (spec ┬º4.2)
      if (state.phase !== 'PLAYER_ATTACK' && state.phase !== 'ATTACK_CHOICE') {
        return { ok: false, reason: 'Support cards can only be bought during the Attack phase' };
      }
      // D393: Validar jugador activo
      if (state.activePlayerId !== playerId) {
        return { ok: false, reason: 'Not your turn' };
      }
      return { ok: true };
    }

    case 'PASS':
      return { ok: true };

    case 'RESOLVE_CHOICE': {
      const choice = state.pendingChoices.find(c => c.choiceId === command.choiceId);
      if (!choice) return { ok: false, reason: 'Choice not found' };
      if (choice.playerId !== playerId) return { ok: false, reason: 'Not your choice' };
      if (command.selectedIds.length < choice.minSelections || command.selectedIds.length > choice.maxSelections) {
        return { ok: false, reason: 'Invalid number of selections' };
      }
      // D394: Validar que todas las selecciones est├®n en las opciones v├ílidas
      // (excepto CONFIRM con opciones textuales como 'glory'/'coins')
      if (choice.type !== 'CONFIRM') {
        for (const id of command.selectedIds) {
          if (!choice.options.includes(id)) {
            return { ok: false, reason: 'Invalid selection: not among available options' };
          }
        }
        // D400: Validar que no haya selecciones duplicadas (especialmente SELECT_ORDER)
        const uniqueSelected = new Set(command.selectedIds);
        if (uniqueSelected.size !== command.selectedIds.length) {
          return { ok: false, reason: 'Duplicate selections' };
        }
      }
      return { ok: true };
    }

    default:
      return { ok: false, reason: 'Command not supported' };
  }
}

export function execute(
  state: GameState,
  command: Command,
  rng: DeterministicRng,
  registry?: EffectRegistry,
  catalog?: CatalogLoadResult,
): CommandResult {
  // Identificar al jugador que envia el comando
  const playerId = getPlayerIdFromCommand(command, state);

  // 1. Validar
  const validation = isLegal(state, playerId, command, catalog);
  if (!validation.ok) {
    return {
      accepted: false,
      reason: validation.reason,
      events: [],
      newState: state,
      rng,
    };
  }

  // 2. Preparar motor de efectos
  const reg = registry ?? new EffectRegistry();
  if (!registry) {
    registerCoreEffects(reg);
  }
  const bus = new EventBus(reg, rng);
  bus.setState(state);

  // 3. Generar eventos segun el comando
  const events: GameEvent[] = [];

  switch (command.type) {
    case 'PLAY_CARD': {
      const player = state.players[playerId];
      const card = player.hand.find(c => c.instanceId === command.cardInstanceId);
      if (!card) {
        return { accepted: false, reason: 'Card not found', events, newState: state, rng };
      }
      // Si estamos en ATTACK_CHOICE, transicionar a PLAYER_ATTACK primero
      if (state.phase === 'ATTACK_CHOICE') {
        events.push({
          type: 'PHASE_CHANGED',
          phase: 'PLAYER_ATTACK',
          seq: reg.nextSeq(),
        });
        state = { ...state, phase: 'PLAYER_ATTACK' };
      }

      // Si tenemos catalogo, resolver la carta completamente con efectos
      if (catalog) {
        const cardDef = catalog.byId.get(card.definitionId);
        if (cardDef) {
          const result = resolveCard(
            state,
            card,
            cardDef,
            command.targetEnemyId ?? null,
            player,
            rng,
            reg,
            catalog,
          );
          // Si hay eleccion pendiente (empate), aplicar eventos acumulados y guardar la eleccion
          // D390: Aplicar los eventos al estado antes de devolverlo
          if (result.pendingChoice) {
            let choiceState = state;
            for (const ev of result.events) {
              choiceState = applyEvent(choiceState, ev);
            }
            choiceState = {
              ...choiceState,
              pendingChoices: [...choiceState.pendingChoices, result.pendingChoice],
            };
            return {
              accepted: true,
              events: [...events, ...result.events],
              newState: choiceState,
              rng,
            };
          }
          // Aplicar todos los eventos generados por la resolucion
          let resolvedState = state;
          for (const ev of result.events) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          return {
            accepted: true,
            events: [...events, ...result.events],
            newState: { ...resolvedState, rngState: rng.serialize() },
            rng,
          };
        }
      }

      // Fallback sin catalogo: esqueleto basico
      events.push({
        type: 'CARD_PLAYED',
        playerId,
        cardInstanceId: card.instanceId,
        cardDefinitionId: card.definitionId,
        cardName: catalog?.byId.get(card.definitionId)?.name,
        targetEnemyInstanceId: command.targetEnemyId,
        seq: reg.nextSeq(),
      });

      // Mover carta a Desgaste
      if (card.zone !== 'IN_FRONT_OF_PLAYER') {
        events.push({
          type: 'CARD_MOVED',
          cardInstanceId: card.instanceId,
          from: 'HAND',
          to: 'WEAR_PILE',
          seq: reg.nextSeq(),
        });
      }

      break;
    }

    case 'END_ATTACK': {
      // Pasar a fase de ataque de la Horda
      events.push({
        type: 'PHASE_CHANGED',
        phase: 'HORDE_ATTACK',
        seq: reg.nextSeq(),
      });
      break;
    }

    case 'EVASION': {
      events.push({
        type: 'EVASION_PERFORMED',
        playerId,
        discardedCardInstanceIds: command.discardedCardInstanceIds,
        seq: reg.nextSeq(),
      });
      // EVASION_PERFORMED ya mueve las cartas de HAND a WEAR_PILE en applyEvent.
      // No emitir CARD_MOVED redundantes (D334).
      // Poblar evasionDiscardedCount en el estado para EVASION_DISCARDED_COUNT
      state = { ...state, evasionDiscardedCount: command.discardedCardInstanceIds.length };
      // Taheral: ganar 2 monedas por cada carta descartada en Evasion
      const taheralEvents = taheralEvasionBonus(state, playerId, command.discardedCardInstanceIds.length);
      events.push(...taheralEvents);
      // Consumir un uso de la Pericia de Taheral si se activo
      if (taheralEvents.length > 0) {
        const player = state.players[playerId];
        events.push({
          type: 'HERO_ABILITY_USED',
          playerId,
          usesRemaining: Math.max(0, player.heroUsesRemaining - 1),
          seq: reg.nextSeq(),
        });
      }
      // Yermo de Cemenmar: en evasi├│n, robar hasta 3 monedas (max 2 por h├®roe)
      if (state.scenario?.definitionId === 'scenario.cemenmar-wastes') {
        const others = state.playerOrder.filter(id => id !== playerId);
        let totalStolen = 0;
        for (const otherId of others) {
          if (totalStolen >= 3) break;
          const otherPlayer = state.players[otherId];
          const maxFromThis = Math.min(2, otherPlayer.coins, 3 - totalStolen);
          if (maxFromThis > 0) {
            events.push({
              type: 'COINS_STOLEN',
              fromPlayerId: otherId,
              toPlayerId: playerId,
              amount: maxFromThis,
              seq: reg.nextSeq(),
            });
            totalStolen += maxFromThis;
          }
        }
      }
      // Pasar directamente a Mercado (no recibe da├▒o de la Horda)
      events.push({
        type: 'PHASE_CHANGED',
        phase: 'MARKET',
        seq: reg.nextSeq(),
      });
      break;
    }

    case 'BUY_CARD': {
      const card = state.market.find(c => c.instanceId === command.marketCardInstanceId);
      if (!card) {
        return { accepted: false, reason: 'Card not in market', events, newState: state, rng };
      }
      // Determinar coste desde el catalogo
      // D376: Sin catalogo no se puede determinar el coste; rechazar
      if (!catalog) {
        return { accepted: false, reason: 'Catalog required to determine cost', events, newState: state, rng };
      }
      const cardDef = catalog.byId.get(card.definitionId);
      if (!cardDef) {
        return { accepted: false, reason: 'Card definition not found', events, newState: state, rng };
      }
      let cost = cardDef.printedCost ?? 0;
      // Aplicar modificador de escenario (Mercado de Lotharion: -1)
      cost = Math.max(0, cost + state.marketCostModifier);
      events.push({
        type: 'MARKET_PURCHASED',
        playerId,
        cardInstanceId: card.instanceId,
        cost,
        seq: reg.nextSeq(),
      });
      // Reposicion automatica: siempre 5 cartas disponibles (especificacion 3.5)
      // EXCEPCION: en modo solitario no se repone el mercado (especificacion 4.1)
      if (state.marketDeck.length > 0 && state.mode !== 'SOLO') {
        const newCard = state.marketDeck[0];
        events.push({
          type: 'MARKET_REPLENISHED',
          cardInstanceId: newCard.instanceId,
          seq: reg.nextSeq(),
        });
      }
      break;
    }

    case 'END_TURN': {
      // Si estamos en MARKET, transicionar a RESTORATION primero
      if (state.phase === 'MARKET') {
        events.push({
          type: 'PHASE_CHANGED',
          phase: 'RESTORATION',
          seq: reg.nextSeq(),
        });
        state = { ...state, phase: 'RESTORATION' };
      }
      // TURN_ENDED lo emite processTurnEnd (no duplicar aqu├¡)
      break;
    }

    case 'USE_HERO_ABILITY': {
      // Invocar la pericia del heroe (useHeroAbility ya emite HERO_ABILITY_USED)
      const targetId = (command as any).targetId;
      const abilityResult = catalog
        ? useHeroAbility(state, playerId, rng, catalog, targetId)
        : { events: [] as GameEvent[], state, pendingChoice: null };
      events.push(...abilityResult.events);
      // Usar el estado devuelto (puede incluir pendingChoices para Idril/Aranel/Neddia)
      state = abilityResult.state;
      break;
    }

    case 'PASS':
      // No genera eventos
      break;

    case 'SWAP_STARTING_CARDS': {
      const swapResult = swapStartingCards(state, playerId, command.cardInstanceIds, rng);
      if (swapResult.error) {
        return { accepted: false, reason: swapResult.error, events: [], newState: state, rng };
      }
      events.push(...swapResult.events);
      state = swapResult.state;
      break;
    }

    case 'CHOOSE_LEADER_CARDS': {
      // Guardar las cartas pujadas por el jugador en leaderBidCards
      state = {
        ...state,
        players: {
          ...state.players,
          [playerId]: {
            ...state.players[playerId],
            leaderBidCards: command.cardInstanceIds,
          },
        },
        // Remover la pendingChoice de este jugador
        pendingChoices: state.pendingChoices.filter(
          c => c.choiceId !== `leader-bid-${playerId}`
        ),
      };
      // Verificar si todos los jugadores han pujado
      const allBid = state.playerOrder.every(pid =>
        (state.players[pid] as any).leaderBidCards &&
        (state.players[pid] as any).leaderBidCards.length > 0
      );
      if (allBid && catalog) {
        // Resolver la puja inline (evita import circular con setup.ts)
        let leaderId = state.playerOrder[0];
        let maxDamage = -1;
        for (const pid of state.playerOrder) {
          const p = state.players[pid];
          if (!p) continue;
          const bidCardIds = (p as any).leaderBidCards as string[] | undefined;
          if (!bidCardIds || bidCardIds.length === 0) continue;
          const bidCards = p.hand.filter(c => bidCardIds.includes(c.instanceId));
          let bidDamage = 0;
          for (const card of bidCards) {
            const cardDef = catalog.byId.get(card.definitionId);
            bidDamage += cardDef?.printedAttack ?? 0;
          }
          if (bidDamage > maxDamage) {
            maxDamage = bidDamage;
            leaderId = pid;
          } else if (bidDamage === maxDamage) {
            // Empate: gana el jugador con mayor edad (spec ┬º3.2.6)
            const currentLeader = state.players[leaderId];
            const challenger = state.players[pid];
            const currentAge = currentLeader?.playerAge ?? 0;
            const challengerAge = challenger?.playerAge ?? 0;
            if (challengerAge > currentAge) {
              leaderId = pid;
            }
          }
          // Retirar cartas pujadas de mano y ponerlas al fondo del mazo
          const bidIds = new Set(bidCards.map(c => c.instanceId));
          state.players[pid] = {
            ...state.players[pid],
            hand: state.players[pid].hand.filter(c => !bidIds.has(c.instanceId)),
            abilityDeck: [...state.players[pid].abilityDeck, ...bidCards.map(c => ({ ...c, zone: 'ABILITY_DECK' as any }))],
          };
        }
        // Robar hasta 4 cartas
        for (const pid of state.playerOrder) {
          const p = state.players[pid];
          if (!p) continue;
          while (p.hand.length < 4 && p.abilityDeck.length > 0) {
            const drawn = p.abilityDeck[0];
            state.players[pid] = {
              ...state.players[pid],
              abilityDeck: state.players[pid].abilityDeck.slice(1),
              hand: [...state.players[pid].hand, { ...drawn, zone: 'HAND' as any }],
            };
          }
        }
        state = { ...state, activePlayerId: leaderId };
        state.pendingChoices = state.pendingChoices.filter(c => !c.choiceId.startsWith('leader-bid-'));
        events.push({
          type: 'LEADER_DETERMINED',
          playerId: leaderId,
          seq: reg.nextSeq(),
        });
      }
      break;
    }

    case 'ACCEPT_TURN_START_EFFECT': {
      if (state.scenario) {
        const tsResult = executeTurnStartEffect(state, state.scenario.definitionId, playerId, command.accepted, catalog, rng);
        events.push(...tsResult.events);
        state = tsResult.state;
        // D381: Si el efecto genera una eleccion pendiente (ej: Portal de Ulthar), guardarla
        if (tsResult.pendingChoice) {
          state = {
            ...state,
            pendingChoices: [...state.pendingChoices, tsResult.pendingChoice],
          };
        }
        // Consumir la pendingChoice de inicio de turno
        const choiceId = `turn-start-${state.turnNumber}`;
        state = {
          ...state,
          pendingChoices: state.pendingChoices.filter(pc => pc.choiceId !== choiceId),
        };
      }
      break;
    }

    case 'OPEN_SUPPORT_DECK': {
      const result = openSupportDeck(state, playerId, command.supportDeckIndex);
      if (result.error) {
        return { accepted: false, reason: result.error, events: [], newState: state, rng };
      }
      events.push(...result.events);
      state = result.state;
      break;
    }

    case 'BUY_SUPPORT_CARD': {
      const result = buySupportCard(state, playerId, command.supportDeckIndex, command.payment);
      if (result.error) {
        return { accepted: false, reason: result.error, events: [], newState: state, rng };
      }
      events.push(...result.events);
      state = result.state;
      break;
    }

    case 'RESOLVE_CHOICE': {
      // Resolver una eleccion pendiente (empate en HERO_WITH_FEWEST_WOUNDS, etc.)
      const choice = state.pendingChoices.find(c => c.choiceId === command.choiceId);
      if (!choice) {
        return { accepted: false, reason: 'Choice not found', events, newState: state, rng };
      }
      if (choice.playerId !== playerId) {
        return { accepted: false, reason: 'Not your choice', events, newState: state, rng };
      }
      // SEARCH_DECK: buscar en mazo de habilidad y poner en mano (Aranel)
      if (choice.type === 'SEARCH_DECK') {
        const selectedCardId = command.selectedIds[0];
        const player = state.players[playerId];
        const foundCard = player.abilityDeck.find(c => c.instanceId === selectedCardId);
        if (foundCard) {
          // D368: Si hay multiples cartas en mano, pedir al jugador que elija cual devolver
          if (player.hand.length > 1) {
            const handChoiceId = `aranel-hand-${reg.nextSeq()}`;
            state = {
              ...state,
              pendingChoices: [
                ...state.pendingChoices.filter(c => c.choiceId !== command.choiceId),
                {
                  choiceId: handChoiceId,
                  playerId,
                  type: 'SELECT_CARD_FROM_HAND' as const,
                  prompt: 'Elige una carta de tu mano para devolver al mazo',
                  options: player.hand.map(c => c.instanceId),
                  minSelections: 1,
                  maxSelections: 1,
                  relatedCardIds: [foundCard.instanceId],
                },
              ],
            };
            return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
          }
          // Si solo hay 0 o 1 cartas en mano, usar la primera (sin eleccion)
          const handCard = player.hand[0];
          const newEvents: GameEvent[] = [];
          if (handCard) {
            newEvents.push({
              type: 'CARD_MOVED',
              cardInstanceId: handCard.instanceId,
              from: 'HAND',
              to: 'ABILITY_DECK',
              seq: reg.nextSeq(),
            });
          }
          newEvents.push({
            type: 'CARD_MOVED',
            cardInstanceId: foundCard.instanceId,
            from: 'ABILITY_DECK',
            to: 'HAND',
            seq: reg.nextSeq(),
          });
          events.push(...newEvents);
          let resolvedState = state;
          for (const ev of newEvents) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          // Barajar realmente el mazo y emitir DECK_SHUFFLED con el orden resultante
          const shuffledDeck = rng.shuffle(resolvedState.players[playerId].abilityDeck);
          const shuffleEvent: GameEvent = {
            type: 'DECK_SHUFFLED',
            playerId,
            deck: 'ABILITY',
            newOrder: shuffledDeck.map(c => c.instanceId),
            seq: reg.nextSeq(),
          };
          events.push(shuffleEvent);
          resolvedState = applyEvent(resolvedState, shuffleEvent);
          resolvedState = {
            ...resolvedState,
            pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
          };
          state = resolvedState;
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // SEARCH_MARKET_DECK: buscar en mazo de Mercado e intercambiar con mercado visible (Neddia)
      if (choice.type === 'SEARCH_MARKET_DECK') {
        const selectedIds = command.selectedIds;
        // D369: Pedir al jugador que elija qu├® cartas visibles del mercado reemplazar
        if (selectedIds.length > 0 && state.market.length > 0) {
          const marketChoiceId = `neddia-market-${reg.nextSeq()}`;
          state = {
            ...state,
            pendingChoices: [
              ...state.pendingChoices.filter(c => c.choiceId !== command.choiceId),
              {
                choiceId: marketChoiceId,
                playerId,
                type: 'SELECT_FROM_MARKET' as const,
                prompt: `Elige ${selectedIds.length} carta(s) visible(s) del mercado para reemplazar`,
                options: state.market.map(c => c.instanceId),
                minSelections: selectedIds.length,
                maxSelections: selectedIds.length,
                relatedCardIds: selectedIds,
              },
            ],
          };
          return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
        }
        state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // SELECT_HERO sin resolutionContext: re-invocar la pericia con el target (Val├¿rys)
      if (choice.type === 'SELECT_HERO' && !choice.resolutionContext) {
        const targetHeroId = command.selectedIds[0];
        if (targetHeroId && catalog) {
          const abilityResult = useHeroAbility(state, playerId, rng, catalog, targetHeroId);
          events.push(...abilityResult.events);
          // Aplicar los eventos al estado para que glory/prevention/shields/coins se reflejen
          let resolvedState = abilityResult.state;
          for (const ev of abilityResult.events) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // SELECT_ENEMY sin resolutionContext con choiceId "trap-": Trampa (empate de Fortaleza)
      if (choice.type === 'SELECT_ENEMY' && !choice.resolutionContext && choice.choiceId.startsWith('trap-')) {
        const chosenEnemyId = command.selectedIds[0];
        // Validar que el enemigo elegido est├® entre las opciones del empate
        if (!choice.options.includes(chosenEnemyId)) {
          return { accepted: false, reason: 'Selected enemy is not among the tied options', events, newState: state, rng };
        }
        if (catalog) {
          // Re-invocar processHordeAttackTriggers con el enemigo elegido
          const reg = new EffectRegistry();
          registerCoreEffects(reg);
          const triggerResult = processHordeAttackTriggers(state, rng, reg, catalog, chosenEnemyId);
          events.push(...triggerResult.events);
          let resolvedState = triggerResult.state;
          for (const ev of triggerResult.events) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // SELECT_ORDER: reordenar cartas (Idril: 3 inferiores de la Horda)
      if (choice.type === 'SELECT_ORDER') {
        const newOrder = command.selectedIds;
        // Reordenar las 3 cartas inferiores del mazo de la Horda
        const bottomCount = choice.options.length;
        const top = state.hordeDeck.slice(0, state.hordeDeck.length - bottomCount);
        const reorderedCards = newOrder
          .map(id => state.hordeDeck.find(c => c.instanceId === id))
          .filter((c): c is NonNullable<typeof c> => c !== null);
        state = {
          ...state,
          hordeDeck: [...top, ...reorderedCards],
          pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId),
        };
        // No emitir DECK_RESHUFFLED (es para mazo de habilidad, no Horda)
        break;
      }

      // D368: SELECT_CARD_FROM_HAND con relatedCardIds (Aranel: elegir carta de mano para devolver al mazo)
      if (choice.type === 'SELECT_CARD_FROM_HAND' && choice.relatedCardIds && choice.relatedCardIds.length > 0
          && choice.choiceId.startsWith('aranel-')) {
        const handCardId = command.selectedIds[0];
        const deckCardId = choice.relatedCardIds[0];
        const player = state.players[playerId];
        const handCard = player.hand.find(c => c.instanceId === handCardId);
        const deckCard = player.abilityDeck.find(c => c.instanceId === deckCardId);
        if (handCard && deckCard) {
          const newEvents: GameEvent[] = [
            { type: 'CARD_MOVED', cardInstanceId: handCard.instanceId, from: 'HAND', to: 'ABILITY_DECK', seq: reg.nextSeq() },
            { type: 'CARD_MOVED', cardInstanceId: deckCard.instanceId, from: 'ABILITY_DECK', to: 'HAND', seq: reg.nextSeq() },
          ];
          events.push(...newEvents);
          let resolvedState = state;
          for (const ev of newEvents) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          // Barajar el mazo
          const shuffledDeck = rng.shuffle(resolvedState.players[playerId].abilityDeck);
          const shuffleEvent: GameEvent = {
            type: 'DECK_SHUFFLED', playerId, deck: 'ABILITY',
            newOrder: shuffledDeck.map(c => c.instanceId), seq: reg.nextSeq(),
          };
          events.push(shuffleEvent);
          resolvedState = applyEvent(resolvedState, shuffleEvent);
          state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // D369: SELECT_FROM_MARKET con relatedCardIds (Neddia: elegir cartas visibles del mercado a reemplazar)
      if (choice.type === 'SELECT_FROM_MARKET' && choice.relatedCardIds && choice.relatedCardIds.length > 0
          && choice.choiceId.startsWith('neddia-')) {
        const visibleCardIds = command.selectedIds;
        const deckCardIds = choice.relatedCardIds;
        const newEvents: GameEvent[] = [];
        const effectiveCount = Math.min(visibleCardIds.length, deckCardIds.length);
        for (let i = 0; i < effectiveCount; i++) {
          const visibleCard = state.market.find(c => c.instanceId === visibleCardIds[i]);
          const deckCard = state.marketDeck.find(c => c.instanceId === deckCardIds[i]);
          if (visibleCard && deckCard) {
            newEvents.push({ type: 'CARD_MOVED', cardInstanceId: visibleCard.instanceId, from: 'MARKET', to: 'MARKET_DECK', seq: reg.nextSeq() });
            newEvents.push({ type: 'CARD_MOVED', cardInstanceId: deckCard.instanceId, from: 'MARKET_DECK', to: 'MARKET', seq: reg.nextSeq() });
          }
        }
        events.push(...newEvents);
        let resolvedState = state;
        for (const ev of newEvents) {
          resolvedState = applyEvent(resolvedState, ev);
        }
        // Barajar el mazo de Mercado
        const shuffledMarket = rng.shuffle(resolvedState.marketDeck);
        const shuffleEvent: GameEvent = {
          type: 'DECK_SHUFFLED', playerId, deck: 'MARKET',
          newOrder: shuffledMarket.map(c => c.instanceId), seq: reg.nextSeq(),
        };
        events.push(shuffleEvent);
        resolvedState = applyEvent(resolvedState, shuffleEvent);
        state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // D381: CONFIRM con choiceId "ulthar-pay-": Portal de Ulthar (elegir Gloria o Monedas)
      if (choice.type === 'CONFIRM' && choice.choiceId.startsWith('ulthar-pay-')) {
        const payment = command.selectedIds[0];
        const player = state.players[playerId];
        const newEvents: GameEvent[] = [];
        if (payment === 'glory' && player.glory >= 1) {
          newEvents.push({ type: 'GLORY_LOST', playerId, amount: 1, seq: reg.nextSeq() });
        } else if (payment === 'coins' && player.coins >= 2) {
          newEvents.push({ type: 'COINS_GAINED', playerId, amount: -2, seq: reg.nextSeq() });
        } else {
          return { accepted: false, reason: 'Cannot afford selected payment', events, newState: state, rng };
        }
        events.push(...newEvents);
        let resolvedState = state;
        for (const ev of newEvents) {
          resolvedState = applyEvent(resolvedState, ev);
        }
        // Tras el pago, crear eleccion para elegir Hueste a devolver
        const nonWarlordEnemies = resolvedState.battlefield.filter(e => !e.isWarlord);
        if (nonWarlordEnemies.length > 0 && player.trophies.length > 0) {
          const enemyChoice: PendingChoice = {
            choiceId: `ulthar-enemy-${reg.nextSeq()}`,
            playerId,
            type: 'SELECT_ENEMY',
            prompt: 'Portal de Ulthar: Elige una Hueste para devolverla al mazo',
            options: nonWarlordEnemies.map(e => e.instanceId),
            minSelections: 1,
            maxSelections: 1,
          };
          state = {
            ...resolvedState,
            pendingChoices: [
              ...resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
              enemyChoice,
            ],
          };
        } else {
          state = {
            ...resolvedState,
            pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
          };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // Lodazal de Kalern: SELECT_ENEMY con choiceId "kalern-mud-enemy-"
      if (choice.type === 'SELECT_ENEMY' && choice.choiceId.startsWith('kalern-mud-enemy-')) {
        const enemyId = command.selectedIds[0];
        const newEvent: GameEvent = {
          type: 'ENEMY_RETURNED_TO_HORDE',
          enemyInstanceId: enemyId,
          position: 'BOTTOM',
          seq: reg.nextSeq(),
        };
        events.push(newEvent);
        let resolvedState = applyEvent(state, newEvent);
        resolvedState = {
          ...resolvedState,
          pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
        };
        state = resolvedState;
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // Puerto de Eque: SELECT_CARD_FROM_HAND con choiceId "eque-port-card-"
      if (choice.type === 'SELECT_CARD_FROM_HAND' && choice.choiceId.startsWith('eque-port-card-')) {
        const cardId = command.selectedIds[0];
        const player = state.players[playerId];
        const newEvents: GameEvent[] = [];
        // Descartar la carta elegida
        newEvents.push({
          type: 'CARD_MOVED', cardInstanceId: cardId,
          from: 'HAND', to: 'WEAR_PILE', seq: reg.nextSeq(),
        });
        // Robar 1 carta
        if (player.abilityDeck.length > 0) {
          newEvents.push({
            type: 'CARDS_DRAWN', playerId, count: 1,
            cardInstanceIds: [player.abilityDeck[0].instanceId], seq: reg.nextSeq(),
          });
        }
        // +1 da├▒o a cada enemigo del campo
        for (const enemy of state.battlefield) {
          newEvents.push({
            type: 'MODIFIER_ADDED',
            modifierId: `eque-dmg-${reg.nextSeq()}`,
            targetId: enemy.instanceId,
            layer: 'ENEMY_OUTGOING_DAMAGE',
            amount: 1,
            duration: 'UNTIL_END_OF_TURN',
            seq: reg.nextSeq(),
          });
        }
        events.push(...newEvents);
        let resolvedState = state;
        for (const ev of newEvents) {
          resolvedState = applyEvent(resolvedState, ev);
        }
        state = {
          ...resolvedState,
          pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
        };
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // Portal de Ulthar: SELECT_ENEMY con choiceId "ulthar-enemy-" (tras pago)
      if (choice.type === 'SELECT_ENEMY' && choice.choiceId.startsWith('ulthar-enemy-')) {
        const enemyId = command.selectedIds[0];
        const player = state.players[playerId];
        const newEvents: GameEvent[] = [];
        // Devolver Hueste al fondo del mazo
        newEvents.push({
          type: 'CARD_MOVED', cardInstanceId: enemyId,
          from: 'BATTLEFIELD', to: 'HORDE_DECK', seq: reg.nextSeq(),
        });
        events.push(...newEvents);
        let resolvedState = state;
        for (const ev of newEvents) {
          resolvedState = applyEvent(resolvedState, ev);
        }
        // Crear eleccion para trofeo a colocar
        if (player.trophies.length > 0) {
          const trophyChoice: PendingChoice = {
            choiceId: `ulthar-trophy-${reg.nextSeq()}`,
            playerId,
            type: 'CONFIRM',
            prompt: 'Portal de Ulthar: Elige un trofeo para colocarlo en el campo',
            options: player.trophies,
            minSelections: 1,
            maxSelections: 1,
          };
          state = {
            ...resolvedState,
            pendingChoices: [
              ...resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
              trophyChoice,
            ],
          };
        } else {
          state = {
            ...resolvedState,
            pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
          };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // Portal de Ulthar: CONFIRM con choiceId "ulthar-trophy-" (elegir trofeo)
      if (choice.type === 'CONFIRM' && choice.choiceId.startsWith('ulthar-trophy-')) {
        const trophyInstanceId = command.selectedIds[0];
        // D397: trophies guarda instanceId, buscar definitionId en el mazo de la Horda
        const trophyCard = state.hordeDeck.find(c => c.instanceId === trophyInstanceId);
        const trophyDefId = trophyCard?.definitionId ?? trophyInstanceId;
        const trophyDef = catalog?.byId.get(trophyDefId);
        const newEvents: GameEvent[] = [];
        if (trophyDef) {
          // Revelar trofeo como enemigo en el campo
          newEvents.push({
            type: 'ENEMY_REVEALED', enemyInstanceId: `trophy-${trophyInstanceId}-${reg.nextSeq()}`,
            definitionId: trophyDefId, fortitude: trophyDef.printedFortitude ?? 1, seq: reg.nextSeq(),
          });
        }
        events.push(...newEvents);
        let resolvedState = state;
        for (const ev of newEvents) {
          resolvedState = applyEvent(resolvedState, ev);
        }
        // Remover trofeo del jugador
        resolvedState = {
          ...resolvedState,
          players: {
            ...resolvedState.players,
            [playerId]: {
              ...resolvedState.players[playerId],
              trophies: resolvedState.players[playerId].trophies.filter(t => t !== trophyInstanceId),
            },
          },
          pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId),
        };
        state = resolvedState;
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // D371: REACTION_WINDOW ÔÇö el jugador elige usar pericia o pasar
      if (choice.type === 'REACTION_WINDOW') {
        const selection = command.selectedIds[0];
        // Remover la elecci├│n pendiente
        state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        if (selection === 'PASS') {
          // No hacer nada, solo resolver la elecci├│n
          return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
        }
        if (selection === 'USE_ABILITY') {
          // El jugador quiere usar su pericia; crear una elecci├│n SELECT_HERO
          // para que elija el objetivo (Val├¿rys/Lisavette)
          const otherHeroes = state.playerOrder.filter(id => id !== playerId);
          state = {
            ...state,
            pendingChoices: [...state.pendingChoices, {
              choiceId: `reaction-hero-${playerId}-${reg.nextSeq()}`,
              playerId,
              type: 'SELECT_HERO' as const,
              prompt: 'Selecciona el heroe objetivo de tu pericia',
              options: otherHeroes,
              minSelections: 1,
              maxSelections: 1,
            }],
          };
          return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // D371: SELECT_HERO originado de ventana de reacci├│n ÔåÆ invocar useHeroAbility
      if (choice.type === 'SELECT_HERO' && !choice.resolutionContext && choice.choiceId.startsWith('reaction-hero-')) {
        const targetHeroId = command.selectedIds[0];
        if (targetHeroId && catalog) {
          const abilityResult = useHeroAbility(state, playerId, rng, catalog, targetHeroId);
          events.push(...abilityResult.events);
          let resolvedState = abilityResult.state;
          for (const ev of abilityResult.events) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // D370: SELECT_ENEMY originado de Lisavette ÔåÆ invocar useHeroAbility con ambos targets
      if (choice.type === 'SELECT_ENEMY' && choice.choiceId.startsWith('lisavette-enemy-') && choice.resolutionContext?.chosenHeroTarget) {
        const targetHeroId = choice.resolutionContext.chosenHeroTarget;
        const targetEnemyId = command.selectedIds[0];
        if (targetEnemyId && catalog) {
          const abilityResult = useHeroAbility(state, playerId, rng, catalog, targetHeroId, targetEnemyId);
          events.push(...abilityResult.events);
          let resolvedState = abilityResult.state;
          for (const ev of abilityResult.events) {
            resolvedState = applyEvent(resolvedState, ev);
          }
          state = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        } else {
          state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        }
        return { accepted: true, events, newState: { ...state, rngState: rng.serialize() }, rng };
      }

      // Recuperar la carta original del contexto
      const card = state.players[playerId].hand.find(c => c.instanceId === choice.resolutionContext?.currentCardInstanceId)
        ?? state.players[playerId].wearPile.find(c => c.instanceId === choice.resolutionContext?.currentCardInstanceId);
      if (!card || !choice.resolutionContext) {
        // Limpiar la eleccion pendiente
        state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        break;
      }
      const cardDef = catalog?.byId.get(card.definitionId);
      if (!cardDef || !catalog) {
        state = { ...state, pendingChoices: state.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
        break;
      }
      // Determinar los targets elegidos
      const chosenHero = choice.type === 'SELECT_HERO' ? command.selectedIds[0] : null;
      const chosenEnemy = choice.type === 'SELECT_ENEMY' ? command.selectedIds[0] : null;
      const chosenWear = choice.type === 'SELECT_CARD_FROM_WEAR' ? command.selectedIds[0] : null;
      // Re-resolver la carta con la eleccion
      const result = resolveCard(
        state, card, cardDef, choice.resolutionContext.selectedEnemyId,
        state.players[playerId], rng, reg, catalog,
        chosenHero, chosenEnemy, chosenWear,
      );
      // Aplicar eventos
      let resolvedState = state;
      for (const ev of result.events) {
        resolvedState = applyEvent(resolvedState, ev);
      }
      // Limpiar la eleccion pendiente
      resolvedState = { ...resolvedState, pendingChoices: resolvedState.pendingChoices.filter(c => c.choiceId !== command.choiceId) };
      return { accepted: true, events: result.events, newState: { ...resolvedState, rngState: rng.serialize() }, rng };
    }

    default:
      // Comandos no manejados aqu├¡ (START_GAME, CHOOSE_LEADER_CARDS, SELECT_TARGET, etc.)
      return { accepted: false, reason: 'Command not supported', events, newState: state, rng };
  }

  // 4. Aplicar eventos al estado (reducer puro)
  let newState = state;
  for (const event of events) {
    newState = applyEvent(newState, event);
  }

  // Actualizar rngState en el estado (especificacion ┬º51.5)
  newState = { ...newState, rngState: rng.serialize() };

  return {
    accepted: true,
    events,
    newState,
    rng,
  };
}

function getPlayerIdFromCommand(_command: Command, state: GameState): string {
  // El playerId viene implicito en el comando o es el activo
  // En una implementacion real, el playerId se extrae del contexto WebSocket
  return state.activePlayerId;
}

/**
 * EffectRegistry ÔÇö registro de handlers para cada tipo de CardEffect.
 *
 * El motor despacha por effect.type, no por nombre de carta.
 * Esto permite que las cartas personalizadas usen los mismos efectos
 * sin necesidad de programar codigo nuevo.
 */

import type {
  CardEffect,
  Condition,
  ValueExpr,
  TargetSelector,
  HeroSelector,
  GameState,
  GameEvent,
  ResolutionContext,
  EnemyState,
  Zone,
} from '@nt4h/schema';

import type { DeterministicRng } from '../rng/index.js';
import type { EventBus } from '../triggers/index.js';
import { getEffectiveFortitude, getEnemyDamageBonus } from '../modifiers/index.js';
import { applyDamageModifiers } from './resolver.js';

export type EffectHandler<E extends CardEffect = CardEffect> = (
  effect: E,
  ctx: ResolutionContext,
  state: GameState,
  rng: DeterministicRng,
  eventBus: EventBus,
) => GameEvent[];

/** Extrae el tipo especifico de CardEffect dado su discriminador */
type EffectOfType<T extends string> = Extract<CardEffect, { type: T }>;

export class EffectRegistry {
  private handlers = new Map<string, EffectHandler<any>>();
  private seqCounter = 0;

  register<T extends CardEffect['type']>(
    type: T,
    handler: EffectHandler<EffectOfType<T>>,
  ): void {
    this.handlers.set(type, handler as EffectHandler<any>);
  }

  execute(
    effect: CardEffect,
    ctx: ResolutionContext,
    state: GameState,
    rng: DeterministicRng,
    eventBus: EventBus,
  ): GameEvent[] {
    const handler = this.handlers.get(effect.type);
    if (!handler) {
      throw new Error(`Unknown effect type: ${effect.type}`);
    }
    return handler(effect, ctx, state, rng, eventBus);
  }

  nextSeq(): number {
    return ++this.seqCounter;
  }

  resetSeq(): void {
    this.seqCounter = 0;
  }
}

// ============================================================================
// Evaluadores de ValueExpr
// ============================================================================

export function evalValue(
  expr: ValueExpr,
  ctx: ResolutionContext,
  state: GameState,
): number {
  switch (expr.kind) {
    case 'CONSTANT':
      return expr.value;

    case 'COUNT_LIVING_ENEMIES':
      return state.battlefield.length;

    case 'COUNT_ENEMIES_IN_FIELD':
      return state.battlefield.length;

    case 'FORTITUDE_OF': {
      const targetId = resolveTarget(expr.target, ctx, state);
      if (!targetId) return 0;
      const enemy = state.battlefield.find(e => e.instanceId === targetId);
      return enemy ? enemy.baseFortitude : 0;
    }

    case 'SUM':
      return expr.of.reduce((acc, sub) => acc + evalValue(sub, ctx, state), 0);

    case 'MULTIPLY':
      return expr.factors.reduce((acc, sub) => acc * evalValue(sub, ctx, state), 1);

    case 'EVASION_DISCARDED_COUNT':
      // Numero de cartas descartadas en la evasion actual
      // Se lee del contexto de resoluci├│n o del estado temporal
      return (ctx as any).evasionDiscardedCount ?? (state as any).evasionDiscardedCount ?? 0;

    case 'FLOOR_DIV':
      return Math.floor(evalValue(expr.numerator, ctx, state) / expr.denominator);

    default: {
      const _exhaustive: never = expr;
      void _exhaustive;
      return 0;
    }
  }
}

// ============================================================================
// Evaluadores de Condition
// ============================================================================

export function evalCondition(
  condition: Condition,
  ctx: ResolutionContext,
  state: GameState,
): boolean {
  switch (condition.kind) {
    case 'FIRST_CARD_OF_NAME_THIS_TURN':
      // Buscar por nombre exacto (applyEvent indexa por nombre y definitionId)
      return (ctx.cardsPlayedThisTurn[condition.name] ?? 0) === 0;

    case 'ALREADY_USED_AGAINST_THIS_ENEMY': {
      if (!ctx.selectedEnemyId) return false;
      const enemyMap = ctx.cardsPlayedAgainstEnemy[ctx.selectedEnemyId];
      if (!enemyMap) return false;
      return (enemyMap[condition.name] ?? 0) > 0;
    }

    case 'ENEMY_DEFEATED_BY_THIS_CARD':
      return ctx.selectedEnemyId !== null &&
             ctx.enemiesDefeatedThisResolution.includes(ctx.selectedEnemyId);

    case 'HAS_CAPABILITY': {
      const player = state.players[ctx.activePlayerId];
      return player.capabilities.includes(condition.icon);
    }

    case 'ENEMY_FORTITUDE_GTE': {
      if (!ctx.selectedEnemyId) return false;
      const enemy = state.battlefield.find(e => e.instanceId === ctx.selectedEnemyId);
      return enemy ? enemy.baseFortitude >= condition.value : false;
    }

    case 'NOT':
      return !evalCondition(condition.condition, ctx, state);

    case 'AND':
      return condition.conditions.every(c => evalCondition(c, ctx, state));

    case 'OR':
      return condition.conditions.some(c => evalCondition(c, ctx, state));

    default: {
      const _exhaustive: never = condition;
      void _exhaustive;
      return false;
    }
  }
}

// ============================================================================
// Resolucion de selectores
// ============================================================================

export function resolveTarget(
  selector: TargetSelector,
  ctx: ResolutionContext,
  state: GameState,
): string | null {
  switch (selector.kind) {
    case 'ONE_ENEMY':
    case 'SELECTED_ENEMY': {
      const targetId = ctx.selectedEnemyId;
      if (!targetId) return null;
      // Validar filter si existe
      if (selector.kind === 'ONE_ENEMY' && selector.filter) {
        const enemy = state.battlefield.find(e => e.instanceId === targetId);
        if (!enemy) return null;
        const f = selector.filter;
        if (f.minFortitude !== undefined && getEffectiveFortitude(enemy, state) < f.minFortitude) return null;
        if (f.isOrc !== undefined && enemy.isOrc !== f.isOrc) return null;
        if (f.isWarlord !== undefined && enemy.isWarlord !== f.isWarlord) return null;
      }
      return targetId;
    }

    case 'ALL_ENEMIES':
      return null; // ALL_ENEMIES se maneja de forma especial en el handler

    case 'ENEMY_WITH_MAX_FORTITUDE': {
      if (state.battlefield.length === 0) return null;
      // Si el jugador ya eligi├│ (via pendingChoice), usar esa elecci├│n
      if (ctx.chosenEnemyTarget) {
        const chosen = state.battlefield.find(e => e.instanceId === ctx.chosenEnemyTarget);
        if (chosen) return chosen.instanceId;
      }
      // Usar getEffectiveFortitude (no baseFortitude) para respetar modificadores
      const max = state.battlefield.reduce((best, e) =>
        getEffectiveFortitude(e, state) > getEffectiveFortitude(best, state) ? e : best
      );
      return max.instanceId;
    }

    case 'ENEMY_WITH_FEWEST_WOUNDS': {
      if (state.battlefield.length === 0) return null;
      const min = state.battlefield.reduce((best, e) =>
        e.wounds < best.wounds ? e : best
      );
      return min.instanceId;
    }

    default: {
      const _exhaustive: never = selector;
      void _exhaustive;
      return null;
    }
  }
}

export function resolveHeroTargets(
  selector: HeroSelector,
  ctx: ResolutionContext,
  state: GameState,
): string[] {
  switch (selector.kind) {
    case 'SELF':
      return [ctx.activePlayerId];

    case 'ALL_OTHERS':
    case 'EACH_OTHER':
      return state.playerOrder.filter(id => id !== ctx.activePlayerId);

    case 'HERO_WITH_FEWEST_WOUNDS': {
      // Lluvia de Flechas: da├▒a al h├®roe con menos Heridas, incluyendo al activo
      // En empate, el jugador elige (via pendingChoice); si no hay choice, preferir al activo
      if (ctx.chosenHeroTarget) return [ctx.chosenHeroTarget];
      const all = state.playerOrder;
      if (all.length === 0) return [];
      const minWounds = Math.min(...all.map(id => state.players[id].wounds));
      const candidates = all.filter(id => state.players[id].wounds === minWounds);
      if (candidates.length === 1) return [candidates[0]];
      // Fallback sin UI: preferir al jugador activo
      if (candidates.includes(ctx.activePlayerId)) return [ctx.activePlayerId];
      return [candidates[0]];
    }

    case 'OTHER_HERO':
      return state.playerOrder.filter(id => id !== ctx.activePlayerId);

    default: {
      const _exhaustive: never = selector;
      void _exhaustive;
      return [];
    }
  }
}

/**
 * Aplicar dano a un heroe: perdida de cartas del mazo, con reciclaje de Desgaste
 * y herida si el mazo se agota (igual que el ataque de la Horda).
 */
export function applyHeroDamage(
  playerId: string,
  amount: number,
  state: GameState,
  rng: DeterministicRng,
  nextSeqFn: () => number,
): GameEvent[] {
  const player = state.players[playerId];
  const events: GameEvent[] = [];
  let remaining = amount;
  let deck = [...player.abilityDeck];
  let wear = [...player.wearPile];
  let wounds = player.wounds;
  let pendingLost: string[] = [];

  while (remaining > 0) {
    if (deck.length === 0) {
      // D372: Si no hay Desgaste para reciclar, no se puede herir ni perder cartas
      if (wear.length === 0) break;
      if (pendingLost.length > 0) {
        events.push({
          type: 'CARDS_LOST' as const,
          playerId,
          count: pendingLost.length,
          cardInstanceIds: pendingLost,
          seq: nextSeqFn(),
        });
        pendingLost = [];
      }
      wounds++;
      events.push({
        type: 'HERO_WOUNDED' as const,
        playerId,
        woundCount: wounds,
        seq: nextSeqFn(),
      });
      deck = rng.shuffle([...wear]);
      wear = [];
      events.push({
        type: 'DECK_RESHUFFLED' as const,
        playerId,
        newDeckSize: deck.length,
        newOrder: deck.map(c => c.instanceId),
        seq: nextSeqFn(),
      });
    }
    const lost = deck.slice(0, remaining).map(c => c.instanceId);
    pendingLost.push(...lost);
    const lostCards = deck.slice(0, remaining);
    wear = [...wear, ...lostCards.map(c => ({ ...c, zone: 'WEAR_PILE' as Zone }))];
    deck = deck.slice(lost.length);
    remaining -= lost.length;
  }
  if (pendingLost.length > 0) {
    events.push({
      type: 'CARDS_LOST' as const,
      playerId,
      count: pendingLost.length,
      cardInstanceIds: pendingLost,
      seq: nextSeqFn(),
    });
  }
  return events;
}

// ============================================================================
// Registro de handlers core
// ============================================================================

export function registerCoreEffects(registry: EffectRegistry): void {
  // --- Dano ---
  registry.register('DEAL_DAMAGE', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    // Aplicar vulnerabilidad del enemigo (Flecha Corrosiva)
    const enemy = state.battlefield.find(e => e.instanceId === targetId);
    const bonus = enemy ? getEnemyDamageBonus(enemy) : 0;
    return [
      { type: 'DAMAGE_DEALT', targetId, amount: amount + bonus, sourceCardInstanceId: ctx.currentCardInstanceId, seq: registry.nextSeq() },
    ];
  });

  registry.register('DEAL_DAMAGE_ALL_ENEMIES', (eff, ctx, state) => {
    const baseAmount = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];
    const amount = player ? applyDamageModifiers(baseAmount, ctx.currentCardName, player) : baseAmount;
    return state.battlefield.map(e => ({
      type: 'DAMAGE_DEALT' as const,
      targetId: e.instanceId,
      amount: amount + getEnemyDamageBonus(e),
      sourceCardInstanceId: ctx.currentCardInstanceId,
      seq: registry.nextSeq(),
    }));
  });

  registry.register('DEAL_DAMAGE_SPLIT', (eff, ctx, state) => {
    // Repartir amount dano entre targetCount enemigos
    const baseAmount = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];
    const amount = player ? applyDamageModifiers(baseAmount, ctx.currentCardName, player) : baseAmount;
    const count = eff.targetCount;
    // Resolver target selector para seleccionar los enemigos concretos
    let targets: EnemyState[] = [];
    switch (eff.target.kind) {
      case 'ALL_ENEMIES':
        targets = state.battlefield.slice(0, count);
        break;
      case 'ONE_ENEMY':
      case 'SELECTED_ENEMY': {
        const selected = state.battlefield.find(e => e.instanceId === ctx.selectedEnemyId);
        targets = selected ? [selected] : [];
        break;
      }
      case 'ENEMY_WITH_MAX_FORTITUDE': {
        if (state.battlefield.length > 0) {
          const sorted = [...state.battlefield].sort((a, b) =>
            getEffectiveFortitude(b, state) - getEffectiveFortitude(a, state)
          );
          targets = sorted.slice(0, count);
        }
        break;
      }
      case 'ENEMY_WITH_FEWEST_WOUNDS': {
        if (state.battlefield.length > 0) {
          const sorted = [...state.battlefield].sort((a, b) => a.wounds - b.wounds);
          targets = sorted.slice(0, count);
        }
        break;
      }
      default:
        targets = state.battlefield.slice(0, count);
    }
    if (targets.length === 0) return [];
    // Usar targetCount (del cat├ílogo) para calcular da├▒o por target, no targets.length
    // As├¡ "2 a 2 enemigos" (amount=4, targetCount=2) = 2 por enemigo, incluso si solo hay 1
    const divisor = count;
    const perTarget = Math.floor(amount / divisor);
    const remainder = amount % divisor;
    return targets.map((e, i) => ({
      type: 'DAMAGE_DEALT' as const,
      targetId: e.instanceId,
      amount: perTarget + (i < remainder ? 1 : 0) + getEnemyDamageBonus(e),
      sourceCardInstanceId: ctx.currentCardInstanceId,
      seq: registry.nextSeq(),
    }));
  });

  registry.register('DEAL_DAMAGE_TO_HERO', (eff, ctx, state, rng) => {
    const amount = evalValue(eff.amount, ctx, state);
    const targets = resolveHeroTargets(eff.target, ctx, state);
    // El dano a heroes se convierte en perdida de cartas (con herida/reciclaje si mazo vacio)
    return targets.flatMap(targetId => applyHeroDamage(targetId, amount, state, rng, () => registry.nextSeq()));
  });

  registry.register('DEAL_DAMAGE_TO_OTHER_HEROES', (eff, ctx, state, rng) => {
    const amount = evalValue(eff.amount, ctx, state);
    const others = state.playerOrder.filter(id => id !== ctx.activePlayerId);
    return others.flatMap(targetId => applyHeroDamage(targetId, amount, state, rng, () => registry.nextSeq()));
  });

  // --- Prevencion ---
  registry.register('PREVENT_DAMAGE', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    return [{
      type: 'PREVENTION_APPLIED',
      playerId: ctx.activePlayerId,
      amount,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('SHIELD', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    return [{
      type: 'SHIELD_PLACED',
      playerId: ctx.activePlayerId,
      amount,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('CANCEL_ALL_DAMAGE', (_eff, ctx, _state) => {
    return [{
      type: 'CANCELLATION_ACTIVATED',
      playerId: ctx.activePlayerId,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('PREVENT_ENEMY_DAMAGE', (eff, ctx, state) => {
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    return [{
      type: 'ENEMY_DAMAGE_DISABLED',
      enemyInstanceId: targetId,
      seq: registry.nextSeq(),
    }];
  });

  // --- Cartas ---
  registry.register('DRAW_CARDS', (eff, ctx, state) => {
    const count = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];
    const source = eff.source ?? 'ABILITY_DECK';
    const drawn: string[] = [];

    if (source === 'SUPPORT_DECK') {
      // Robar del primer mazo de Apoyo disponible (sin mutar el estado)
      const supportDeck = player.supportDecks?.find(d => d.length > 0);
      if (supportDeck) {
        drawn.push(...supportDeck.slice(0, count).map(c => c.instanceId));
      }
    } else {
      // Usar slice para evitar acceso fuera de rango
      drawn.push(...player.abilityDeck.slice(0, count).map(c => c.instanceId));
    }

    if (drawn.length === 0) return [];

    return [{
      type: 'CARDS_DRAWN',
      playerId: ctx.activePlayerId,
      count: drawn.length,
      cardInstanceIds: drawn,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('LOSE_CARDS', (eff, ctx, state, rng) => {
    const count = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];

    // Si el mazo tiene suficientes cartas, perder normalmente
    if (player.abilityDeck.length >= count) {
      const lost = player.abilityDeck.slice(0, count).map(c => c.instanceId);
      return [{
        type: 'CARDS_LOST',
        playerId: ctx.activePlayerId,
        count: lost.length,
        cardInstanceIds: lost,
        seq: registry.nextSeq(),
      }];
    }

    // Mazo agotado o insuficiente: usar applyHeroDamage para reciclaje + herida
    if (count > 0) {
      return applyHeroDamage(ctx.activePlayerId, count, state, rng, () => registry.nextSeq());
    }
    return [];
  });

  registry.register('RECOVER_CARDS', (eff, ctx, state) => {
    const count = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];
    // Recuperar de la parte INFERIOR del desgaste (las cartas mas antiguas)
    const recovered = player.wearPile.slice(0, count).map(c => c.instanceId);

    if (recovered.length === 0) return [];

    return [{
      type: 'CARDS_RECOVERED',
      playerId: ctx.activePlayerId,
      count: recovered.length,
      cardInstanceIds: recovered,
      toZone: eff.to === 'BOTTOM_OF_DECK' ? 'ABILITY_DECK' : 'HAND',
      seq: registry.nextSeq(),
    }];
  });

  registry.register('ALL_HEROES_RECOVER', (eff, ctx, state) => {
    const count = evalValue(eff.amount, ctx, state);
    return state.playerOrder.flatMap(playerId => {
      const player = state.players[playerId];
      const recovered = player.wearPile.slice(0, count).map(c => c.instanceId);
      if (recovered.length === 0) return [];
      return [{
        type: 'CARDS_RECOVERED' as const,
        playerId,
        count: recovered.length,
        cardInstanceIds: recovered,
        toZone: 'ABILITY_DECK' as const,
        seq: registry.nextSeq(),
      }];
    });
  });

  registry.register('OTHER_HEROES_RECOVER', (eff, ctx, state) => {
    const count = evalValue(eff.amount, ctx, state);
    const others = state.playerOrder.filter(id => id !== ctx.activePlayerId);
    return others.flatMap(playerId => {
      const player = state.players[playerId];
      const recovered = player.wearPile.slice(0, count).map(c => c.instanceId);
      if (recovered.length === 0) return [];
      return [{
        type: 'CARDS_RECOVERED' as const,
        playerId,
        count: recovered.length,
        cardInstanceIds: recovered,
        toZone: 'ABILITY_DECK' as const,
        seq: registry.nextSeq(),
      }];
    });
  });

  // --- Recursos ---
  registry.register('GAIN_GLORY', (eff, ctx, _state) => {
    const amount = evalValue(eff.amount, ctx, _state);
    return [{
      type: 'GLORY_GAINED',
      playerId: ctx.activePlayerId,
      amount,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('GAIN_COINS', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    // Resolver target: DEFEATING_HERO, SELF, o HeroSelector
    let targetIds: string[] = [ctx.activePlayerId];
    if (eff.target === 'DEFEATING_HERO') {
      targetIds = [ctx.defeatingPlayerId ?? ctx.activePlayerId];
    } else if (eff.target === 'SELF' || eff.target === undefined) {
      targetIds = [ctx.activePlayerId];
    } else {
      // HeroSelector
      targetIds = resolveHeroTargets(eff.target, ctx, state);
    }
    return targetIds.map(playerId => ({
      type: 'COINS_GAINED' as const,
      playerId,
      amount,
      seq: registry.nextSeq(),
    }));
  });

  registry.register('IGNORE_COIN_REWARDS', (_eff, _ctx, _state) => {
    // Se maneja en applyScenarioEffects: marca ignoreCoinRewards
    return [];
  });

  registry.register('IGNORE_GLORY_REWARDS', (_eff, _ctx, _state) => {
    // Se maneja en applyScenarioEffects: marca ignoreGloryRewards
    return [];
  });

  registry.register('ON_ENEMY_DEFEATED', (eff: any, ctx, state, rng, eventBus) => {
    // ON_ENEMY_DEFEATED: efecto condicional al derrotar un enemigo.
    // Eval├║a condition.fortitudeGte contra la fortaleza del enemigo derrotado.
    const condition = eff.condition as { fortitudeGte?: number } | undefined;
    const innerEffects = eff.effects as any[] | undefined;
    if (!innerEffects || innerEffects.length === 0) return [];

    // ctx.lastDefeatedEnemyFortitude se establece desde el resolver
    const enemyFortitude = (ctx as any).lastDefeatedEnemyFortitude ?? 0;
    if (condition?.fortitudeGte !== undefined && enemyFortitude < condition.fortitudeGte) {
      return [];
    }

    // Ejecutar los efectos internos pasando rng y eventBus
    const events: GameEvent[] = [];
    for (const innerEff of innerEffects) {
      const innerEvents = registry.execute(innerEff, ctx, state, rng, eventBus);
      events.push(...innerEvents);
    }
    return events;
  });

  registry.register('STEAL_COINS', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    const targets = resolveHeroTargets(eff.from, ctx, state);
    // En modo solitario (sin otros h├®roes), robar de la reserva
    if (targets.length === 0) {
      return [{
        type: 'COINS_GAINED' as const,
        playerId: ctx.activePlayerId,
        amount,
        seq: registry.nextSeq(),
      }];
    }
    return targets.map(fromId => ({
      type: 'COINS_STOLEN' as const,
      fromPlayerId: fromId,
      toPlayerId: ctx.activePlayerId,
      amount: Math.min(amount, state.players[fromId].coins),
      seq: registry.nextSeq(),
    }));
  });

  registry.register('HEAL_WOUNDS', (eff, ctx, _state) => {
    const amount = evalValue(eff.amount, ctx, _state);
    return [{
      type: 'WOUND_HEALED',
      playerId: ctx.activePlayerId,
      amount,
      seq: registry.nextSeq(),
    }];
  });

  // --- Control de flujo ---
  registry.register('CONDITIONAL', (eff, ctx, state, rng, bus) => {
    if (evalCondition(eff.condition, ctx, state)) {
      return eff.then.flatMap(e => registry.execute(e, ctx, state, rng, bus));
    }
    return eff.else?.flatMap(e => registry.execute(e, ctx, state, rng, bus)) ?? [];
  });

  registry.register('END_ATTACK', (_eff, _ctx, _state) => {
    // Senala fin del enfrentamiento; el motor de fases lo procesara
    return [];
  });

  // --- Enemigos ---
  registry.register('DISABLE_ENEMY_DAMAGE', (eff, ctx, state) => {
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    return [{
      type: 'ENEMY_DAMAGE_DISABLED',
      enemyInstanceId: targetId,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('APPLY_VULNERABILITY', (eff, ctx, state) => {
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    const bonus = evalValue(eff.bonus, ctx, state);
    return [{
      type: 'VULNERABILITY_APPLIED',
      enemyInstanceId: targetId,
      bonus,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('DEFEAT_ENEMY', (eff, ctx, state) => {
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    const enemy = state.battlefield.find(e => e.instanceId === targetId);
    if (!enemy) return [];

    let reward = eff.loot ? (enemy.reward ?? { coins: 0, glory: 0 }) : { coins: 0, glory: 0 };
    // Respetar modificadores de escenario (IGNORE_COIN/GLORY_REWARDS)
    if (state.ignoreCoinRewards) reward = { ...reward, coins: 0 };
    if (state.ignoreGloryRewards) reward = { ...reward, glory: 0 };
    return [{
      type: 'ENEMY_DEFEATED',
      enemyInstanceId: targetId,
      enemyDefinitionId: enemy.definitionId,
      defeatingPlayerId: ctx.activePlayerId,
      reward,
      seq: registry.nextSeq(),
    }];
  });

  // --- Especiales ---
  registry.register('REMOVE_FROM_GAME', (_eff, ctx, _state) => {
    return [{
      type: 'CARD_REMOVED_FROM_GAME',
      cardInstanceId: ctx.currentCardInstanceId,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('PLACE_PERSISTENT', (eff, ctx, _state) => {
    return [{
      type: 'PERSISTENT_CARD_PLACED',
      playerId: ctx.activePlayerId,
      cardInstanceId: ctx.currentCardInstanceId,
      cardDefinitionId: ctx.currentCardId,
      trigger: eff.trigger,
      seq: registry.nextSeq(),
    }];
  });

  registry.register('COST', (eff, ctx, state) => {
    const amount = evalValue(eff.amount, ctx, state);
    const player = state.players[ctx.activePlayerId];
    if (!player) return [];
    if (eff.resource === 'COINS') {
      // Validar que hay monedas suficientes
      if (player.coins < amount) return [];
      return [{
        type: 'COINS_GAINED',
        playerId: ctx.activePlayerId,
        amount: -amount,
        seq: registry.nextSeq(),
      }];
    } else {
      // GLORY: usar GLORY_LOST (no GLORY_GAINED negativo)
      if (player.glory < amount) return [];
      return [{
        type: 'GLORY_LOST',
        playerId: ctx.activePlayerId,
        amount,
        seq: registry.nextSeq(),
      }];
    }
  });

  // DRAW_AND_CHECK, PLAY_IMMEDIATELY, MODIFY_DAMAGE, etc.
  // se manejan en el motor de resolucion con logica especial
  registry.register('DRAW_AND_CHECK', (_eff, _ctx, _state) => {
    // Manejado por el motor de resolucion (necesita logica de cadena)
    return [];
  });

  registry.register('DRAW_AND_ADD_ATTACK', (_eff, _ctx, _state) => {
    // Manejado por el motor de resolucion (logica especial en resolver.ts)
    return [];
  });

  registry.register('PLAY_IMMEDIATELY', (_eff, _ctx, _state) => {
    // Manejado por el motor de resolucion
    return [];
  });

  registry.register('CUSTOM_SCENARIO', (_eff, _ctx, _state) => {
    // Los handlers reales estan en scenarios/index.ts (applyScenarioEffects, onTurnStart, etc.)
    return [];
  });

  registry.register('RECOVER_THIS_CARD', (eff, ctx, _state) => {
    return [{
      type: 'CARDS_RECOVERED',
      playerId: ctx.activePlayerId,
      count: 1,
      cardInstanceIds: [ctx.currentCardInstanceId],
      toZone: eff.to === 'HAND' ? 'HAND' : 'ABILITY_DECK',
      seq: registry.nextSeq(),
    }];
  });

  // === Handlers para efectos especiales ===

  // ON_DEFEAT: los efectos al derrotar se procesan en el resolver,
  // no aqui. Este handler es un no-op para efectos sueltos.
  registry.register('ON_DEFEAT', (_eff, _ctx, _state) => []);

  // ON_HORDE_ATTACK: los efectos reactivos al ataque de la Horda
  // se procesan via EventBus. Este handler es un no-op.
  registry.register('ON_HORDE_ATTACK', (_eff, _ctx, _state) => []);

  // MODIFY_DAMAGE: anade un modificador de dano al jugador activo
  // (ej: Piedra de Amolar: +1 al dano de cartas este turno)
  registry.register('MODIFY_DAMAGE', (eff, ctx, state) => {
    const amount = evalValue(eff.modifier, ctx, state);
    return [{
      type: 'MODIFIER_ADDED',
      modifierId: `dmg-mod-${registry.nextSeq()}`,
      targetId: ctx.activePlayerId,
      layer: 'DAMAGE_BONUS',
      amount,
      scope: eff.scope,
      filter: eff.filter,
      seq: registry.nextSeq(),
    }];
  });

  // MODIFY_FORTITUDE: anade un modificador de fortaleza a un enemigo
  // (ej: Ruinas de Brunmar: -1 a todos; Roghkiller: +1 a orcos)
  registry.register('MODIFY_FORTITUDE', (eff, ctx, state) => {
    const amount = evalValue(eff.modifier, ctx, state);
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    return [{
      type: 'MODIFIER_ADDED',
      modifierId: `fort-mod-${registry.nextSeq()}`,
      targetId,
      layer: 'FORTITUDE_MODIFIERS',
      amount,
      duration: eff.duration,
      seq: registry.nextSeq(),
    }];
  });

  // MODIFY_MARKET_COST: modificador global de coste de mercado
  // (ej: Mercado de Lotharion: -1 a todos los articulos)
  registry.register('MODIFY_MARKET_COST', (eff, ctx, state) => {
    const modifier = evalValue(eff.modifier, ctx, state);
    return [{
      type: 'MODIFIER_ADDED',
      modifierId: `market-cost-${registry.nextSeq()}`,
      targetId: 'market',
      layer: 'MARKET_COST',
      amount: modifier,
      sourceId: ctx.currentCardInstanceId,
      duration: 'WHILE_SOURCE_ACTIVE',
      seq: registry.nextSeq(),
    }];
  });

  // SHUFFLE_DECK: barajar el mazo de habilidad o mercado
  registry.register('SHUFFLE_DECK', (eff, ctx, state, rng) => {
    const player = state.players[ctx.activePlayerId];
    if (eff.deck === 'ABILITY') {
      const shuffled = rng.shuffle(player.abilityDeck);
      return [{
        type: 'DECK_SHUFFLED',
        playerId: ctx.activePlayerId,
        deck: 'ABILITY',
        newOrder: shuffled.map(c => c.instanceId),
        seq: registry.nextSeq(),
      }];
    }
    if (eff.deck === 'MARKET') {
      // Barajar el mazo de Mercado (Pericia de Neddia)
      const shuffled = rng.shuffle(state.marketDeck);
      return [{
        type: 'DECK_SHUFFLED',
        playerId: ctx.activePlayerId,
        deck: 'MARKET',
        newOrder: shuffled.map(c => c.instanceId),
        seq: registry.nextSeq(),
      }];
    }
    if (eff.deck === 'HORDE') {
      const shuffled = rng.shuffle(state.hordeDeck);
      return [{
        type: 'DECK_SHUFFLED',
        playerId: ctx.activePlayerId,
        deck: 'HORDE',
        newOrder: shuffled.map(c => c.instanceId),
        seq: registry.nextSeq(),
      }];
    }
    return [];
  });

  // SEARCH_DECK: buscar una carta en el mazo y ponerla en mano o intercambiar
  // (ej: Aranel: buscar en mazo y sustituir por una de mano)
  registry.register('SEARCH_DECK', (eff, ctx, state) => {
    const player = state.players[ctx.activePlayerId];
    // Determinar el mazo objetivo (ABILITY por defecto, MARKET si se especifica)
    const deck = eff.deck === 'MARKET' ? state.marketDeck : player.abilityDeck;
    // Buscar la primera carta que cumpla el filtro
    const foundIdx = deck.findIndex(c => {
      const filter = eff.filter as any;
      if (filter.name) {
        const cName = (c as any).name ?? '';
        if (cName !== filter.name && c.definitionId !== filter.name) return false;
      }
      if (filter.definitionId) {
        if (c.definitionId !== filter.definitionId) return false;
      }
      // Si no hay filtros, coincide con cualquier carta (toma la primera)
      return true;
    });
    if (foundIdx === -1) return [];

    const foundCard = deck[foundIdx];
    const fromZone: Zone = eff.deck === 'MARKET' ? 'MARKET_DECK' : 'ABILITY_DECK';
    if (eff.action === 'PUT_IN_HAND') {
      return [{
        type: 'CARD_MOVED',
        cardInstanceId: foundCard.instanceId,
        from: fromZone,
        to: 'HAND',
        seq: registry.nextSeq(),
      }];
    }
    // SWAP_WITH_HAND: intercambiar con la primera carta de mano
    if (player.hand.length > 0) {
      const handCard = player.hand[0];
      return [
        {
          type: 'CARD_MOVED' as const,
          cardInstanceId: handCard.instanceId,
          from: 'HAND' as const,
          to: fromZone,
          seq: registry.nextSeq(),
        },
        {
          type: 'CARD_MOVED' as const,
          cardInstanceId: foundCard.instanceId,
          from: fromZone,
          to: 'HAND' as const,
          seq: registry.nextSeq(),
        },
      ];
    }
    return [];
  });

  // SEARCH_WEAR_PILE_PUT_IN_HAND: buscar en pila de desgaste y poner en mano
  // (ej: Vial de Conjuracion)
  registry.register('SEARCH_WEAR_PILE_PUT_IN_HAND', (_eff, ctx, state) => {
    const player = state.players[ctx.activePlayerId];
    if (player.wearPile.length === 0) return [];
    // Si el jugador eligi├│ una carta concreta, usarla; si no, tomar la mas reciente
    const card = ctx.chosenWearCardId
      ? player.wearPile.find(c => c.instanceId === ctx.chosenWearCardId)
      : player.wearPile[player.wearPile.length - 1];
    if (!card) return [];
    return [{
      type: 'CARD_MOVED',
      cardInstanceId: card.instanceId,
      from: 'WEAR_PILE',
      to: 'HAND',
      seq: registry.nextSeq(),
    }];
  });

  // RECOVER_CARD_BY_NAME: recuperar una carta por nombre de desgaste a fondo del mazo
  // (ej: Recoger Flechas: recuperar "Disparo rapido")
  registry.register('RECOVER_CARD_BY_NAME', (eff, ctx, state) => {
    const player = state.players[ctx.activePlayerId];
    // Normalizar: min├║sculas, sin tildes
    const normalize = (s: string) => s.toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    const targetName = normalize(eff.name);
    // Buscar desde el INICIO del desgaste (cartas m├ís antiguas = parte inferior)
    for (let i = 0; i < player.wearPile.length; i++) {
      const c = player.wearPile[i];
      if (c.name ? normalize(c.name) === targetName : normalize(c.definitionId).includes(targetName)) {
        return [{
          type: 'CARD_MOVED',
          cardInstanceId: c.instanceId,
          from: 'WEAR_PILE',
          to: 'ABILITY_DECK',
          seq: registry.nextSeq(),
        }];
      }
    }
    return [];
  });

  // SWAP_ENEMY: cambiar un enemigo del campo por uno del mazo de la Horda
  // (ej: Supervivencia)
  registry.register('SWAP_ENEMY', (eff, ctx, state) => {
    // Nota: el resolver intercepta SWAP_ENEMY antes de llegar aqui para acceder al catalogo.
    // Este handler es fallback si el resolver no lo intercepta.
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId || state.hordeDeck.length === 0) return [];
    const newEnemyCard = state.hordeDeck[state.hordeDeck.length - 1];
    return [
      {
        type: 'ENEMY_SWAPPED' as const,
        oldEnemyInstanceId: targetId,
        newEnemyInstanceId: newEnemyCard.instanceId,
        newEnemyDefinitionId: newEnemyCard.definitionId,
        newEnemyFortitude: 1,
        newEnemyReward: null,
        newEnemyIsOrc: false,
        newEnemyIsWarlord: false,
        newEnemySpecialIcons: [],
        seq: registry.nextSeq(),
      },
    ];
  });

  // RETURN_TO_HORDE: devolver un enemigo al mazo de la Horda
  // (ej: Lodazal de Kalern, Portal de Ulthar)
  registry.register('RETURN_TO_HORDE', (eff, ctx, state) => {
    const targetId = resolveTarget(eff.target, ctx, state);
    if (!targetId) return [];
    return [{
      type: 'ENEMY_RETURNED_TO_HORDE',
      enemyInstanceId: targetId,
      position: eff.position,
      seq: registry.nextSeq(),
    }];
  });

  // INTERCEPT_DAMAGE: interceptar dano de otro heroe
  // (ej: Valerys: recibir el dano de la Horda de otro heroe)
  registry.register('INTERCEPT_DAMAGE', (eff, ctx, state) => {
    // eff.from es un HeroSelector, no un string
    const fromIds = resolveHeroTargets(eff.from, ctx, state)
      .filter(id => id !== ctx.activePlayerId);
    if (fromIds.length === 0) return [];
    const fromPlayerId = fromIds[0];
    return [{
      type: 'DAMAGE_INTERCEPTED',
      interceptorPlayerId: ctx.activePlayerId,
      originalTargetPlayerId: fromPlayerId,
      amount: 0, // Se actualiza con el dano real en el motor de fases
      seq: registry.nextSeq(),
    }];
  });

  // LOOK_AT_CARDS: mirar cartas del mazo de la Horda y reordenar
  // (ej: Idril: mirar 3 cartas inferiores del mazo de la Horda)
  registry.register('LOOK_AT_CARDS', (eff, ctx, state) => {
    const count = evalValue(eff.amount, ctx, state);
    if (eff.deck !== 'HORDE') return [];
    // No genera eventos que cambien el estado directamente;
    // el reordenamiento se maneja como un evento especial
    const bottomCards = state.hordeDeck.slice(-count).map(c => c.instanceId);
    return [{
      type: 'CARDS_REVEALED_TO_PLAYER',
      playerId: ctx.activePlayerId,
      cardInstanceIds: bottomCards,
      deck: 'HORDE',
      seq: registry.nextSeq(),
    }];
  });

  // STEAL_COINS_MULTIPLE: robar monedas a multiples heroes
  // (ej: Yermo de Cemenmar: hasta 3 monedas, max 2 por heroe)
  registry.register('STEAL_COINS_MULTIPLE', (eff, ctx, state) => {
    const maxTotal = evalValue(eff.maxTotal ?? eff.max_total ?? { kind: 'CONSTANT', value: 0 }, ctx, state);
    const maxPerHero = evalValue(eff.maxPerHero ?? eff.max_per_hero ?? { kind: 'CONSTANT', value: 0 }, ctx, state);
    const events: GameEvent[] = [];
    let stolen = 0;
    for (const playerId of state.playerOrder) {
      if (playerId === ctx.activePlayerId) continue;
      if (stolen >= maxTotal) break;
      const otherPlayer = state.players[playerId];
      const canSteal = Math.min(maxPerHero, maxTotal - stolen, otherPlayer.coins);
      if (canSteal > 0) {
        events.push({
          type: 'COINS_STOLEN',
          fromPlayerId: playerId,
          toPlayerId: ctx.activePlayerId,
          amount: canSteal,
          seq: registry.nextSeq(),
        });
        stolen += canSteal;
      }
    }
    return events;
  });

  // PLAY_RANDOM_CARD_FROM_OTHER_HERO: jugar una carta aleatoria de otro h├®roe
  // (ej: L├ígrimas de Aradiel ÔÇö coste en Gloria)
  registry.register('PLAY_RANDOM_CARD_FROM_OTHER_HERO', (eff, ctx, state, rng) => {
    const costGlory = evalValue(eff.costGlory ?? eff.cost_glory ?? { kind: 'CONSTANT', value: 0 }, ctx, state);
    const player = state.players[ctx.activePlayerId];
    if (!player) return [];
    if (player.glory < costGlory) return []; // No hay gloria suficiente

    const events: GameEvent[] = [];
    // Pagar el coste de Gloria
    if (costGlory > 0) {
      events.push({
        type: 'GLORY_LOST',
        playerId: ctx.activePlayerId,
        amount: costGlory,
        seq: registry.nextSeq(),
      });
    }
    // Elegir un h├®roe aleatorio y robar una carta aleatoria de su mazo (usando RNG determinista)
    const otherPlayers = state.playerOrder
      .filter(pid => pid !== ctx.activePlayerId)
      .map(pid => state.players[pid])
      .filter(p => p.abilityDeck.length > 0);
    if (otherPlayers.length === 0) return events;
    const targetPlayer = rng.pick(otherPlayers);
    const drawnCard = rng.pick(targetPlayer.abilityDeck);
    // Mover la carta del mazo del otro h├®roe a la mano del jugador activo
    events.push({
      type: 'CARD_MOVED',
      cardInstanceId: drawnCard.instanceId,
      from: 'ABILITY_DECK',
      to: 'HAND',
      seq: registry.nextSeq(),
    });
    events.push({
      type: 'CARD_PLAYED',
      playerId: ctx.activePlayerId,
      cardInstanceId: drawnCard.instanceId,
      cardDefinitionId: drawnCard.definitionId,
      cardName: drawnCard.name,
      seq: registry.nextSeq(),
    });
    return events;
  });
}

/**
 * CardResolver ÔÇö motor de resolucion de cartas que integra EffectRegistry
 * con EventBus y maneja efectos especiales que requieren logica de cadena.
 *
 * Efectos especiales:
 * - DRAW_AND_CHECK: Disparo Rapido encadenado (robar y comprobar si es la misma carta)
 * - PLAY_IMMEDIATELY: jugar la carta robada inmediatamente
 * - PLACE_PERSISTENT: Trampa (carta permanente con disparador)
 * - ON_DEFEAT: efectos al derrotar un enemigo
 * - ON_HORDE_ATTACK: efectos reactivos al ataque de la Horda
 * - MODIFY_DAMAGE: Piedra de Amolar (modificador de dano del turno)
 * - MODIFY_FORTITUDE: Ruinas de Brunmar, Roghkiller (modificadores continuos)
 */

import type {
  GameState,
  GameEvent,
  CardEffect,
  CardDefinition,
  ResolutionContext,
  CardInstance,
  Zone,
  PlayerState,
  PendingChoice,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import { EffectRegistry, evalValue, resolveTarget, applyHeroDamage } from '../effects/registry.js';
import { EventBus, MAX_CHAIN_DEPTH, MAX_EFFECT_RECURSION } from '../triggers/index.js';
import { applyEvent } from '../events/applyEvent.js';
import { belethIlRapidShotRecovery } from '../heroes/abilities.js';
import { getEffectiveFortitude, getEnemyDamageBonus } from '../modifiers/index.js';
import { onEnemyDefeated as scenarioOnEnemyDefeated } from '../scenarios/index.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

let resolveSeq = 0;
function nextSeq(): number {
  return ++resolveSeq;
}
export function resetResolveSeq(): void {
  resolveSeq = 0;
}

/**
 * Helper: emitir ENEMY_DEFEATED + invocar efectos del escenario.
 * Usa enemiesDefeated como Set para evitar dobles.
 * Devuelve el estado actualizado y a├▒ade eventos a allEvents.
 */
function emitEnemyDefeated(
  currentState: GameState,
  enemyInstanceId: string,
  defeatingPlayerId: string,
  enemiesDefeated: string[],
  allEvents: GameEvent[],
  catalog: CatalogLoadResult,
  ctx?: ResolutionContext,
): GameState {
  if (enemiesDefeated.includes(enemyInstanceId)) return currentState;
  const enemy = currentState.battlefield.find(e => e.instanceId === enemyInstanceId);
  if (!enemy) return currentState;

  enemiesDefeated.push(enemyInstanceId);
  let finalReward = { ...(enemy.reward ?? { coins: 0, glory: 0 }) };
  if (currentState.ignoreCoinRewards) finalReward.coins = 0;
  if (currentState.ignoreGloryRewards) finalReward.glory = 0;

  allEvents.push({
    type: 'ENEMY_DEFEATED',
    enemyInstanceId,
    enemyDefinitionId: enemy.definitionId,
    defeatingPlayerId,
    reward: finalReward,
    seq: nextSeq(),
  });

  // Establecer lastDefeatedEnemyFortitude y defeatingPlayerId en el contexto para ON_ENEMY_DEFEATED
  const enemyFortitude = getEffectiveFortitude(enemy, currentState);
  if (ctx) {
    (ctx as any).lastDefeatedEnemyFortitude = enemyFortitude;
    (ctx as any).defeatingPlayerId = defeatingPlayerId;
  }

  // Ejecutar efectos ON_ENEMY_DEFEATED del escenario activo
  const scenarioDefId = currentState.scenario?.definitionId;
  if (scenarioDefId) {
    const scenarioEvents = scenarioOnEnemyDefeated(
      currentState,
      scenarioDefId,
      defeatingPlayerId,
      enemyFortitude,
      catalog,
    );
    allEvents.push(...scenarioEvents);
    for (const ev of scenarioEvents) {
      currentState = applyEventInline(currentState, ev);
    }
  }

  // Pericia de Roghkiller: al ser derrotado, eliminar su modificador de +1 a orcos
  const defeatedDef = catalog.byId.get(enemy.definitionId);
  if (defeatedDef?.name === 'Roghkiller') {
    currentState = {
      ...currentState,
      battlefield: currentState.battlefield.map(e => ({
        ...e,
        modifiers: e.modifiers.filter(m => m.sourceId !== 'roghkiller'),
      })),
    };
  }

  return currentState;
}

/**
 * Detectar empates en selectores que requieren eleccion del jugador.
 * Si hay empate, devuelve un PendingChoice para que el jugador decida.
 */
function detectTieForChoice(
  state: GameState,
  cardDef: CardDefinition,
  player: PlayerState,
): PendingChoice | null {
  const effects = cardDef.effects ?? [];
  for (const eff of effects) {
    // HERO_WITH_FEWEST_WOUNDS: empate en menos heridas
    if (eff.type === 'DEAL_DAMAGE_TO_HERO' && 'target' in eff && eff.target?.kind === 'HERO_WITH_FEWEST_WOUNDS') {
      const all = state.playerOrder;
      if (all.length === 0) continue;
      const minWounds = Math.min(...all.map(id => state.players[id].wounds));
      const candidates = all.filter(id => state.players[id].wounds === minWounds);
      if (candidates.length > 1) {
        return {
          choiceId: `tie-hero-${cardDef.id}-${nextSeq()}`,
          playerId: player.playerId,
          type: 'SELECT_HERO',
          prompt: `${cardDef.name}: Elige el h├®roe con menos Heridas (empate)`,
          options: candidates,
          minSelections: 1,
          maxSelections: 1,
        };
      }
    }
    // ENEMY_WITH_MAX_FORTITUDE: empate en fortaleza
    if ('target' in eff && eff.target && typeof eff.target === 'object' && eff.target.kind === 'ENEMY_WITH_MAX_FORTITUDE') {
      if (state.battlefield.length === 0) continue;
      const maxFort = Math.max(...state.battlefield.map(e => getEffectiveFortitude(e, state)));
      const candidates = state.battlefield.filter(e => getEffectiveFortitude(e, state) === maxFort);
      if (candidates.length > 1) {
        return {
          choiceId: `tie-enemy-${cardDef.id}-${nextSeq()}`,
          playerId: player.playerId,
          type: 'SELECT_ENEMY',
          prompt: `${cardDef.name}: Elige el enemigo con m├ís Fortaleza (empate)`,
          options: candidates.map(e => e.instanceId),
          minSelections: 1,
          maxSelections: 1,
        };
      }
    }
  }
  return null;
}

export interface ResolveResult {
  events: GameEvent[];
  newState: GameState;
  /** Enemigos derrotados durante esta resolucion */
  enemiesDefeated: string[];
  /** Cartas adicionales jugadas (para Disparo Rapido) */
  additionalCardsPlayed: string[];
  /** Eleccion pendiente si se detecto un empate que requiere decision del jugador */
  pendingChoice?: PendingChoice;
}

/**
 * Resolver una carta jugada: ejecutar todos sus efectos en orden,
 * procesar disparadores reactivos, y aplicar los eventos al estado.
 */
export function resolveCard(
  state: GameState,
  card: CardInstance,
  cardDef: CardDefinition,
  targetEnemyId: string | null,
  player: PlayerState,
  rng: DeterministicRng,
  registry: EffectRegistry,
  catalog: CatalogLoadResult,
  chosenHeroTarget?: string | null,
  chosenEnemyTarget?: string | null,
  chosenWearCardId?: string | null,
): ResolveResult {
  const allEvents: GameEvent[] = [];
  const enemiesDefeated: string[] = [];
  const additionalCardsPlayed: string[] = [];
  let currentState = state;

  // Contexto de resolucion (construido temprano para pendingChoice)
  const ctx: ResolutionContext = {
    activePlayerId: player.playerId,
    currentCardId: card.definitionId,
    currentCardName: cardDef.name,
    currentCardInstanceId: card.instanceId,
    selectedEnemyId: targetEnemyId,
    cardsPlayedThisTurn: { ...player.cardsPlayedThisTurn },
    cardsPlayedAgainstEnemy: { ...player.cardsPlayedAgainstEnemy },
    drawnCardInstanceId: null,
    sourceZone: 'HAND',
    enemiesDefeatedThisResolution: enemiesDefeated,
    depth: 0,
    chosenHeroTarget: chosenHeroTarget ?? null,
    chosenEnemyTarget: chosenEnemyTarget ?? null,
  };

  // Pre-escanear empates en selectores que requieren eleccion del jugador
  if (chosenHeroTarget === undefined && chosenEnemyTarget === undefined) {
    const tieChoice = detectTieForChoice(state, cardDef, player);
    if (tieChoice) {
      tieChoice.resolutionContext = ctx;
      return {
        events: [],
        newState: state,
        enemiesDefeated,
        additionalCardsPlayed,
        pendingChoice: tieChoice,
      };
    }
  }

  // Pre-escanear SEARCH_WEAR_PILE_PUT_IN_HAND: si hay mas de 1 carta en desgaste,
  // el jugador debe elegir (spec: "Busca una carta en tu pila de Desgaste")
  if (chosenWearCardId === undefined) {
    const hasSearchWear = cardDef.effects?.some(e => e.type === 'SEARCH_WEAR_PILE_PUT_IN_HAND');
    if (hasSearchWear) {
      const wearPile = player.wearPile;
      if (wearPile.length > 1) {
        const wearChoice: PendingChoice = {
          choiceId: `wear-${nextSeq()}`,
          playerId: player.playerId,
          type: 'SELECT_CARD_FROM_WEAR',
          prompt: `Elige una carta de tu pila de Desgaste para ${cardDef.name}`,
          options: wearPile.map(c => c.instanceId),
          minSelections: 1,
          maxSelections: 1,
          resolutionContext: ctx,
        };
        return {
          events: [],
          newState: state,
          enemiesDefeated,
          additionalCardsPlayed,
          pendingChoice: wearChoice,
        };
      }
    }
  } else {
    ctx.chosenWearCardId = chosenWearCardId;
  }

  // Evento: carta jugada
  allEvents.push({
    type: 'CARD_PLAYED',
    playerId: player.playerId,
    cardInstanceId: card.instanceId,
    cardDefinitionId: card.definitionId,
    cardName: cardDef.name,
    targetEnemyInstanceId: targetEnemyId ?? undefined,
    seq: nextSeq(),
  });

  // Bus: configurar con el estado actual
  const bus = new EventBus(registry, rng);
  bus.setState(currentState);

  // 1. Dano impreso de la carta (si tiene printedAttack > 0)
  // Excepcion: si la carta define su dano mediante efectos (SPLIT, ALL, TO_HERO),
  // no aplicar printedAttack al target unico (se aplicaria dos veces)
  const hasSpecialDamageEffect = cardDef.effects.some(
    e => e.type === 'DEAL_DAMAGE_SPLIT' || e.type === 'DEAL_DAMAGE_ALL_ENEMIES' || e.type === 'DEAL_DAMAGE_TO_HERO' || e.type === 'DEAL_DAMAGE_TO_OTHER_HEROES'
  );
  if (cardDef.printedAttack && cardDef.printedAttack > 0 && targetEnemyId && !hasSpecialDamageEffect) {
    let damage = cardDef.printedAttack;

    // Aplicar modificadores de dano del turno (Piedra de Amolar)
    damage = applyDamageModifiers(damage, cardDef.name, player);

    // Aplicar penalizacion de capacidad (especificacion 3.5)
    // Si el heroe tiene un icono con penalizacion, restar del dano
    // Ej: Picaro con armas a distancia resta 1
    // No se aplica la penalizacion si el heroe posee otro icono requerido sin penalizacion
    if (cardDef.penaltyCapabilities && cardDef.penaltyCapabilities.length > 0) {
      for (const penalty of cardDef.penaltyCapabilities) {
        if (player.capabilities.includes(penalty.icon)) {
          // Verificar si el heroe tiene algun capability requerido que NO este en penaltyCapabilities
          const hasNonPenaltyMatch = player.capabilities.some(cap =>
            cardDef.requiredCapabilities?.includes(cap) &&
            !cardDef.penaltyCapabilities?.some(p => p.icon === cap)
          );
          if (!hasNonPenaltyMatch) {
            damage = Math.max(0, damage - penalty.damagePenalty);
          }
        }
      }
    }

    // Aplicar vulnerabilidad del enemigo
    const enemy = currentState.battlefield.find(e => e.instanceId === targetEnemyId);
    if (enemy) {
      const vulnMods = enemy.modifiers.filter(m => m.layer === 'DAMAGE_BONUS');
      for (const mod of vulnMods) {
        damage += mod.amount;
      }
    }

    // Golpe de Baston: si ya se uso contra este enemigo, dano = 2
    if (cardDef.name === 'Golpe de Bast├│n' && targetEnemyId) {
      const usedAgainst = ctx.cardsPlayedAgainstEnemy[targetEnemyId]?.['Golpe de Bast├│n'] ?? 0;
      if (usedAgainst > 0) {
        damage = 2;
      }
    }

    // Ballesta Precisa: si ya se uso contra este enemigo, dano = 3
    if (cardDef.name === 'Ballesta Precisa' && targetEnemyId) {
      const usedAgainst = ctx.cardsPlayedAgainstEnemy[targetEnemyId]?.['Ballesta Precisa'] ?? 0;
      if (usedAgainst > 0) {
        damage = 3;
      }
    }

    allEvents.push({
      type: 'DAMAGE_DEALT',
      targetId: targetEnemyId,
      amount: damage,
      sourceCardInstanceId: card.instanceId,
      seq: nextSeq(),
    });

    // Aplicar el dano al estado intermedio para que los efectos posteriores
    // (como Todo o Nada) vean las heridas actualizadas al reevaluar derrota
    currentState = applyEventInline(currentState, {
      type: 'DAMAGE_DEALT',
      targetId: targetEnemyId,
      amount: damage,
      sourceCardInstanceId: card.instanceId,
      seq: nextSeq(),
    });

    // (La Gloria especial del Se├▒or y las pericias de Gurdrug/Shriekknifer
    // se procesan tras todos los efectos en el bloque post-efectos)

    // Comprobar si el enemigo es derrotado (currentState ya tiene el da├▒o aplicado)
    const enemyAfter = currentState.battlefield.find(e => e.instanceId === targetEnemyId);
    if (enemyAfter && enemyAfter.wounds >= getEffectiveFortitude(enemyAfter, currentState)) {
      // Emitir ENEMY_DEFEATED + invocar escenario
      currentState = emitEnemyDefeated(
        currentState, targetEnemyId, player.playerId, enemiesDefeated, allEvents, catalog, ctx,
      );

      // Ejecutar efectos ON_DEFEAT de la carta
      for (const effect of cardDef.effects) {
        if (effect.type === 'ON_DEFEAT') {
          const onDefeatEvents = executeEffectChain(
            effect.effects,
            ctx,
            currentState,
            rng,
            registry,
            catalog,
            0,
          );
          allEvents.push(...onDefeatEvents.events);
          currentState = onDefeatEvents.state;
        }
      }
    }
  }

  // 2. Ejecutar efectos de la carta (excluyendo ON_DEFEAT que ya se procesaron)
  for (const effect of cardDef.effects) {
    if (effect.type === 'ON_DEFEAT' || effect.type === 'ON_HORDE_ATTACK') continue;

    if (effect.type === 'DRAW_AND_ADD_ATTACK') {
      // Todo o Nada: robar 1 carta, sumar su dano al ataque, recuperar al fondo
      const drawCount = evalValue(effect.amount, ctx, currentState);
      const playerState = currentState.players[player.playerId];
      const drawnCards: CardInstance[] = [];
      for (let i = 0; i < drawCount && playerState.abilityDeck.length > 0; i++) {
        drawnCards.push(playerState.abilityDeck[0]);
        playerState.abilityDeck = playerState.abilityDeck.slice(1);
      }
      for (const drawnCard of drawnCards) {
        // Emitir evento de robo
        allEvents.push({
          type: 'CARDS_DRAWN',
          playerId: player.playerId,
          count: 1,
          cardInstanceIds: [drawnCard.instanceId],
          seq: nextSeq(),
        });
        const drawnDef = catalog.byId.get(drawnCard.definitionId);
        const extraDamage = drawnDef?.printedAttack ?? 0;
        // Sumar dano al objetivo actual
        if (extraDamage > 0 && targetEnemyId) {
          allEvents.push({
            type: 'DAMAGE_DEALT',
            targetId: targetEnemyId,
            amount: extraDamage,
            sourceCardInstanceId: drawnCard.instanceId,
            seq: nextSeq(),
          });
          // NOTA: La carta robada por Todo o Nada NO se juega, solo suma su ataque.
          // Por tanto NO genera Gloria del Se├▒or de la Guerra (┬º3.7: 1 Gloria por carta jugada).
          // Aplicar al estado intermedio
          currentState = applyEventInline(currentState, {
            type: 'DAMAGE_DEALT',
            targetId: targetEnemyId,
            amount: extraDamage,
            sourceCardInstanceId: drawnCard.instanceId,
            seq: nextSeq(),
          });
          // Comprobar derrota (applyEventInline ya sum├│ extraDamage a wounds)
          currentState = emitEnemyDefeated(
            currentState, targetEnemyId, player.playerId, enemiesDefeated, allEvents, catalog, ctx,
          );
        }
        // Recuperar la carta robada al fondo del mazo
        allEvents.push({
          type: 'CARD_MOVED',
          cardInstanceId: drawnCard.instanceId,
          from: 'HAND',
          to: 'ABILITY_DECK',
          seq: nextSeq(),
        });
        currentState = {
          ...currentState,
          players: {
            ...currentState.players,
            [player.playerId]: {
              ...currentState.players[player.playerId],
              abilityDeck: [
                ...currentState.players[player.playerId].abilityDeck,
                { ...drawnCard, zone: 'ABILITY_DECK' as Zone },
              ],
            },
          },
        };
      }
      continue;
    }

    if (effect.type === 'DRAW_AND_CHECK') {
      // Disparo Rapido: logica especial de cadena
      const chainResult = resolveRapidShot(
        currentState,
        card,
        cardDef,
        targetEnemyId,
        player,
        rng,
        registry,
        catalog,
        ctx,
        0,
        enemiesDefeated, // heredar enemigos ya derrotados
      );
      allEvents.push(...chainResult.events);
      currentState = chainResult.state;
      additionalCardsPlayed.push(...chainResult.additionalCardsPlayed);
      enemiesDefeated.push(...chainResult.enemiesDefeated);
      continue;
    }

    if (effect.type === 'PLACE_PERSISTENT') {
      // Trampa: colocar carta persistente
      allEvents.push({
        type: 'PERSISTENT_CARD_PLACED',
        playerId: player.playerId,
        cardInstanceId: card.instanceId,
        cardDefinitionId: card.definitionId,
        trigger: effect.trigger,
        seq: nextSeq(),
      });
      // No mover a desgaste; queda frente al jugador
      continue;
    }

    if (effect.type === 'SWAP_ENEMY') {
      // Supervivencia: intercambiar enemigo en campo por el del fondo del mazo de la Horda
      const targetId = effect.target.kind === 'SELECTED_ENEMY' ? targetEnemyId : null;
      if (!targetId || currentState.hordeDeck.length === 0) continue;
      const newEnemyCard = currentState.hordeDeck[currentState.hordeDeck.length - 1];
      const newEnemyDef = catalog.byId.get(newEnemyCard.definitionId);
      if (!newEnemyDef) continue;
      allEvents.push({
        type: 'ENEMY_SWAPPED',
        oldEnemyInstanceId: targetId,
        newEnemyInstanceId: newEnemyCard.instanceId,
        newEnemyDefinitionId: newEnemyCard.definitionId,
        newEnemyFortitude: newEnemyDef.printedFortitude ?? 1,
        newEnemyReward: newEnemyDef.reward ?? null,
        newEnemyIsOrc: newEnemyDef.isOrc ?? false,
        newEnemyIsWarlord: newEnemyDef.type === 'WARLORD',
        newEnemySpecialIcons: newEnemyDef.specialIcons ?? [],
        seq: nextSeq(),
      });
      continue;
    }

    if (effect.type === 'MODIFY_DAMAGE') {
      // Piedra de Amolar: anadir modificador de dano al jugador
      const modifierAmount = evalValue(effect.modifier, ctx, currentState);
      // El modificador se aplica via PlayerState.modifiers
      // Lo manejamos anadiendolo al estado del jugador
      const modId = `mod-${nextSeq()}`;
      allEvents.push({
        type: 'MODIFIER_ADDED',
        modifierId: modId,
        targetId: player.playerId,
        layer: 'DAMAGE_BONUS',
        amount: modifierAmount,
        sourceId: card.instanceId,
        duration: 'UNTIL_END_OF_TURN',
        filter: effect.filter,
        scope: effect.scope,
        seq: nextSeq(),
      });
      // Actualizar estado: anadir modificador al jugador
      currentState = {
        ...currentState,
        players: {
          ...currentState.players,
          [player.playerId]: {
            ...currentState.players[player.playerId],
            modifiers: [
              ...currentState.players[player.playerId].modifiers,
              {
                id: modId,
                sourceId: card.instanceId,
                layer: 'DAMAGE_BONUS',
                timestamp: nextSeq(),
                duration: 'UNTIL_END_OF_TURN',
                amount: modifierAmount,
                filter: effect.filter,
                scope: effect.scope,
              },
            ],
          },
        },
      };
      continue;
    }

    if (effect.type === 'MODIFY_FORTITUDE') {
      // Ruinas de Brunmar / Roghkiller: modificar fortaleza de enemigos
      const modifierAmount = evalValue(effect.modifier, ctx, currentState);
      // Manejar ALL_ENEMIES: aplicar a todos los enemigos del campo
      const targetIds = effect.target.kind === 'ALL_ENEMIES'
        ? currentState.battlefield.map(e => e.instanceId)
        : [resolveTarget(effect.target, ctx, currentState)].filter((id): id is string => id !== null);
      for (const targetId of targetIds) {
        const modId = `fort-mod-${nextSeq()}`;
        allEvents.push({
          type: 'MODIFIER_ADDED',
          modifierId: modId,
          targetId,
          layer: 'FORTITUDE_MODIFIERS',
          amount: modifierAmount,
          sourceId: card.instanceId,
          duration: effect.duration,
          seq: nextSeq(),
        });
        // Aplicar al estado intermedio: solo a├▒adir el modificador, NO mutar baseFortitude
        currentState = {
          ...currentState,
          battlefield: currentState.battlefield.map(e =>
            e.instanceId === targetId
              ? {
                  ...e,
                  modifiers: [
                    ...e.modifiers,
                    {
                      id: modId,
                      sourceId: card.instanceId,
                      layer: 'FORTITUDE_MODIFIERS',
                      timestamp: nextSeq(),
                      duration: effect.duration,
                      amount: modifierAmount,
                      targetId,
                    },
                  ],
                }
              : e
          ),
        };
      }
      continue;
    }

    if (effect.type === 'MODIFY_MARKET_COST') {
      // Mercado de Lotharion: reducir coste de mercado
      const modifierAmount = evalValue(effect.modifier, ctx, currentState);
      const modId = `market-cost-${nextSeq()}`;
      allEvents.push({
        type: 'MODIFIER_ADDED',
        modifierId: modId,
        targetId: 'market',
        layer: 'MARKET_COST',
        amount: modifierAmount,
        sourceId: card.instanceId,
        duration: 'WHILE_SOURCE_ACTIVE',
        seq: nextSeq(),
      });
      currentState = {
        ...currentState,
        marketCostModifier: currentState.marketCostModifier + modifierAmount,
      };
      continue;
    }

    if (effect.type === 'END_ATTACK') {
      // Escudo: terminar el enfrentamiento y pasar al ataque de la Horda
      allEvents.push({
        type: 'PHASE_CHANGED',
        phase: 'HORDE_ATTACK',
        seq: nextSeq(),
      });
      continue;
    }

    // Efecto normal: delegar al registry
    const effectEvents = registry.execute(effect, ctx, currentState, rng, bus);
    allEvents.push(...effectEvents);

    // Aplicar eventos al estado
    for (const ev of effectEvents) {
      // Si el registry emiti├│ ENEMY_DEFEATED (ej: DEFEAT_ENEMY), capturar enemigo ANTES de aplicar
      const enemyBeforeApply = ev.type === 'ENEMY_DEFEATED'
        ? currentState.battlefield.find(e => e.instanceId === ev.enemyInstanceId)
        : null;
      currentState = applyEventInline(currentState, ev);
      if (ev.type === 'ENEMY_DEFEATED' && enemyBeforeApply && !enemiesDefeated.includes(ev.enemyInstanceId)) {
        enemiesDefeated.push(ev.enemyInstanceId);
        const scenarioDefId = currentState.scenario?.definitionId;
        if (scenarioDefId) {
          const enemyFortitude = getEffectiveFortitude(enemyBeforeApply, currentState);
          (ctx as any).lastDefeatedEnemyFortitude = enemyFortitude;
          const scenarioEvents = scenarioOnEnemyDefeated(
            currentState, scenarioDefId, ev.defeatingPlayerId, enemyFortitude, catalog,
          );
          allEvents.push(...scenarioEvents);
          for (const sev of scenarioEvents) {
            currentState = applyEventInline(currentState, sev);
          }
        }
      }
    }
  }

  // Tras ejecutar todos los efectos, comprobar si los da├▒os gen├®ricos
  // (DEAL_DAMAGE_SPLIT, DEAL_DAMAGE_ALL, etc.) han derrotado alg├║n enemigo
  for (const enemy of currentState.battlefield) {
    if (enemy.wounds >= getEffectiveFortitude(enemy, currentState)) {
      currentState = emitEnemyDefeated(
        currentState, enemy.instanceId, player.playerId, enemiesDefeated, allEvents, catalog, ctx,
      );
    }
  }

  // Pericias de Se├▒ores de la Guerra: procesar tras todos los efectos
  // Buscar DAMAGE_DEALT emitidos contra Se├▒ores por esta carta o sus copias (Disparo R├ípido)
  const allSourceCardIds = new Set([card.instanceId, ...additionalCardsPlayed]);
  const damageEventsVsWarlord = allEvents.filter(
    (e): e is { type: 'DAMAGE_DEALT'; targetId: string; amount: number; sourceCardInstanceId: string; seq: number } =>
      e.type === 'DAMAGE_DEALT' &&
      allSourceCardIds.has(e.sourceCardInstanceId) &&
      e.amount >= 1
  );
  // Agrupar por Se├▒or (pericias se activan una vez por Se├▒or por carta)
  const warlordsHit = new Set<string>();
  // Gloria: 1 por carta que da├▒e a cualquier Se├▒or (no por Se├▒or)
  const gloryCards = new Set<string>();
  for (const dmgEv of damageEventsVsWarlord) {
    // Buscar el enemigo en el estado actual O en el original (puede haber sido derrotado)
    let warlord = currentState.battlefield.find(e => e.instanceId === dmgEv.targetId);
    if (!warlord) {
      // Buscar en el estado original (antes de aplicar eventos)
      warlord = state.battlefield.find(e => e.instanceId === dmgEv.targetId);
    }
    if (!warlord?.isWarlord) continue;
    // Gloria: 1 por carta (no por Se├▒or ni por impacto)
    gloryCards.add(dmgEv.sourceCardInstanceId);
    // Pericias: una vez por Se├▒or por carta
    const periciaKey = `${dmgEv.sourceCardInstanceId}-${warlord.instanceId}`;
    if (warlordsHit.has(periciaKey)) continue;
    warlordsHit.add(periciaKey);
    const warlordDef = catalog.byId.get(warlord.definitionId);
    if (!warlordDef) continue;

    // Gurdrug: cada carta que da├▒e al Jefe provoca p├®rdida de 1 carta adicional
    if (warlordDef.name === 'Gurdrug') {
      // Usar applyHeroDamage para manejar mazo vac├¡o (reciclaje + herida)
      const gurdrugEvents = applyHeroDamage(
        player.playerId, 1, currentState, rng, nextSeq,
      );
      allEvents.push(...gurdrugEvents);
      // Actualizar estado para que la siguiente iteraci├│n vea el mazo actualizado
      for (const ev of gurdrugEvents) {
        currentState = applyEventInline(currentState, ev);
      }
    }

    // Shriekknifer: cartas con printedAttack == 1 ÔåÆ recuperar 1 carta
    if (warlordDef.name === 'Shriekknifer' && (cardDef.printedAttack ?? 0) === 1) {
      const playerState = currentState.players[player.playerId];
      if (playerState.wearPile.length > 0) {
        // Recuperar de la parte INFERIOR del desgaste (cartas m├ís antiguas)
        const recoveredCard = playerState.wearPile[0];
        const recoverEvent = {
          type: 'CARDS_RECOVERED' as const,
          playerId: player.playerId,
          count: 1,
          cardInstanceIds: [recoveredCard.instanceId],
          toZone: 'ABILITY_DECK' as const,
          seq: nextSeq(),
        };
        allEvents.push(recoverEvent);
        // Actualizar estado para que la siguiente iteraci├│n vea el desgaste actualizado
        currentState = applyEventInline(currentState, recoverEvent);
      }
    }
  }

  // Gloria especial del Se├▒or: 1 Gloria por carta que da├▒e al Se├▒or (┬º3.7, DIG-008)
  for (const _cardId of gloryCards) {
    allEvents.push({
      type: 'GLORY_GAINED',
      playerId: player.playerId,
      amount: 1,
      seq: nextSeq(),
    });
  }

  // 3. Mover carta a desgaste (o destino especial)
  // Excepci├│n: si la carta tiene RECOVER_THIS_CARD y se emiti├│ CARDS_RECOVERED para ella,
  // no mover a WEAR_PILE (la carta se recuper├│ a mano o mazo)
  const wasRecovered = allEvents.some(
    e => e.type === 'CARDS_RECOVERED' && (e as { cardInstanceIds?: string[] }).cardInstanceIds?.includes(card.instanceId)
  );
  if (wasRecovered) {
    // La carta ya fue recuperada por RECOVER_THIS_CARD; no mover a WEAR_PILE
  } else if (cardDef.destinationAfterUse === 'WEAR_PILE') {
    allEvents.push({
      type: 'CARD_MOVED',
      cardInstanceId: card.instanceId,
      from: 'HAND',
      to: 'WEAR_PILE',
      seq: nextSeq(),
    });
  } else if (cardDef.destinationAfterUse === 'REMOVED_FROM_GAME') {
    allEvents.push({
      type: 'CARD_REMOVED_FROM_GAME',
      cardInstanceId: card.instanceId,
      seq: nextSeq(),
    });
  } else if (cardDef.destinationAfterUse === 'IN_FRONT_OF_PLAYER') {
    // Ya se manejo en PLACE_PERSISTENT
  }

  // 4. Aplicar todos los eventos al estado final
  // Nota: empezamos desde el estado original (no currentState) porque
  // los eventos ya se aplicaron incrementalmente a currentState durante
  // la resolucion. Aplicarlos de nuevo desde state asegura consistencia
  // del event sourcing sin doblar efectos.
  let finalState = state;
  for (const ev of allEvents) {
    finalState = applyEventInline(finalState, ev);
  }

  return {
    events: allEvents,
    newState: finalState,
    enemiesDefeated,
    additionalCardsPlayed,
  };
}

// ============================================================================
// Disparo Rapido ÔÇö cadena de cartas
// ============================================================================

interface ChainResult {
  events: GameEvent[];
  state: GameState;
  additionalCardsPlayed: string[];
  enemiesDefeated: string[];
}

function resolveRapidShot(
  state: GameState,
  _sourceCard: CardInstance,
  cardDef: CardDefinition,
  targetEnemyId: string | null,
  player: PlayerState,
  rng: DeterministicRng,
  registry: EffectRegistry,
  catalog: CatalogLoadResult,
  ctx: ResolutionContext,
  depth: number = 0,
  inheritedEnemiesDefeated: string[] = [],
): ChainResult {
  const events: GameEvent[] = [];
  let currentState = state;
  const additionalCardsPlayed: string[] = [];
  const enemiesDefeated: string[] = [...inheritedEnemiesDefeated];

  if (depth >= MAX_CHAIN_DEPTH) {
    return { events, state: currentState, additionalCardsPlayed, enemiesDefeated };
  }

  // Buscar el efecto DRAW_AND_CHECK
  const drawEffect = cardDef.effects.find(e => e.type === 'DRAW_AND_CHECK');
  if (!drawEffect || drawEffect.type !== 'DRAW_AND_CHECK') {
    return { events, state: currentState, additionalCardsPlayed, enemiesDefeated };
  }

  // Normalizar aliases snake_case (compatibilidad con formato MD)
  const expectedName = drawEffect.expectedName ?? (drawEffect as any).expected_name;
  const onMatchEffects = drawEffect.onMatch ?? (drawEffect as any).on_match ?? [];
  // Leer inheritTarget del onMatch (default: true)
  const playImmediatelyEffect = onMatchEffects.find((e: any) => e.type === 'PLAY_IMMEDIATELY');
  const inheritTarget = playImmediatelyEffect ? (playImmediatelyEffect as any).inheritTarget !== false : true;

  // Robar 1 carta del mazo
  let currentPlayer = currentState.players[player.playerId];
  if (currentPlayer.abilityDeck.length === 0) {
    // Mazo agotado: recibir 1 Herida y barajar Desgaste (especificacion: mazo como vida)
    if (currentPlayer.wearPile.length > 0) {
      events.push({
        type: 'HERO_WOUNDED',
        playerId: player.playerId,
        woundCount: currentPlayer.wounds + 1,
        seq: nextSeq(),
      });
      const shuffledWear = rng.shuffle([...currentPlayer.wearPile]);
      const newOrder = shuffledWear.map(c => c.instanceId);
      events.push({
        type: 'DECK_RESHUFFLED',
        playerId: player.playerId,
        newDeckSize: shuffledWear.length,
        newOrder,
        seq: nextSeq(),
      });
      // Actualizar estado: barajar desgaste como nuevo mazo
      currentState = {
        ...currentState,
        players: {
          ...currentState.players,
          [player.playerId]: {
            ...currentPlayer,
            abilityDeck: shuffledWear.map(c => ({ ...c, zone: 'ABILITY_DECK' as Zone })),
            wearPile: [],
            wounds: currentPlayer.wounds + 1,
          },
        },
      };
      currentPlayer = currentState.players[player.playerId];
    } else {
      // No hay desgaste ni mazo: no se puede robar
      return { events, state: currentState, additionalCardsPlayed, enemiesDefeated };
    }
  }

  const drawnCard = currentPlayer.abilityDeck[0];
  const drawnDef = catalog.byId.get(drawnCard.definitionId);

  // Evento: carta robada
  events.push({
    type: 'CARDS_DRAWN',
    playerId: player.playerId,
    count: 1,
    cardInstanceIds: [drawnCard.instanceId],
    seq: nextSeq(),
  });

  // Aplicar el robo al estado
  currentState = {
    ...currentState,
    players: {
      ...currentState.players,
      [player.playerId]: {
        ...currentState.players[player.playerId],
        abilityDeck: currentState.players[player.playerId].abilityDeck.slice(1),
        hand: [...currentState.players[player.playerId].hand, { ...drawnCard, zone: 'HAND' as Zone }],
      },
    },
  };

  if (!drawnDef) {
    return { events, state: currentState, additionalCardsPlayed, enemiesDefeated };
  }

  // Comprobar si la carta robada es del mismo nombre
  if (drawnDef.name === expectedName) {
    // Coincidencia: ejecutar onMatch (PLAY_IMMEDIATELY)
    additionalCardsPlayed.push(drawnCard.instanceId);

    // Quitar la carta robada de la mano
    currentState = {
      ...currentState,
      players: {
        ...currentState.players,
        [player.playerId]: {
          ...currentState.players[player.playerId],
          hand: currentState.players[player.playerId].hand.filter(
            c => c.instanceId !== drawnCard.instanceId
          ),
        },
      },
    };

    // Evento: carta jugada
    // Determinar el objetivo de la carta robada
    // Si inheritTarget === false, elegir un nuevo objetivo (primer enemigo del campo que no sea el original)
    let drawnTargetEnemyId: string | null;
    if (inheritTarget) {
      drawnTargetEnemyId = targetEnemyId;
    } else {
      // Buscar un enemigo diferente al original
      const differentEnemy = currentState.battlefield.find(e => e.instanceId !== targetEnemyId);
      drawnTargetEnemyId = differentEnemy
        ? differentEnemy.instanceId
        : (currentState.battlefield.length > 0 ? currentState.battlefield[0].instanceId : null);
    }

    events.push({
      type: 'CARD_PLAYED',
      playerId: player.playerId,
      cardInstanceId: drawnCard.instanceId,
      cardDefinitionId: drawnCard.definitionId,
      cardName: drawnDef.name,
      targetEnemyInstanceId: drawnTargetEnemyId ?? undefined,
      seq: nextSeq(),
    });

    // Dano impreso de la carta robada
    if (drawnDef.printedAttack && drawnDef.printedAttack > 0 && drawnTargetEnemyId) {
      let damage = drawnDef.printedAttack;
      damage = applyDamageModifiers(damage, drawnDef.name, currentState.players[player.playerId]);
      // Aplicar vulnerabilidad del enemigo (DAMAGE_BONUS)
      if (drawnTargetEnemyId) {
        const enemy = currentState.battlefield.find(e => e.instanceId === drawnTargetEnemyId);
        if (enemy) damage += getEnemyDamageBonus(enemy);
      }

      events.push({
        type: 'DAMAGE_DEALT',
        targetId: drawnTargetEnemyId,
        amount: damage,
        sourceCardInstanceId: drawnCard.instanceId,
        seq: nextSeq(),
      });

      // Aplicar el dano al estado intermedio para que la reevaluacion de derrota sea correcta
      currentState = applyEventInline(currentState, {
        type: 'DAMAGE_DEALT',
        targetId: drawnTargetEnemyId,
        amount: damage,
        sourceCardInstanceId: drawnCard.instanceId,
        seq: nextSeq(),
      });

      // Gloria del Se├▒or de la Guerra: se otorga en el post-procesado de pericias
      // (no aqu├¡, para evitar doble GLORY_GAINED)

      // Comprobar derrota (currentState ya tiene el da├▒o aplicado)
      if (drawnTargetEnemyId) {
        currentState = emitEnemyDefeated(
          currentState, drawnTargetEnemyId, player.playerId, enemiesDefeated, events, catalog, ctx,
        );
      }
    }

    // Mover carta robada a desgaste
    events.push({
      type: 'CARD_MOVED',
      cardInstanceId: drawnCard.instanceId,
      from: 'HAND',
      to: 'WEAR_PILE',
      seq: nextSeq(),
    });

    // Recursion: la carta robada tambien tiene DRAW_AND_CHECK
    if (drawnDef.effects.some(e => e.type === 'DRAW_AND_CHECK')) {
      const newCtx: ResolutionContext = {
        ...ctx,
        currentCardId: drawnCard.definitionId,
        currentCardName: drawnDef.name,
        currentCardInstanceId: drawnCard.instanceId,
        depth: depth + 1,
      };
      const chainResult = resolveRapidShot(
        currentState,
        drawnCard,
        drawnDef,
        drawnTargetEnemyId,
        currentState.players[player.playerId],
        rng,
        registry,
        catalog,
        newCtx,
        depth + 1,
        enemiesDefeated, // heredar enemigos ya derrotados en la cadena
      );
      events.push(...chainResult.events);
      currentState = chainResult.state;
      additionalCardsPlayed.push(...chainResult.additionalCardsPlayed);
      enemiesDefeated.push(...chainResult.enemiesDefeated);
    }
  } else {
    // No coincidencia: la carta robada va al FONDO del mazo de Habilidad
    // (especificacion: Disparo Rapido - carta fallida al fondo del mazo)
    events.push({
      type: 'CARD_MOVED',
      cardInstanceId: drawnCard.instanceId,
      from: 'HAND',
      to: 'ABILITY_DECK',
      seq: nextSeq(),
    });
    // Actualizar estado: remover de mano, anadir al fondo del mazo
    currentState = {
      ...currentState,
      players: {
        ...currentState.players,
        [player.playerId]: {
          ...currentState.players[player.playerId],
          hand: currentState.players[player.playerId].hand.filter(
            c => c.instanceId !== drawnCard.instanceId
          ),
          abilityDeck: [
            ...currentState.players[player.playerId].abilityDeck,
            { ...drawnCard, zone: 'ABILITY_DECK' as Zone },
          ],
        },
      },
    };

    // Beleth-Il: recuperar la carta fallida y robar otra
    // (especificacion: Pericia de Beleth-Il - una vez por turno)
    const playerState = currentState.players[player.playerId];
    const heroDef = catalog.byId.get(playerState.heroId);
    const isBelethIl = heroDef?.name === 'Beleth-Il';
    const hasUsesRemaining = (playerState.heroUsesRemaining ?? 0) > 0;
    if (isBelethIl && hasUsesRemaining) {
      const belethEvents = belethIlRapidShotRecovery(currentState, player.playerId, drawnCard.instanceId);
      if (belethEvents.length > 0) {
        events.push(...belethEvents);
        // Consumir un uso de Pericia
        events.push({
          type: 'HERO_ABILITY_USED',
          playerId: player.playerId,
          usesRemaining: (playerState.heroUsesRemaining ?? 1) - 1,
          seq: nextSeq(),
        });
        // Aplicar eventos de recuperaci├│n al estado antes de robar carta extra
        // (la carta fallida ya no est├í en abilityDeck)
        for (const ev of belethEvents) {
          currentState = applyEventInline(currentState, ev);
        }
        // Robar 1 carta extra del mazo actualizado
        const updatedPlayer = currentState.players[player.playerId];
        if (updatedPlayer.abilityDeck.length > 0) {
          const extraCard = updatedPlayer.abilityDeck[0];
          events.push({
            type: 'CARDS_DRAWN',
            playerId: player.playerId,
            count: 1,
            cardInstanceIds: [extraCard.instanceId],
            seq: nextSeq(),
          });
        } else if (updatedPlayer.wearPile.length > 0) {
          // Mazo vac├¡o: herida + barajar desgaste (especificacion: mazo como vida)
          events.push({
            type: 'HERO_WOUNDED',
            playerId: player.playerId,
            woundCount: updatedPlayer.wounds + 1,
            seq: nextSeq(),
          });
          const shuffledWear = rng.shuffle([...updatedPlayer.wearPile]);
          const newOrder = shuffledWear.map(c => c.instanceId);
          events.push({
            type: 'DECK_RESHUFFLED',
            playerId: player.playerId,
            newDeckSize: shuffledWear.length,
            newOrder,
            seq: nextSeq(),
          });
          if (shuffledWear.length > 0) {
            events.push({
              type: 'CARDS_DRAWN',
              playerId: player.playerId,
              count: 1,
              cardInstanceIds: [shuffledWear[0].instanceId],
              seq: nextSeq(),
            });
          }
        }
      }
    }
  }

  return { events, state: currentState, additionalCardsPlayed, enemiesDefeated };
}

// ============================================================================
// Disparadores reactivos: ON_HORDE_ATTACK (Trampa)
// ============================================================================

export function processHordeAttackTriggers(
  state: GameState,
  rng: DeterministicRng,
  registry: EffectRegistry,
  catalog: CatalogLoadResult,
  chosenEnemyTarget?: string | null,
): { events: GameEvent[]; state: GameState; pendingChoice?: PendingChoice } {
  const events: GameEvent[] = [];
  let currentState = state;

  // Buscar cartas persistentes con trigger HORDE_ATTACK
  // D378: Solo se activan para el jugador activo (la Horda ataca al h├®roe activo)
  for (const playerId of [state.activePlayerId]) {
    const player = state.players[playerId];
    if (!player) continue;
    for (const persistentCard of player.persistentCards) {
      if (persistentCard.persistentTrigger !== 'HORDE_ATTACK') continue;

      const cardDef = catalog.byId.get(persistentCard.definitionId);
      if (!cardDef) continue;

      // Buscar el efecto PLACE_PERSISTENT y ejecutar sus efectos internos
      for (const effect of cardDef.effects) {
        if (effect.type !== 'PLACE_PERSISTENT') continue;

        // Detectar empate de Fortaleza m├íxima para Trampa (spec: el jugador elige)
        if (chosenEnemyTarget === undefined) {
          const innerEffects = (effect as any).effects ?? [];
          const hasMaxFortitudeTarget = innerEffects.some((e: any) =>
            e.target?.kind === 'ENEMY_WITH_MAX_FORTITUDE'
          );
          if (hasMaxFortitudeTarget && currentState.battlefield.length > 0) {
            const maxFort = Math.max(...currentState.battlefield.map(e => getEffectiveFortitude(e, currentState)));
            const tied = currentState.battlefield.filter(e => getEffectiveFortitude(e, currentState) === maxFort);
            if (tied.length > 1) {
              const tieChoice: PendingChoice = {
                choiceId: `trap-${nextSeq()}`,
                playerId,
                type: 'SELECT_ENEMY',
                prompt: `Trampa: elige el enemigo a derrotar (empate de Fortaleza ${maxFort})`,
                options: tied.map(e => e.instanceId),
                minSelections: 1,
                maxSelections: 1,
              };
              return { events, state: currentState, pendingChoice: tieChoice };
            }
          }
        }

        // La Trampa derrota al enemigo con mayor fortaleza
        const ctx: ResolutionContext = {
          activePlayerId: playerId,
          currentCardId: persistentCard.definitionId,
          currentCardName: cardDef.name,
          currentCardInstanceId: persistentCard.instanceId,
          selectedEnemyId: null,
          cardsPlayedThisTurn: {},
          cardsPlayedAgainstEnemy: {},
          drawnCardInstanceId: null,
          sourceZone: 'IN_FRONT_OF_PLAYER',
          enemiesDefeatedThisResolution: [],
          depth: 0,
          chosenEnemyTarget: chosenEnemyTarget ?? null,
        };

        // Ejecutar los efectos internos del PLACE_PERSISTENT (no el PLACE_PERSISTENT mismo)
        const innerEffects = (effect as any).effects ?? [];
        const bus = new EventBus(registry, rng);
        for (const innerEff of innerEffects) {
          const triggerEvents = registry.execute(innerEff, ctx, currentState, rng, bus);
          events.push(...triggerEvents);
          // Aplicar eventos al estado
          for (const ev of triggerEvents) {
            // Capturar enemigo ANTES de applyEventInline (que lo elimina del battlefield)
            const enemyBeforeApply = ev.type === 'ENEMY_DEFEATED'
              ? currentState.battlefield.find(e => e.instanceId === ev.enemyInstanceId)
              : null;
            currentState = applyEventInline(currentState, ev);
            // Si se emiti├│ ENEMY_DEFEATED, invocar escenario
            if (ev.type === 'ENEMY_DEFEATED' && enemyBeforeApply && !ctx.enemiesDefeatedThisResolution.includes(ev.enemyInstanceId)) {
              ctx.enemiesDefeatedThisResolution.push(ev.enemyInstanceId);
              const scenarioDefId = currentState.scenario?.definitionId;
              if (scenarioDefId) {
                const enemy = enemyBeforeApply;
                if (enemy) {
                  const enemyFortitude = getEffectiveFortitude(enemy, currentState);
                  (ctx as any).lastDefeatedEnemyFortitude = enemyFortitude;
                  const scenarioEvents = scenarioOnEnemyDefeated(
                    currentState, scenarioDefId, ev.defeatingPlayerId, enemyFortitude, catalog,
                  );
                  events.push(...scenarioEvents);
                  for (const sev of scenarioEvents) {
                    currentState = applyEventInline(currentState, sev);
                  }
                }
              }
            }
          }
        }

        // Remover la carta persistente (se consume)
        events.push({
          type: 'PERSISTENT_CARD_REMOVED',
          cardInstanceId: persistentCard.instanceId,
          seq: nextSeq(),
        });
        events.push({
          type: 'CARD_REMOVED_FROM_GAME',
          cardInstanceId: persistentCard.instanceId,
          seq: nextSeq(),
        });
      }
    }
  }

  return { events, state };
}

// ============================================================================
// Helpers
// ============================================================================

export function applyDamageModifiers(baseDamage: number, cardName: string, player: PlayerState): number {
  let damage = baseDamage;
  for (const mod of player.modifiers) {
    if (mod.layer !== 'DAMAGE_BONUS') continue;
    if (mod.filter?.name && mod.filter.name !== cardName) continue;
    damage += mod.amount;
  }
  return Math.max(0, damage);
}

function applyEventInline(state: GameState, event: GameEvent): GameState {
  return applyEvent(state, event);
}

// ============================================================================
// Ejecutar cadena de efectos con limite de recursion
// ============================================================================

function executeEffectChain(
  effects: CardEffect[],
  ctx: ResolutionContext,
  state: GameState,
  rng: DeterministicRng,
  registry: EffectRegistry,
  _catalog: CatalogLoadResult,
  depth: number,
): { events: GameEvent[]; state: GameState } {
  if (depth >= MAX_EFFECT_RECURSION) {
    return { events: [], state };
  }

  const allEvents: GameEvent[] = [];
  let currentState = state;
  const bus = new EventBus(registry, rng);
  bus.setState(currentState);

  for (const effect of effects) {
    const events = registry.execute(effect, ctx, currentState, rng, bus);
    allEvents.push(...events);
    for (const ev of events) {
      currentState = applyEventInline(currentState, ev);
    }
  }

  return { events: allEvents, state: currentState };
}

/**
 * applyEvent ÔÇö reducer puro que aplica un evento al estado.
 *
 * Reglas:
 * - Sin efectos secundarios (no I/O, no RNG, no mutacion del input).
 * - Devuelve un nuevo estado.
 * - El estado es un fold sobre eventos: state = events.reduce(applyEvent, initialState).
 */

import type {
  GameState,
  GameEvent,
  PlayerState,
  EnemyState,
  CardInstance,
  Modifier,
  ModifierLayer,
  Zone,
} from '@nt4h/schema';

export function applyEvent(state: GameState, event: GameEvent): GameState {
  const newState = applyEventInternal(state, event);
  // Especificacion ┬º51.12: event sourcing ÔÇö todos los eventos van al eventLog
  return {
    ...newState,
    eventLog: [...newState.eventLog, event],
    monotonicCounter: newState.monotonicCounter + 1,
  };
}

function applyEventInternal(state: GameState, event: GameEvent): GameState {
  switch (event.type) {
    // === Fases y turnos ===
    case 'PHASE_CHANGED':
      return { ...state, phase: event.phase };

    case 'TURN_STARTED':
      return {
        ...state,
        activePlayerId: event.playerId,
        turnNumber: event.turnNumber,
        // Reset contadores por turno del jugador activo
        players: mapPlayer(state.players, event.playerId, p => ({
          ...p,
          cardsPlayedThisTurn: {},
          cardsPlayedAgainstEnemy: {},
          oncePerTurnUsed: new Set(),
          prevention: 0,
          damageCancellation: false,
          shields: 0,
          interceptedBy: null,
          // Reset contadores de Apoyo (modo solitario)
          supportCardsDrawnThisTurn: 0,
          supportDeckIndexUsedThisTurn: null,
        })),
      };

    case 'TURN_ENDED':
      return state;

    // === Cartas jugadas ===
    case 'CARD_PLAYED': {
      const player = state.players[event.playerId];
      const card = player.hand.find(c => c.instanceId === event.cardInstanceId);
      if (!card) return state; // defensive: carta no encontrada

      // NOTA: NO quitamos la carta de la mano aqu├¡. CARD_MOVED la mueve a WEAR_PILE.
      // Si la quitamos aqu├¡, CARD_MOVED no la encontrar├í.
      return {
        ...state,
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            cardsPlayedThisTurn: {
              ...player.cardsPlayedThisTurn,
              // Indexar por definitionId Y por nombre (las condiciones buscan por nombre)
              [card.definitionId]: (player.cardsPlayedThisTurn[card.definitionId] ?? 0) + 1,
              ...(event.cardName ? {
                [event.cardName]: (player.cardsPlayedThisTurn[event.cardName] ?? 0) + 1,
              } : {}),
            },
            cardsPlayedAgainstEnemy: {
              ...player.cardsPlayedAgainstEnemy,
              ...(state.activePlayerId === event.playerId && state.battlefield.some(e => e.instanceId === event.targetEnemyInstanceId) ? {
                [event.targetEnemyInstanceId!]: {
                  ...player.cardsPlayedAgainstEnemy[event.targetEnemyInstanceId!],
                  [card.definitionId]: (player.cardsPlayedAgainstEnemy[event.targetEnemyInstanceId!]?.[card.definitionId] ?? 0) + 1,
                  ...(event.cardName ? {
                    [event.cardName]: (player.cardsPlayedAgainstEnemy[event.targetEnemyInstanceId!]?.[event.cardName] ?? 0) + 1,
                  } : {}),
                },
              } : {}),
            },
          },
        },
      };
    }

    // === Dano y heridas ===
    case 'DAMAGE_DEALT':
      return {
        ...state,
        battlefield: state.battlefield.map(e =>
          e.instanceId === event.targetId
            ? { ...e, wounds: e.wounds + event.amount }
            : e
        ),
      };

    case 'WOUND_PLACED':
      return {
        ...state,
        battlefield: state.battlefield.map(e =>
          e.instanceId === event.enemyInstanceId
            ? { ...e, wounds: e.wounds + event.amount }
            : e
        ),
      };

    case 'ENEMY_DEFEATED': {
      const enemy = state.battlefield.find(e => e.instanceId === event.enemyInstanceId);
      if (!enemy) return state;

      const player = state.players[event.defeatingPlayerId];
      // Si se derrot├│ a Roghkiller, eliminar sus modificadores de +1 fortaleza de los orcos
      let newBattlefield = state.battlefield.filter(e => e.instanceId !== event.enemyInstanceId);
      if (enemy.isWarlord && enemy.definitionId.includes('roghkiller')) {
        newBattlefield = newBattlefield.map(e => ({
          ...e,
          modifiers: e.modifiers.filter(m => m.sourceId !== 'roghkiller'),
        }));
      }
      return {
        ...state,
        battlefield: newBattlefield,
        warlordDefeated: state.warlordDefeated || enemy.isWarlord,
        warlordsDefeatedCount: state.warlordsDefeatedCount + (enemy.isWarlord ? 1 : 0),
        players: {
          ...state.players,
          [event.defeatingPlayerId]: {
            ...player,
            // D397: Guardar instanceId (no definitionId) seg├║n el schema
            trophies: [...player.trophies, event.enemyInstanceId],
            coins: player.coins + event.reward.coins,
            glory: player.glory + event.reward.glory,
          },
        },
      };
    }

    // === Robo de cartas ===
    case 'CARDS_DRAWN': {
      const player = state.players[event.playerId];
      const drawnCards: typeof player.hand = [];
      const remainingDeck = [...player.abilityDeck];

      for (const cardInstanceId of event.cardInstanceIds) {
        const idx = remainingDeck.findIndex(c => c.instanceId === cardInstanceId);
        if (idx >= 0) {
          drawnCards.push({ ...remainingDeck[idx], zone: 'HAND' as Zone });
          remainingDeck.splice(idx, 1);
        }
      }

      return {
        ...state,
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            abilityDeck: remainingDeck,
            hand: [...player.hand, ...drawnCards],
          },
        },
      };
    }

    // === Perdida de cartas (del mazo al desgaste) ===
    case 'CARDS_LOST': {
      const player = state.players[event.playerId];
      const lostCards: typeof player.wearPile = [];
      const remainingDeck = [...player.abilityDeck];

      for (const cardInstanceId of event.cardInstanceIds) {
        const idx = remainingDeck.findIndex(c => c.instanceId === cardInstanceId);
        if (idx >= 0) {
          lostCards.push({ ...remainingDeck[idx], zone: 'WEAR_PILE' as Zone });
          remainingDeck.splice(idx, 1);
        }
      }

      return {
        ...state,
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            abilityDeck: remainingDeck,
            wearPile: [...player.wearPile, ...lostCards],
          },
        },
      };
    }

    // === Recuperacion de cartas ===
    case 'CARDS_RECOVERED': {
      const player = state.players[event.playerId];
      const recoveredCards: typeof player.abilityDeck = [];
      const remainingWear = [...player.wearPile];
      const remainingHand = [...player.hand];

      for (const cardInstanceId of event.cardInstanceIds) {
        // Buscar en wearPile primero
        const wearIdx = remainingWear.findIndex(c => c.instanceId === cardInstanceId);
        if (wearIdx >= 0) {
          const card = remainingWear[wearIdx];
          if (event.toZone === 'HAND') {
            recoveredCards.push({ ...card, zone: 'HAND' as Zone });
          } else {
            recoveredCards.push({ ...card, zone: 'ABILITY_DECK' as Zone });
          }
          remainingWear.splice(wearIdx, 1);
          continue;
        }
        // Buscar en hand (Daga ├ëlfica: la carta no lleg├│ a wearPile)
        const handIdx = remainingHand.findIndex(c => c.instanceId === cardInstanceId);
        if (handIdx >= 0) {
          const card = remainingHand[handIdx];
          if (event.toZone === 'HAND') {
            // Ya est├í en mano, mantenerla
            recoveredCards.push({ ...card, zone: 'HAND' as Zone });
          } else {
            recoveredCards.push({ ...card, zone: 'ABILITY_DECK' as Zone });
            remainingHand.splice(handIdx, 1);
          }
        }
      }

      if (event.toZone === 'HAND') {
        // Si recoveredCards incluye cartas ya en hand, mantener hand sin duplicar
        const handFromWear = recoveredCards.filter(c =>
          !remainingHand.some(h => h.instanceId === c.instanceId)
        );
        return {
          ...state,
          players: {
            ...state.players,
            [event.playerId]: {
              ...player,
              wearPile: remainingWear,
              hand: [...remainingHand, ...handFromWear],
            },
          },
        };
      }

      // BOTTOM_OF_DECK: anadir al final del mazo
      return {
        ...state,
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            wearPile: remainingWear,
            hand: remainingHand,
            abilityDeck: [...player.abilityDeck, ...recoveredCards],
          },
        },
      };
    }

    // === Recursos ===
    case 'GLORY_GAINED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        glory: p.glory + event.amount,
      }));

    case 'GLORY_LOST':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        glory: Math.max(0, p.glory - event.amount),
      }));

    case 'COINS_GAINED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        coins: p.coins + event.amount,
      }));

    case 'COINS_STOLEN':
      return {
        ...state,
        players: {
          ...state.players,
          [event.fromPlayerId]: {
            ...state.players[event.fromPlayerId],
            coins: state.players[event.fromPlayerId].coins - event.amount,
          },
          [event.toPlayerId]: {
            ...state.players[event.toPlayerId],
            coins: state.players[event.toPlayerId].coins + event.amount,
          },
        },
      };

    case 'WOUND_HEALED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        wounds: Math.max(0, p.wounds - event.amount),
      }));

    // === Movimiento de cartas ===
    case 'CARD_MOVED':
      return moveCard(state, event.cardInstanceId, event.to);

    case 'CARD_REMOVED_FROM_GAME':
      return removeCardFromAllZones(state, event.cardInstanceId);

    // === Ataque de la Horda ===
    case 'HORDE_ATTACKED':
      // El dano ya fue procesado como CARDS_LOST por el motor
      return state;

    // === Revelacion de enemigos ===
    case 'ENEMY_REVEALED':
      return state; // El enemigo ya esta en battlefield

    case 'WARLORD_REVEALED':
      return { ...state, warlordRevealed: true };

    // === Mercado ===
    case 'MARKET_PURCHASED': {
      const player = state.players[event.playerId];
      const card = state.market.find(c => c.instanceId === event.cardInstanceId);
      if (!card) return state;

      return {
        ...state,
        market: state.market.filter(c => c.instanceId !== event.cardInstanceId),
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            coins: player.coins - event.cost,
            hand: [...player.hand, { ...card, zone: 'HAND' as Zone }],
          },
        },
      };
    }

    case 'MARKET_REPLENISHED': {
      // Mover la carta del marketDeck al mercado (especificacion 3.5)
      const newCard = state.marketDeck.find(c => c.instanceId === event.cardInstanceId);
      if (!newCard) return state;
      return {
        ...state,
        market: [...state.market, { ...newCard, zone: 'MARKET' as Zone }],
        marketDeck: state.marketDeck.filter(c => c.instanceId !== event.cardInstanceId),
      };
    }

    // === Escenarios ===
    case 'SCENARIO_REVEALED':
      // Setear el escenario revelado (puede haber sido borrado por SCENARIO_DISCARDED previo)
      return {
        ...state,
        scenario: {
          instanceId: event.scenarioInstanceId,
          definitionId: event.definitionId,
          ownerId: 'scenario',
          zone: 'SCENARIO_ACTIVE' as Zone,
        },
        // Solitario: 1 moneda sobre el escenario revelado (spec ┬º4.1)
        scenarioCoins: state.mode === 'SOLO' ? 1 : 0,
      };

    case 'SCENARIO_DISCARDED':
      return { ...state, scenario: null, scenarioCoins: 0 };

    // === Pericias ===
    case 'HERO_ABILITY_USED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        heroUsesRemaining: event.usesRemaining,
      }));

    // === Prevencion ===
    case 'PREVENTION_APPLIED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        prevention: p.prevention + event.amount,
      }));

    case 'SHIELD_PLACED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        shields: p.shields + event.amount,
      }));

    case 'SHIELD_TRANSFERRED': {
      const fromPlayer = state.players[event.fromPlayerId];
      const toPlayer = state.players[event.toPlayerId];
      if (!fromPlayer || !toPlayer) return state;
      return {
        ...state,
        players: {
          ...state.players,
          [event.fromPlayerId]: { ...fromPlayer, shields: Math.max(0, fromPlayer.shields - event.amount) },
          [event.toPlayerId]: { ...toPlayer, shields: toPlayer.shields + event.amount },
        },
      };
    }

    case 'CANCELLATION_ACTIVATED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        damageCancellation: true,
      }));

    // === Enemigos ===
    case 'ENEMY_DAMAGE_DISABLED':
      return {
        ...state,
        battlefield: state.battlefield.map(e =>
          e.instanceId === event.enemyInstanceId
            ? { ...e, damageDisabled: true }
            : e
        ),
      };

    case 'VULNERABILITY_APPLIED':
      return {
        ...state,
        battlefield: state.battlefield.map(e =>
          e.instanceId === event.enemyInstanceId
            ? {
                ...e,
                modifiers: [
                  ...e.modifiers,
                  {
                    id: `vuln-${event.seq}`,
                    sourceId: event.enemyInstanceId,
                    layer: 'DAMAGE_BONUS',
                    timestamp: event.seq,
                    duration: 'UNTIL_END_OF_TURN',
                    amount: event.bonus,
                    targetId: event.enemyInstanceId,
                  },
                ],
              }
            : e
        ),
      };

    // === Modificadores ===
    case 'MODIFIER_ADDED': {
      // Aplicar modificador al objetivo (jugador, enemigo o mercado)
      const modifier: Modifier = {
        id: event.modifierId,
        sourceId: event.sourceId ?? '',
        layer: event.layer as ModifierLayer,
        timestamp: state.monotonicCounter,
        duration: (event.duration as Modifier['duration']) ?? 'UNTIL_END_OF_TURN',
        amount: event.amount ?? 0,
        filter: event.filter,
        scope: event.scope,
        targetId: event.targetId,
      };
      // Si el target es un enemigo del campo
      const enemy = state.battlefield.find(e => e.instanceId === event.targetId);
      if (enemy) {
        return {
          ...state,
          battlefield: state.battlefield.map(e =>
            e.instanceId === event.targetId
              ? { ...e, modifiers: [...e.modifiers, modifier] }
              : e
          ),
        };
      }
      // Si el target es un jugador
      if (state.players[event.targetId]) {
        return mapPlayerState(state, event.targetId, p => ({
          ...p,
          modifiers: [...p.modifiers, modifier],
        }));
      }
      // Si el target es 'market', aplicar modificador de coste
      if (event.targetId === 'market' && event.layer === 'MARKET_COST') {
        return { ...state, marketCostModifier: state.marketCostModifier + (event.amount ?? -1) };
      }
      return state;
    }

    case 'MODIFIER_EXPIRED': {
      const newPlayers = { ...state.players };
      for (const [id, p] of Object.entries(newPlayers)) {
        newPlayers[id] = {
          ...p,
          modifiers: p.modifiers.filter(m => m.id !== event.modifierId),
        };
      }
      return {
        ...state,
        players: newPlayers,
        battlefield: state.battlefield.map(e => ({
          ...e,
          modifiers: e.modifiers.filter(m => m.id !== event.modifierId),
        })),
      };
    }

    // === Heridas de heroe ===
    case 'HERO_WOUNDED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        wounds: event.woundCount,
      }));

    // === Mazo agotado y reciclado ===
    case 'DECK_EXHAUSTED':
      return state;

    case 'DECK_RESHUFFLED':
      return mapPlayerState(state, event.playerId, p => {
        // Si el evento incluye newOrder NO vacio, usarlo; si no, mantener orden lineal
        const newDeck = (Array.isArray(event.newOrder) && event.newOrder.length > 0)
          ? event.newOrder.map(id => {
              const card = p.wearPile.find(c => c.instanceId === id);
              return card ? { ...card, zone: 'ABILITY_DECK' as Zone } : null;
            }).filter((c): c is NonNullable<typeof c> => c !== null)
          : [...p.wearPile].map(c => ({ ...c, zone: 'ABILITY_DECK' as Zone }));
        return {
          ...p,
          abilityDeck: newDeck,
          wearPile: [],
        };
      });

    // === Evasion ===
    case 'EVASION_PERFORMED': {
      const player = state.players[event.playerId];
      const discarded = player.hand.filter(c => event.discardedCardInstanceIds.includes(c.instanceId));
      const remainingHand = player.hand.filter(c => !event.discardedCardInstanceIds.includes(c.instanceId));

      return {
        ...state,
        evasionDiscardedCount: event.discardedCardInstanceIds.length,
        players: {
          ...state.players,
          [event.playerId]: {
            ...player,
            hand: remainingHand,
            wearPile: [...player.wearPile, ...discarded.map(c => ({ ...c, zone: 'WEAR_PILE' as Zone }))],
          },
        },
      };
    }

    // === Fin de partida ===
    case 'GAME_ENDED':
      return { ...state, phase: 'FINISHED' };

    // === Cartas persistentes ===
    case 'PERSISTENT_CARD_PLACED':
      return mapPlayerState(state, event.playerId, p => ({
        ...p,
        // Retirar la carta de la mano (se mueve a IN_FRONT_OF_PLAYER)
        hand: p.hand.filter(c => c.instanceId !== event.cardInstanceId),
        persistentCards: [
          ...p.persistentCards,
          {
            instanceId: event.cardInstanceId,
            definitionId: event.cardDefinitionId,
            ownerId: event.playerId,
            zone: 'IN_FRONT_OF_PLAYER',
            persistentTrigger: event.trigger,
          },
        ],
      }));

    case 'PERSISTENT_CARD_REMOVED':
      return {
        ...state,
        players: Object.fromEntries(
          Object.entries(state.players).map(([id, p]) => [
            id,
            {
              ...p,
              persistentCards: p.persistentCards.filter(c => c.instanceId !== event.cardInstanceId),
            },
          ])
        ),
      };

    // === Leader ===
    case 'LEADER_DETERMINED':
      return { ...state, activePlayerId: event.playerId };

    // === Deck Shuffle ===
    case 'DECK_SHUFFLED': {
      if (event.deck === 'MARKET') {
        // Barajar mazo de Mercado
        const deckMap = new Map(state.marketDeck.map(c => [c.instanceId, c]));
        const newDeck = event.newOrder.map(id => deckMap.get(id)!).filter(Boolean);
        return { ...state, marketDeck: newDeck };
      }
      if (event.deck === 'HORDE') {
        // Barajar mazo de la Horda
        const deckMap = new Map(state.hordeDeck.map(c => [c.instanceId, c]));
        const newDeck = event.newOrder.map(id => deckMap.get(id)!).filter(Boolean);
        return { ...state, hordeDeck: newDeck };
      }
      // ABILITY: reordenar mazo del jugador
      const player = state.players[event.playerId];
      const deckMap = new Map(player.abilityDeck.map(c => [c.instanceId, c]));
      const newDeck = event.newOrder.map(id => deckMap.get(id)!).filter(Boolean);
      return {
        ...state,
        players: {
          ...state.players,
          [event.playerId]: { ...player, abilityDeck: newDeck },
        },
      };
    }

    // === Enemy Swapped ===
    case 'ENEMY_SWAPPED': {
      // El enemigo viejo vuelve al FONDO del mazo de la Horda, el nuevo entra al campo
      const oldEnemy = state.battlefield.find(e => e.instanceId === event.oldEnemyInstanceId);
      if (!oldEnemy) return state;
      const oldEnemyCard: CardInstance = {
        instanceId: oldEnemy.instanceId,
        definitionId: oldEnemy.definitionId,
        ownerId: 'horde',
        zone: 'HORDE_DECK',
      };
      const newEnemy: EnemyState = {
        instanceId: event.newEnemyInstanceId,
        definitionId: event.newEnemyDefinitionId,
        baseFortitude: event.newEnemyFortitude,
        wounds: 0,
        reward: event.newEnemyReward,
        modifiers: [],
        isWarlord: event.newEnemyIsWarlord,
        isOrc: event.newEnemyIsOrc,
        specialIcons: event.newEnemySpecialIcons,
        damageDisabled: false,
      };
      return {
        ...state,
        battlefield: state.battlefield.map(e =>
          e.instanceId === event.oldEnemyInstanceId ? newEnemy : e
        ),
        hordeDeck: [
          ...state.hordeDeck.filter(c => c.instanceId !== event.newEnemyInstanceId),
          oldEnemyCard,
        ],
      };
    }

    // === Enemy Returned to Horde ===
    case 'ENEMY_RETURNED_TO_HORDE': {
      const enemy = state.battlefield.find(e => e.instanceId === event.enemyInstanceId);
      if (!enemy) return state;
      const enemyCard: CardInstance = {
        instanceId: enemy.instanceId,
        definitionId: enemy.definitionId,
        ownerId: 'horde',
        zone: 'HORDE_DECK',
      };
      return {
        ...state,
        battlefield: state.battlefield.filter(e => e.instanceId !== event.enemyInstanceId),
        hordeDeck: event.position === 'BOTTOM'
          ? [...state.hordeDeck, enemyCard]
          : [enemyCard, ...state.hordeDeck],
      };
    }

    // === Damage Intercepted ===
    case 'DAMAGE_INTERCEPTED': {
      // Valerys: interceptar dano de otro heroe
      // El interceptor recibe el dano como perdida de cartas y gana 1 Gloria
      const interceptor = state.players[event.interceptorPlayerId];
      if (!interceptor) return state;
      if (event.amount <= 0) {
        // Registrar intercepcion: el dano real se aplicara en processHordeAttack
        return mapPlayerState(state, event.originalTargetPlayerId, p => ({
          ...p,
          interceptedBy: event.interceptorPlayerId,
          glory: p.glory,
        }));
      }
      // Aplicar dano como perdida de cartas (la Gloria ya se otorgo en valerysAbility)
      const lost = interceptor.abilityDeck.slice(0, event.amount).map(c => c.instanceId);
      return mapPlayerState(state, event.interceptorPlayerId, p => ({
        ...p,
        abilityDeck: p.abilityDeck.slice(lost.length),
        wearPile: [...p.wearPile, ...p.abilityDeck.slice(0, lost.length).map(c => ({ ...c, zone: 'WEAR_PILE' as Zone }))],
      }));
    }

    // === Cards Revealed to Player ===
    case 'CARDS_REVEALED_TO_PLAYER':
      // No cambia el estado del juego; es informativo para el cliente
      return state;

    default: {
      // Exhaustive check
      const _exhaustive: never = event;
      void _exhaustive;
      return state;
    }
  }
}

// ============================================================================
// Helpers
// ============================================================================

function mapPlayer(
  players: Record<string, PlayerState>,
  playerId: string,
  fn: (p: PlayerState) => PlayerState
): Record<string, PlayerState> {
  const player = players[playerId];
  if (!player) return players;
  return { ...players, [playerId]: fn(player) };
}

export function mapPlayerState(
  state: GameState,
  playerId: string,
  fn: (p: PlayerState) => PlayerState
): GameState {
  return { ...state, players: mapPlayer(state.players, playerId, fn) };
}

function moveCard(state: GameState, cardInstanceId: string, to: Zone): GameState {
  // Buscar la carta en todas las zonas del jugador propietario
  const newPlayers = { ...state.players };
  let found = false;
  let foundInPlayer = false;
  let movedCard: any = null;

  for (const [playerId, player] of Object.entries(newPlayers)) {
    const zones: (keyof PlayerState)[] = ['hand', 'abilityDeck', 'wearPile', 'persistentCards'];

    for (const zoneKey of zones) {
      const zoneCards = player[zoneKey] as any[];
      const idx = zoneCards.findIndex((c: any) => c.instanceId === cardInstanceId);
      if (idx >= 0) {
        movedCard = { ...zoneCards[idx], zone: to };
        const newZoneCards = [...zoneCards];
        newZoneCards.splice(idx, 1);

        newPlayers[playerId] = {
          ...player,
          [zoneKey]: newZoneCards,
        };

        // Anadir a la zona destino
        if (to === 'HAND') {
          newPlayers[playerId].hand = [...newPlayers[playerId].hand, movedCard];
        } else if (to === 'WEAR_PILE') {
          newPlayers[playerId].wearPile = [...newPlayers[playerId].wearPile, movedCard];
        } else if (to === 'ABILITY_DECK') {
          newPlayers[playerId].abilityDeck = [...newPlayers[playerId].abilityDeck, movedCard];
        }

        found = true;
        foundInPlayer = true;
        break;
      }
    }
    if (found) break;
  }

  // Si no se encontro en zonas de jugador, buscar en marketDeck/market
  if (!found) {
    const marketIdx = state.marketDeck.findIndex(c => c.instanceId === cardInstanceId);
    if (marketIdx >= 0) {
      movedCard = { ...state.marketDeck[marketIdx], zone: to };
      const newMarketDeck = [...state.marketDeck];
      newMarketDeck.splice(marketIdx, 1);
      state = { ...state, marketDeck: newMarketDeck };
      found = true;
    }
  }
  if (!found) {
    const marketIdx = state.market.findIndex(c => c.instanceId === cardInstanceId);
    if (marketIdx >= 0) {
      movedCard = { ...state.market[marketIdx], zone: to };
      const newMarket = [...state.market];
      newMarket.splice(marketIdx, 1);
      state = { ...state, market: newMarket };
      found = true;
    }
  }

  // Anadir la carta del mercado a la zona destino del jugador activo (si aplica)
  // Solo si la carta NO se encontro en zonas de jugador (viene del mercado)
  if (found && !foundInPlayer && movedCard && (to === 'HAND' || to === 'WEAR_PILE' || to === 'ABILITY_DECK')) {
    const activeId = state.activePlayerId;
    if (activeId && newPlayers[activeId]) {
      const alreadyAdded = newPlayers[activeId].hand.some((c: any) => c.instanceId === cardInstanceId)
        || newPlayers[activeId].abilityDeck.some((c: any) => c.instanceId === cardInstanceId)
        || newPlayers[activeId].wearPile.some((c: any) => c.instanceId === cardInstanceId);
      if (!alreadyAdded) {
        // D377: Clonar el jugador activo para preservar inmutabilidad
        const target = newPlayers[activeId];
        if (to === 'HAND') newPlayers[activeId] = { ...target, hand: [...target.hand, movedCard] };
        else if (to === 'WEAR_PILE') newPlayers[activeId] = { ...target, wearPile: [...target.wearPile, movedCard] };
        else if (to === 'ABILITY_DECK') newPlayers[activeId] = { ...target, abilityDeck: [...target.abilityDeck, movedCard] };
      }
    }
  }

  // Tambien manejar movimiento de una carta del jugador al marketDeck
  if (found && movedCard && to === 'MARKET_DECK') {
    state = { ...state, marketDeck: [...state.marketDeck, movedCard] };
  }
  // Tambien manejar movimiento de una carta al mercado visible
  if (found && movedCard && to === 'MARKET') {
    state = { ...state, market: [...state.market, movedCard] };
  }

  return { ...state, players: newPlayers };
}

function removeCardFromAllZones(state: GameState, cardInstanceId: string): GameState {
  const newPlayers = { ...state.players };

  for (const [playerId, player] of Object.entries(newPlayers)) {
    newPlayers[playerId] = {
      ...player,
      hand: player.hand.filter(c => c.instanceId !== cardInstanceId),
      abilityDeck: player.abilityDeck.filter(c => c.instanceId !== cardInstanceId),
      wearPile: player.wearPile.filter(c => c.instanceId !== cardInstanceId),
      persistentCards: player.persistentCards.filter(c => c.instanceId !== cardInstanceId),
    };
  }

  return {
    ...state,
    players: newPlayers,
    battlefield: state.battlefield.filter(e => e.instanceId !== cardInstanceId),
    market: state.market.filter(c => c.instanceId !== cardInstanceId),
  };
}

// ============================================================================
// Replay: aplicar una lista de eventos al estado inicial
// ============================================================================

export function replayEvents(initialState: GameState, events: GameEvent[]): GameState {
  return events.reduce(applyEvent, initialState);
}

