/**
 * HeroAbilities ÔÇö Pericias de h├®roes.
 *
 * Cada heroe tiene una Pericia especial con un numero limitado de usos.
 * Las Pericias se activan con el comando USE_HERO_ABILITY.
 *
 * Pericias implementadas:
 * - Aranel: buscar carta en mazo y cambiar por mano
 * - Neddia: buscar en mazo de Mercado y cambiar
 * - Taheral: ganar 2 monedas por carta descartada en Evasion
 * - Idril: mirar 3 cartas inferiores de la Horda y reordenar
 * - Feldon: perder mitad de cartas en ataque de Horda (pasiva)
 * - Valerys: interceptar dano de otro heroe y ganar Gloria
 * - Beleth-Il: recuperar primera carta fallida de Disparo Rapido (pasiva)
 * - Lisavette: usar Escudo durante ataque de Horda a otro heroe (pasiva)
 */

import type {
  GameState,
  GameEvent,
  PendingChoice,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

let abilitySeq = 0;
function nextSeq(): number {
  return ++abilitySeq;
}
export function resetAbilitySeq(): void {
  abilitySeq = 0;
}

export interface AbilityResult {
  events: GameEvent[];
  state: GameState;
  /** Obsoleto: las elecciones se guardan en state.pendingChoices */
  pendingChoice: null;
}

/**
 * Activar la Pericia de un heroe.
 */
export function useHeroAbility(
  state: GameState,
  playerId: string,
  _rng: DeterministicRng,
  catalog: CatalogLoadResult,
  targetId?: string,
  targetEnemyId?: string,
): AbilityResult {
  const player = state.players[playerId];
  if (!player) {
    return { events: [], state, pendingChoice: null };
  }

  if (player.heroUsesRemaining <= 0) {
    return { events: [], state, pendingChoice: null };
  }

  const heroDef = catalog.byId.get(player.heroId);
  if (!heroDef) {
    return { events: [], state, pendingChoice: null };
  }

  const events: GameEvent[] = [];

  // Verificaciones previas segun el heroe (antes de consumir el uso)
  // D370: Lisavette requiere carta "Escudo" (warrior.shield) en mano
  if (heroDef.name === 'Lisavette' && !player.hand.find(c => c.definitionId === 'warrior.shield')) {
    return { events: [], state, pendingChoice: null };
  }

  // Para Val├¿rys/Lisavette sin target, NO consumir el uso a├║n (se consume al resolver)
  // D370: Lisavette necesita adem├ís elegir un enemigo cuyo da├▒o prevenir
  const needsTargetFirst = (heroDef.name === 'Val├¿rys' || heroDef.name === 'Lisavette') && !targetId;
  if (needsTargetFirst) {
    // Crear el pendingChoice sin consumir el uso
    switch (heroDef.name) {
      case 'Val├¿rys':
        return valerysAbility(state, playerId, undefined, events);
      case 'Lisavette':
        return lisavetteAbility(state, playerId, undefined, undefined, events);
    }
  }

  // D370: Lisavette con h├®roe objetivo pero sin enemigo objetivo ÔåÆ pedir SELECT_ENEMY
  if (heroDef.name === 'Lisavette' && targetId && !targetEnemyId) {
    return lisavetteAbility(state, playerId, targetId, undefined, events);
  }

  // H├®roes con pericias pasivas: NO consumir uso ni emitir HERO_ABILITY_USED
  // (se activan autom├íticamente durante la fase correspondiente)
  const passiveHeroes = ['Taheral', 'Feldon', 'Beleth-Il', 'BelethIl'];
  if (passiveHeroes.includes(heroDef.name)) {
    return { events: [], state, pendingChoice: null };
  }

  // D374: Pre-validacion ÔÇö no consumir uso si no hay cartas disponibles para la pericia
  if (heroDef.name === 'Aranel' && player.abilityDeck.length === 0) {
    return { events: [], state, pendingChoice: null };
  }
  if (heroDef.name === 'Neddia' && state.marketDeck.length === 0) {
    return { events: [], state, pendingChoice: null };
  }
  if (heroDef.name === 'Idril' && state.hordeDeck.length < 1) {
    return { events: [], state, pendingChoice: null };
  }

  // Evento: pericia usada
  events.push({
    type: 'HERO_ABILITY_USED',
    playerId,
    usesRemaining: player.heroUsesRemaining - 1,
    seq: nextSeq(),
  });

  // Ejecutar efecto segun el heroe
  let newState: GameState = {
    ...state,
    players: {
      ...state.players,
      [playerId]: {
        ...player,
        heroUsesRemaining: player.heroUsesRemaining - 1,
      },
    },
  };

  switch (heroDef.name) {
    case 'Aranel':
      return aranelAbility(newState, playerId, events);

    case 'Neddia':
      return neddiaAbility(newState, playerId, events);

    case 'Taheral':
      // Taheral se activa durante Evasion, no directamente
      return { events, state: newState, pendingChoice: null };

    case 'Idril':
      return idrilAbility(newState, playerId, events);

    case 'Val├¿rys':
    case 'Valerys':
      return valerysAbility(newState, playerId, targetId, events);

    case 'Feldon':
      // Feldon es pasiva (se aplica durante HORDE_ATTACK)
      return { events, state: newState, pendingChoice: null };

    case 'Beleth-Il':
    case 'BelethIl':
      // Beleth-Il es pasiva (se aplica durante Disparo Rapido)
      return { events, state: newState, pendingChoice: null };

    case 'Lisavette':
      // Lisavette: pasiva ÔÇö durante ataque de Horda a otro heroe,
      // puede usar una carta de Escudo para prevenir el da├▒o de un enemigo espec├¡fico
      // y robar hasta 2 Monedas de ese H├®roe.
      // (la verificacion de escudos se hace antes de consumir el uso)
      return lisavetteAbility(newState, playerId, targetId, targetEnemyId, events);

    default:
      return { events, state: newState, pendingChoice: null };
  }
}

// ============================================================================
// Aranel ÔÇö buscar carta en mazo y cambiar por mano
// ============================================================================

function aranelAbility(
  state: GameState,
  playerId: string,
  events: GameEvent[],
): AbilityResult {
  const player = state.players[playerId];
  // Crear PendingChoice con SEARCH_DECK y las cartas del mazo como opciones
  const choice: PendingChoice = {
    choiceId: `aranel-${playerId}-${nextSeq()}`,
    playerId,
    type: 'SEARCH_DECK',
    prompt: 'Aranel: Selecciona una carta de tu mazo para intercambiar con una de tu mano',
    options: player.abilityDeck.map(c => c.instanceId),
    minSelections: 1,
    maxSelections: 1,
  };
  return {
    events,
    state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
    pendingChoice: null,
  };
}

// ============================================================================
// Neddia ÔÇö buscar en mazo de Mercado y cambiar
// ============================================================================

function neddiaAbility(
  state: GameState,
  playerId: string,
  events: GameEvent[],
): AbilityResult {
  // Crear PendingChoice con SEARCH_MARKET_DECK y las cartas del marketDeck como opciones
  const choice: PendingChoice = {
    choiceId: `neddia-${playerId}-${nextSeq()}`,
    playerId,
    type: 'SEARCH_MARKET_DECK',
    prompt: 'Neddia: Selecciona hasta 2 cartas del mazo de Mercado para intercambiar',
    options: state.marketDeck.map(c => c.instanceId),
    minSelections: 1,
    maxSelections: 2,
  };
  return {
    events,
    state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
    pendingChoice: null,
  };
}

// ============================================================================
// Idril ÔÇö mirar 3 cartas inferiores de la Horda y reordenar
// ============================================================================

function idrilAbility(
  state: GameState,
  playerId: string,
  events: GameEvent[],
): AbilityResult {
  // Mirar las 3 cartas inferiores del mazo de la Horda
  const bottom3 = state.hordeDeck.slice(-3);
  if (bottom3.length === 0) {
    return { events, state, pendingChoice: null };
  }
  // Crear pendingChoice con SELECT_ORDER
  const choice: PendingChoice = {
    choiceId: `idril-${playerId}-${nextSeq()}`,
    playerId,
    type: 'SELECT_ORDER',
    prompt: 'Idril: Reordena las 3 cartas inferiores del mazo de la Horda',
    options: bottom3.map(c => c.instanceId),
    minSelections: bottom3.length,
    maxSelections: bottom3.length,
  };
  return {
    events,
    state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
    pendingChoice: null,
  };
}

// ============================================================================
// Valerys ÔÇö interceptar dano de otro heroe y ganar Gloria
// ============================================================================

function valerysAbility(
  state: GameState,
  playerId: string,
  targetHeroId: string | undefined,
  events: GameEvent[],
): AbilityResult {
  if (!targetHeroId) {
    const otherHeroes = state.playerOrder.filter(id => id !== playerId);
    const choice: PendingChoice = {
      choiceId: `valerys-${playerId}-${nextSeq()}`,
      playerId,
      type: 'SELECT_HERO',
      prompt: 'Val├¿rys: Selecciona el heroe cuyo dano vas a interceptar',
      options: otherHeroes,
      minSelections: 1,
      maxSelections: 1,
    };
    return {
      events,
      state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
      pendingChoice: null,
    };
  }

  // Emitir DAMAGE_INTERCEPTED para registrar la intercepcion
  // El dano real se redirige en processHordeAttack; la Gloria se otorga aqui
  events.push({
    type: 'DAMAGE_INTERCEPTED',
    interceptorPlayerId: playerId,
    originalTargetPlayerId: targetHeroId,
    amount: 0, // El dano real se determina en el motor de fases
    seq: nextSeq(),
  });
  // Otorgar 1 ficha de Gloria al interceptor
  events.push({
    type: 'GLORY_GAINED',
    playerId,
    amount: 1,
    seq: nextSeq(),
  });

  return { events, state, pendingChoice: null };
}

// ============================================================================
// Taheral ÔÇö ganar 2 monedas por carta descartada en Evasion (pasiva)
// ============================================================================

export function taheralEvasionBonus(
  state: GameState,
  playerId: string,
  discardedCount: number,
): GameEvent[] {
  const player = state.players[playerId];
  if (!player) return [];

  const heroDef = state.players[playerId].heroId;
  // Verificar si el heroe es Taheral
  // En una implementacion completa, verificamos contra el catalogo
  // Por ahora, devolvemos eventos si el heroId coincide
  if (heroDef !== 'hero.taheral') return [];
  // Verificar que quedan usos de Pericia disponibles
  if ((player.heroUsesRemaining ?? 0) <= 0) return [];

  const coinsGained = discardedCount * 2;
  return [{
    type: 'COINS_GAINED',
    playerId,
    amount: coinsGained,
    seq: nextSeq(),
  }];
}

// ============================================================================
// Feldon ÔÇö perder mitad de cartas en ataque de Horda (pasiva)
// ============================================================================

export function feldonDamageReduction(
  state: GameState,
  playerId: string,
  damage: number,
): number {
  const player = state.players[playerId];
  if (!player) return damage;
  if (player.heroId !== 'hero.feldon') return damage;
  if ((player.heroUsesRemaining ?? 0) <= 0) return damage;
  return Math.floor(damage / 2);
}

// ============================================================================
// Beleth-Il ÔÇö recuperar primera carta fallida de Disparo Rapido (pasiva)
// ============================================================================

export function belethIlRapidShotRecovery(
  state: GameState,
  playerId: string,
  failedCardInstanceId: string,
): GameEvent[] {
  const player = state.players[playerId];
  if (!player) return [];
  if (player.heroId !== 'hero.beleth-il') return [];

  // Recuperar la carta fallida: moverla del fondo del mazo (ABILITY_DECK) a la mano
  // El "robar otra carta" se hace en resolver.ts tras llamar a esta funci├│n
  return [
    {
      type: 'CARD_MOVED',
      cardInstanceId: failedCardInstanceId,
      from: 'ABILITY_DECK',
      to: 'HAND',
      seq: nextSeq(),
    },
  ];
}

// ============================================================================
// Lisavette ÔÇö usar Escudo para otro heroe + robar hasta 2 Monedas (pasiva)
// ============================================================================

function lisavetteAbility(
  state: GameState,
  playerId: string,
  targetHeroId: string | undefined,
  targetEnemyId: string | undefined,
  events: GameEvent[],
): AbilityResult {
  // Paso 1: Sin h├®roe objetivo ÔåÆ pedir SELECT_HERO
  if (!targetHeroId) {
    const otherHeroes = state.playerOrder.filter(id => id !== playerId);
    const choice: PendingChoice = {
      choiceId: `lisavette-${playerId}-${nextSeq()}`,
      playerId,
      type: 'SELECT_HERO',
      prompt: 'Lisavette: Selecciona el heroe al que vas a proteger con un Escudo',
      options: otherHeroes,
      minSelections: 1,
      maxSelections: 1,
    };
    return {
      events,
      state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
      pendingChoice: null,
    };
  }

  // Paso 2: Con h├®roe objetivo pero sin enemigo objetivo ÔåÆ pedir SELECT_ENEMY
  if (!targetEnemyId) {
    const enemies = state.battlefield
      .filter(e => e.wounds < (e.effectiveFortitude ?? e.baseFortitude))
      .map(e => e.instanceId);
    const choice: PendingChoice = {
      choiceId: `lisavette-enemy-${playerId}-${nextSeq()}`,
      playerId,
      type: 'SELECT_ENEMY',
      prompt: 'Lisavette: Selecciona el enemigo cuyo da├▒o vas a prevenir al h├®roe',
      options: enemies,
      minSelections: 1,
      maxSelections: 1,
      resolutionContext: {
        activePlayerId: playerId,
        currentCardId: '',
        currentCardName: 'Lisavette',
        currentCardInstanceId: '',
        selectedEnemyId: null,
        cardsPlayedThisTurn: {},
        cardsPlayedAgainstEnemy: {},
        drawnCardInstanceId: null,
        sourceZone: 'HAND',
        enemiesDefeatedThisResolution: [],
        depth: 0,
        chosenHeroTarget: targetHeroId,
      },
    };
    return {
      events,
      state: { ...state, pendingChoices: [...state.pendingChoices, choice] },
      pendingChoice: null,
    };
  }

  // Paso 3: Con ambos objetivos ÔåÆ ejecutar la pericia
  // D370: Verificar que el jugador tiene una carta de "Escudo" (warrior.shield) en mano
  const player = state.players[playerId];
  const shieldCard = player.hand.find(c => c.definitionId === 'warrior.shield');
  if (!shieldCard) {
    return { events, state, pendingChoice: null };
  }

  // D370: Jugar la carta de Escudo ÔÇö mover de mano a Desgaste
  events.push({
    type: 'CARD_PLAYED',
    playerId,
    cardInstanceId: shieldCard.instanceId,
    cardDefinitionId: 'warrior.shield',
    cardName: 'Escudo',
    seq: nextSeq(),
  });
  events.push({
    type: 'CARD_MOVED',
    cardInstanceId: shieldCard.instanceId,
    from: 'HAND',
    to: 'WEAR_PILE',
    seq: nextSeq(),
  });

  // D370: Prevenir el da├▒o del enemigo espec├¡fico al h├®roe objetivo
  // Usar ENEMY_DAMAGE_DISABLED para que el enemigo seleccionado no cause da├▒o
  // en el Ataque de la Horda (processHordeAttack salta enemigos con damageDisabled)
  events.push({
    type: 'ENEMY_DAMAGE_DISABLED',
    enemyInstanceId: targetEnemyId,
    seq: nextSeq(),
  });

  // D370: Robar hasta 2 Monedas del heroe objetivo
  const targetPlayer = state.players[targetHeroId];
  const coinsToSteal = Math.min(2, targetPlayer?.coins ?? 0);
  if (coinsToSteal > 0) {
    events.push({
      type: 'COINS_STOLEN',
      fromPlayerId: targetHeroId,
      toPlayerId: playerId,
      amount: coinsToSteal,
      seq: nextSeq(),
    });
  }

  return { events, state, pendingChoice: null };
}

/**
 * MulticlassMode ÔÇö reglas del modo multiclase (4 jugadores).
 *
 * Diferencias respecto al modo estandar:
 * 1. 2 Se├▒ores de la Guerra en la Horda (en lugar de 1).
 * 2. Construccion de mazo multiclase: minimo 5 cartas por clase, 15 total.
 * 3. Mercado de 5 cartas (igual que modo normal).
 * 4. La partida termina cuando ambos Se├▒ores son derrotados.
 * 5. Mano inicial de 4 cartas, campo inicial de 3 Huestes (igual que modo normal).
 *
 * TODO: la seleccion de 2 clases por jugador y la construccion del mazo
 * de 15 cartas con minimo 5 de cada clase requiere una interfaz de configuracion
 * que permita elegir 2 clases. Por ahora se usa una sola clase.
 */

import type {
  GameState,
  GameEvent,
  GameConfig,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import type { CatalogLoadResult } from '@nt4h/catalog';
import { setupGame } from '../phases/setup.js';

/**
 * Validar que un mazo multiclase cumple las reglas:
 * - Minimo 5 cartas por clase
 * - 15 cartas total
 */
export function validateMulticlassDeck(
  deckCardIds: string[],
  catalog: CatalogLoadResult,
): { ok: boolean; errors: string[] } {
  const errors: string[] = [];

  if (deckCardIds.length !== 15) {
    errors.push(`Deck must have exactly 15 cards, got ${deckCardIds.length}`);
  }

  // Contar cartas por clase
  const classCounts: Record<string, number> = {};
  for (const cardId of deckCardIds) {
    const card = catalog.byId.get(cardId);
    if (!card) {
      errors.push(`Card not found: ${cardId}`);
      continue;
    }
    if (card.heroClass) {
      classCounts[card.heroClass] = (classCounts[card.heroClass] ?? 0) + 1;
    }
  }

  for (const [cls, count] of Object.entries(classCounts)) {
    if (count < 5) {
      errors.push(`Class ${cls} has only ${count} cards, minimum is 5`);
    }
  }

  return { ok: errors.length === 0, errors };
}

/**
 * Configurar el modo multiclase.
 * Delega a setupGame que ya maneja MULTICLASS con secondDeckId:
 * - m├¡nimo 5 cartas de cada clase, 15 total
 * - 2 Se├▒ores en 4 jugadores
 * - Mercado filtrado por capabilities
 */
export function setupMulticlassMode(
  config: GameConfig,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[]; rng: DeterministicRng; errors: string[] } {
  // Delegar a setupGame que ya implementa todas las reglas multiclase correctamente
  const result = setupGame(config, catalog);
  return {
    state: result.state,
    events: result.events,
    rng: result.rng,
    errors: result.errors,
  };
}

/**
 * Comprobar si la partida multiclase ha terminado (2 Se├▒ores derrotados).
 */
export function isMulticlassGameEnded(state: GameState): boolean {
  // D355: La partida termina cuando ambos Se├▒ores son derrotados,
  // no quedan enemigos en el campo y el mazo de la Horda est├í vac├¡o
  return state.warlordsDefeatedCount >= 2 && state.battlefield.length === 0 && state.hordeDeck.length === 0;
}

/**
 * SoloMode ÔÇö reglas especiales del modo solitario.
 *
 * Diferencias respecto al modo estandar:
 * 1. Huestes sin F2 (no hay segunda cara de recompensa).
 * 2. 6 monedas iniciales (en lugar de 2).
 * 3. 5 cartas de Mercado (en lugar de 4).
 * 4. Sistema de Apoyos: pagar 2 monedas por mazo de Apoyo, robar 1 carta de Apoyo.
 * 5. Excepciones:
 *    - Robar Bolsillos: roba 1 Moneda del mazo de Apoyo en lugar de otros heroes.
 *    - Disparo Rapido: si se agota el mazo, se recicla el desgaste sin herida.
 * 6. Puntuacion solitaria: basada en Gloria + bonificaciones por condiciones.
 */

import type {
  GameState,
  GameEvent,
  GameConfig,
  CardInstance,
  Zone,
  PlayerState,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

let soloSeq = 0;
function nextSeq(): number {
  return ++soloSeq;
}
export function resetSoloSeq(): void {
  soloSeq = 0;
}

/**
 * Configurar el modo solitario:
 * - 6 monedas iniciales
 * - 5 cartas de Mercado
 * - Mazos de Apoyo (uno por heroe seleccionado)
 * - Huestes sin F2 (recompensas simplificadas)
 */
export function setupSoloMode(
  config: GameConfig,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[]; rng: DeterministicRng; errors: string[] } {
  const errors: string[] = [];
  const rng = new DeterministicRng(config.seed);

  // Validar que es modo solitario
  if (config.mode !== 'SOLO') {
    errors.push('Config mode is not SOLO');
    return { state: createEmptyState(), events: [], rng, errors };
  }

  // Validar que hay exactamente 1 jugador
  if (config.heroes.length !== 1) {
    errors.push('Solo mode requires exactly 1 player');
  }

  // Construir estado base
  const state = createEmptyState();
  state.mode = 'SOLO';
  state.playerOrder = [config.heroes[0].playerId];

  // Jugador solitario
  const heroConfig = config.heroes[0];
  const heroDef = catalog.byId.get(heroConfig.heroId);
  if (!heroDef) {
    errors.push(`Hero not found: ${heroConfig.heroId}`);
    return { state, events: [], rng, errors };
  }

  // Construir mazo de habilidad
  const heroClass = inferHeroClass(heroDef);
  const classCards = catalog.byClass.get(heroClass) ?? [];
  const deckInstances: CardInstance[] = [];
  for (const card of classCards) {
    for (let i = 0; i < card.copies; i++) {
      deckInstances.push({
        instanceId: `solo-ability-${card.id}-${i}`,
        definitionId: card.id,
        ownerId: heroConfig.playerId,
        zone: 'ABILITY_DECK' as Zone,
      });
    }
  }
  const shuffledDeck = rng.shuffle(deckInstances);
  const hand = shuffledDeck.slice(0, 4).map(c => ({ ...c, zone: 'HAND' as Zone }));
  const remainingDeck = shuffledDeck.slice(4);

  const player: PlayerState = {
    playerId: heroConfig.playerId,
    heroId: heroConfig.heroId,
    heroFace: heroConfig.heroFace,
    // En modo solitario no se usa la Pericia del heroe (especificacion ┬º4.1)
    heroUsesRemaining: 0,
    heroMaxUses: 0,
    glory: 0,
    coins: 6, // 6 monedas iniciales en solitario
    wounds: 0,
    maxWounds: heroDef.maxWounds ?? 3,
    capabilities: heroDef.capabilities ?? [],
    abilityDeck: remainingDeck,
    hand,
    wearPile: [],
    trophies: [],
    shields: 0,
    prevention: 0,
    damageCancellation: false,
    interceptedBy: null,
    modifiers: [],
    cardsPlayedThisTurn: {},
    cardsPlayedAgainstEnemy: {},
    oncePerTurnUsed: new Set(),
    persistentCards: [],
    supportDecks: [], // Se rellenara con los mazos de Apoyo
  };

  state.players[heroConfig.playerId] = player;
  state.activePlayerId = heroConfig.playerId;

  // Construir Horda: retirar Huestes de Fortaleza 2 (especificacion ┬º4.1)
  // Quedan 22 Huestes en solitario
  const hordeCardsAll = catalog.byType.get('HORDE') ?? [];
  const hordeCards = hordeCardsAll.filter(c => (c.printedFortitude ?? 0) !== 2);
  const hordeInstances: CardInstance[] = hordeCards.map(card => ({
    instanceId: `solo-horde-${card.id}`,
    definitionId: card.id,
    ownerId: 'horde',
    zone: 'HORDE_DECK' as Zone,
  }));
  state.hordeDeck = rng.shuffle(hordeInstances);

  // D359: A├▒adir 1 Se├▒or de la Guerra al principio (parte superior del mazo)
  // El motor roba desde la parte inferior (length-1), as├¡ que el Se├▒or
  // solo saldr├í cuando el mazo se agote.
  const warlordCards = catalog.byType.get('WARLORD') ?? [];
  if (warlordCards.length > 0) {
    state.hordeDeck.unshift({
      instanceId: 'solo-warlord-1',
      definitionId: warlordCards[0].id,
      ownerId: 'horde',
      zone: 'HORDE_DECK' as Zone,
    });
  }

  // D359: Colocar 3 Huestes en el campo desde la parte inferior (especificacion ┬º3.2.5)
  const enemiesInField = state.hordeDeck.slice(-3);
  state.hordeDeck = state.hordeDeck.slice(0, -3);
  for (const enemyCard of enemiesInField) {
    const enemyDef = catalog.byId.get(enemyCard.definitionId);
    if (!enemyDef) continue;
    state.battlefield.push({
      instanceId: enemyCard.instanceId,
      definitionId: enemyCard.definitionId,
      baseFortitude: enemyDef.printedFortitude ?? 1,
      wounds: 0,
      reward: enemyDef.reward ?? { coins: 0, glory: 0 },
      modifiers: [],
      isWarlord: enemyDef.type === 'WARLORD',
      isOrc: enemyDef.isOrc ?? false,
      specialIcons: enemyDef.specialIcons ?? [],
      damageDisabled: false,
    });
  }

  // Mercado solitario: 5 cartas, max 1 copia de cada (especificacion ┬º4.1)
  // No se reponen al comprar
  const marketCardsAll = catalog.byType.get('MARKET') ?? [];
  const marketInstances: CardInstance[] = marketCardsAll.map(card => ({
    instanceId: `solo-market-${card.id}`,
    definitionId: card.id,
    ownerId: 'market',
    zone: 'MARKET_DECK' as Zone,
  }));
  // Barajar y tomar 5 (sin duplicados por definicion)
  // Especificacion ┬º4.1: en solitario no se reponen las cartas de Mercado.
  // Las cartas no seleccionadas se descartan (marketDeck vacio).
  const shuffledMarket = rng.shuffle(marketInstances);
  state.marketDeck = []; // Solitario: no hay mazo de Mercado oculto
  state.market = shuffledMarket.slice(0, 5).map(c => ({ ...c, zone: 'MARKET' as Zone }));

  // Escenarios
  if (config.useScenarios) {
    const scenarioCards = catalog.byType.get('SCENARIO') ?? [];
    // Filtrar escenarios no validos en solitario
    const validScenarios = scenarioCards.filter(s => s.id !== 'scenario.tears-of-aradiel' && s.id !== 'scenario.cemenmar-wastes');
    state.scenarioDeck = validScenarios.map(card => ({
      instanceId: `solo-scenario-${card.id}`,
      definitionId: card.id,
      ownerId: 'scenario',
      zone: 'SCENARIO_DECK' as Zone,
    }));
    state.scenarioDeck = rng.shuffle(state.scenarioDeck);

    if (state.scenarioDeck.length > 0) {
      state.scenario = { ...state.scenarioDeck[0], zone: 'SCENARIO_ACTIVE' as Zone };
      state.scenarioDeck = state.scenarioDeck.slice(1);
      // Colocar 1 moneda sobre el escenario activo (especificacion ┬º4.1)
      state.scenarioCoins = 1;
    }
  }

  // Mazos de Apoyo (uno por heroe seleccionado en config.soloSupportHeroIds)
  if (config.soloSupportHeroIds) {
    for (const supportHeroId of config.soloSupportHeroIds) {
      const supportHeroDef = catalog.byId.get(supportHeroId);
      if (!supportHeroDef) continue;
      const supportClass = inferHeroClass(supportHeroDef);
      const supportClassCards = catalog.byClass.get(supportClass) ?? [];
      const supportDeck: CardInstance[] = [];
      for (const card of supportClassCards) {
        for (let i = 0; i < card.copies; i++) {
          supportDeck.push({
            instanceId: `solo-support-${supportHeroId}-${card.id}-${i}`,
            definitionId: card.id,
            ownerId: heroConfig.playerId,
            zone: 'ABILITY_DECK' as Zone,
          });
        }
      }
      player.supportDecks.push(rng.shuffle(supportDeck));
    }
  }

  state.phase = 'INITIAL_PLAYER_SELECTION';
  state.rngState = rng.serialize();

  return { state, events: [], rng, errors };
}

/**
 * Sistema de Apoyos en modo solitario (especificacion ┬º4.2).
 *
 * Costes de apertura de mazos de Apoyo:
 * - 1er mazo: 3 monedas
 * - 2┬║ mazo: +2 monedas (5 total)
 * - 3er mazo: +1 moneda (6 total)
 *
 * Robar 1 carta de un mazo de Apoyo:
 * - Pagar 2 Gloria O 5 monedas por la primera carta
 * - +1 Gloria O +2 monedas por cada carta adicional
 *
 * Solo se puede usar 1 mazo de Apoyo por turno.
 * La carta robada se devuelve al fondo de su mazo al final del turno.
 */
export function openSupportDeck(
  state: GameState,
  playerId: string,
  supportDeckIndex: number,
): { state: GameState; events: GameEvent[]; error?: string } {
  const events: GameEvent[] = [];
  const player = state.players[playerId];
  if (!player) return { state, events, error: 'Player not found' };

  if (supportDeckIndex < 0 || supportDeckIndex >= player.supportDecks.length) {
    return { state, events, error: 'Invalid support deck index' };
  }

  // D362: Los mazos deben abrirse secuencialmente (spec ┬º4.1)
  // El coste es 3 para el 1er mazo, 5 para el 2┬║, 6 para el 3┬║
  const openedCount = player.supportDecksOpened ?? 0;
  if (supportDeckIndex !== openedCount) {
    return { state, events, error: 'Must open the next sequential support deck' };
  }

  let cost: number;
  if (openedCount === 0) cost = 3;
  else if (openedCount === 1) cost = 5;
  else cost = 6;

  if (player.coins < cost) {
    return { state, events, error: `Not enough coins (need ${cost})` };
  }

  events.push({
    type: 'COINS_GAINED',
    playerId,
    amount: -cost,
    seq: nextSeq(),
  });

  return {
    state: {
      ...state,
      players: {
        ...state.players,
        [playerId]: {
          ...player,
          // D350: No pre-descontar coins; el evento COINS_GAINED negativo ya aplica el descuento
          supportDecksOpened: openedCount + 1,
        },
      },
    },
    events,
  };
}

/**
 * Robar 1 carta de un mazo de Apoyo.
 * Pagar 2 Gloria O 5 monedas por la primera; +1 Gloria O +2 monedas por cada extra.
 */
export function buySupportCard(
  state: GameState,
  playerId: string,
  supportDeckIndex: number,
  payment: { type: 'GLORY'; amount: number } | { type: 'COINS'; amount: number },
): { state: GameState; events: GameEvent[]; error?: string } {
  const events: GameEvent[] = [];
  const player = state.players[playerId];
  if (!player) return { state, events, error: 'Player not found' };

  if (supportDeckIndex < 0 || supportDeckIndex >= player.supportDecks.length) {
    return { state, events, error: 'Invalid support deck index' };
  }

  // D358: Verificar que el mazo de Apoyo haya sido abierto previamente
  const openedCount = player.supportDecksOpened ?? 0;
  if (supportDeckIndex >= openedCount) {
    return { state, events, error: 'Support deck not opened yet' };
  }

  // Especificacion ┬º4.2: solo se puede usar un mazo de Apoyo por turno
  const usedIndex = player.supportDeckIndexUsedThisTurn ?? null;
  if (usedIndex !== null && usedIndex !== supportDeckIndex) {
    return { state, events, error: 'Already used a different support deck this turn' };
  }

  const supportDeck = player.supportDecks[supportDeckIndex];
  if (supportDeck.length === 0) {
    return { state, events, error: 'Support deck is empty' };
  }

  // Coste: primera carta = 2 Gloria o 5 monedas; cada extra = +1 Gloria o +2 monedas
  const cardsDrawnThisTurn = player.supportCardsDrawnThisTurn ?? 0;
  const gloryCost = 2 + cardsDrawnThisTurn;
  const coinsCost = 5 + cardsDrawnThisTurn * 2;

  if (payment.type === 'GLORY') {
    if (player.glory < gloryCost) {
      return { state, events, error: `Not enough glory (need ${gloryCost})` };
    }
    events.push({
      type: 'GLORY_GAINED',
      playerId,
      amount: -gloryCost,
      seq: nextSeq(),
    });
  } else {
    if (player.coins < coinsCost) {
      return { state, events, error: `Not enough coins (need ${coinsCost})` };
    }
    events.push({
      type: 'COINS_GAINED',
      playerId,
      amount: -coinsCost,
      seq: nextSeq(),
    });
  }

  const drawnCard = supportDeck[0];
  const remainingDeck = supportDeck.slice(1);

  events.push({
    type: 'CARDS_DRAWN',
    playerId,
    count: 1,
    cardInstanceIds: [drawnCard.instanceId],
    seq: nextSeq(),
  });

  // D350: No pre-descontar glory/coins aqu├¡; los eventos GLORY_GAINED/COINS_GAINED
  // negativos ya aplican el descuento via applyEvent.
  return {
    state: {
      ...state,
      players: {
        ...state.players,
        [playerId]: {
          ...player,
          hand: [...player.hand, { ...drawnCard, zone: 'HAND' as Zone }],
          supportDecks: player.supportDecks.map((d, i) => i === supportDeckIndex ? remainingDeck : d),
          supportCardsDrawnThisTurn: cardsDrawnThisTurn + 1,
          supportDeckIndexUsedThisTurn: supportDeckIndex,
          // D349: Marcar la carta como prestada para devolverla al mazo al final del turno
          borrowedSupportCardIds: [...(player.borrowedSupportCardIds ?? []), drawnCard.instanceId],
        },
      },
    },
    events,
  };
}

/**
 * Calcular puntuacion final en modo solitario (especificacion ┬º4.3).
 *
 * Puntuacion:
 * - +1 por carta sobrante (mano + mazo)
 * - +1 por cada 2 Gloria (fichas)
 * - +1 por cada 5 monedas
 * - Por cada herida no recibida, tantos puntos como cartas tenga el mazo
 */
export function calculateSoloScore(state: GameState, playerId: string): {
  glory: number;
  bonus: number;
  total: number;
  breakdown: { label: string; value: number }[];
} {
  const player = state.players[playerId];
  if (!player) return { glory: 0, bonus: 0, total: 0, breakdown: [] };

  const breakdown: { label: string; value: number }[] = [];
  let bonus = 0;

  // +1 por carta sobrante (mano + mazo)
  const remainingCards = player.hand.length + player.abilityDeck.length;
  breakdown.push({ label: 'Cartas sobrantes', value: remainingCards });
  bonus += remainingCards;

  // +1 por cada 2 Gloria (fichas)
  const gloryBonus = Math.floor(player.glory / 2);
  breakdown.push({ label: 'Gloria (1pt/2)', value: gloryBonus });
  bonus += gloryBonus;

  // +1 por cada 5 monedas
  const coinsBonus = Math.floor(player.coins / 5);
  breakdown.push({ label: 'Monedas (1pt/5)', value: coinsBonus });
  bonus += coinsBonus;

  // Por cada herida no recibida, tantos puntos como cartas tenga el mazo
  const woundsNotReceived = (player.maxWounds ?? 3) - player.wounds;
  if (woundsNotReceived > 0) {
    const woundBonus = woundsNotReceived * player.abilityDeck.length;
    breakdown.push({ label: 'Heridas no recibidas', value: woundBonus });
    bonus += woundBonus;
  }

  return {
    glory: player.glory,
    bonus,
    // Especificacion ┬º4.3: el total es solo la suma de los 4 conceptos
    // (las fichas de Gloria ya se cuentan como +1 por cada 2)
    total: bonus,
    breakdown,
  };
}

/**
 * Obtener el titulo de solitario segun la puntuacion (especificacion ┬º4.4).
 *
 * - Cazador audaz: 1-10 puntos
 * - Guardi├ín de los justos: 11-20 puntos
 * - Terror de la Horda: 21-40 puntos
 * - Caudillo de Isilendor: 41+ puntos
 */
export function getSoloTitle(score: number): string {
  if (score >= 41) return 'Caudillo de Isilendor';
  if (score >= 21) return 'Terror de la Horda';
  if (score >= 11) return 'Guardi├ín de los justos';
  if (score >= 1) return 'Cazador audaz';
  return 'Derrotado';
}

/**
 * Cambiar hasta 2 cartas iniciales en modo solitario (especificacion ┬º4.1).
 * Las cartas cambiadas van al fondo del mazo y se roban nuevas.
 */
export function swapStartingCards(
  state: GameState,
  playerId: string,
  cardInstanceIds: string[],
  _rng: DeterministicRng,
): { state: GameState; events: GameEvent[]; error?: string } {
  const events: GameEvent[] = [];
  const player = state.players[playerId];
  if (!player) return { state, events, error: 'Player not found' };
  if (cardInstanceIds.length > 2) {
    return { state, events, error: 'Can only swap up to 2 cards' };
  }

  let newHand = [...player.hand];
  let newDeck = [...player.abilityDeck];

  for (const cardId of cardInstanceIds) {
    const cardIdx = newHand.findIndex(c => c.instanceId === cardId);
    if (cardIdx === -1) continue;
    // Mover carta al fondo del mazo
    const card = newHand[cardIdx];
    newHand.splice(cardIdx, 1);
    newDeck.push({ ...card, zone: 'ABILITY_DECK' as Zone });
    // Robar nueva carta del top del mazo
    if (newDeck.length > 0) {
      const newCard = newDeck[0];
      newDeck = newDeck.slice(1);
      newHand.push({ ...newCard, zone: 'HAND' as Zone });
      events.push({
        type: 'CARDS_DRAWN',
        playerId,
        count: 1,
        cardInstanceIds: [newCard.instanceId],
        seq: nextSeq(),
      });
    }
  }

  return {
    state: {
      ...state,
      players: {
        ...state.players,
        [playerId]: { ...player, hand: newHand, abilityDeck: newDeck },
      },
    },
    events,
  };
}

