}

/**
 * modifiers ÔÇö pila de modificadores continuos con capas.
 *
 * Implementaci├│n del sistema de capas de modificadores (secci├│n 51.10).
 *
 * Orden de aplicaci├│n:
 * 1. BASE_CHARACTERISTICS ÔÇö Valores impresos
 * 2. FORTITUDE_MODIFIERS ÔÇö Roghkiller (+1 orcos), Ruinas de Brunmar (-1 todos)
 * 3. DAMAGE_BONUS ÔÇö Piedra de Amolar (+1 este turno), Flecha Corrosiva (+1 vs enemigo)
 * 4. PREVENTION ÔÇö Escudo, Compa├▒ero Lobo, Carga con Escudo
 * 5. CANCELLATION ÔÇö Aura Protectora (cancela todo)
 */

import type {
  GameState,
  PlayerState,
  EnemyState,
} from '@nt4h/schema';

export const MODIFIER_LAYERS = [
  'BASE_CHARACTERISTICS',
  'FORTITUDE_MODIFIERS',
  'DAMAGE_BONUS',
  'ENEMY_OUTGOING_DAMAGE',
  'PREVENTION',
  'CANCELLATION',
  'MARKET_COST',
] as const;

export type ModifierLayer = typeof MODIFIER_LAYERS[number];

/**
 * Aplicar todas las capas de modificadores al estado.
 * Devuelve un nuevo estado con los valores efectivos calculados.
 */
export function applyModifiers(state: GameState): GameState {
  let newState = state;
  for (const layer of MODIFIER_LAYERS) {
    newState = applyLayer(newState, layer);
  }
  return newState;
}

/**
 * Obtener la fortaleza efectiva de un enemigo (base + modificadores).
 */
export function getEffectiveFortitude(enemy: EnemyState, state: GameState): number {
  if (enemy.effectiveFortitude !== undefined) return enemy.effectiveFortitude;
  let fortitude = enemy.baseFortitude;
  for (const mod of enemy.modifiers) {
    if (mod.layer !== 'FORTITUDE_MODIFIERS') continue;
    fortitude += mod.amount;
  }
  if (enemy.isOrc && state.orcFortitudeBonus > 0) {
    fortitude += state.orcFortitudeBonus;
  }
  // D373: Permitir fortaleza 0 (Ruinas de Brunmar puede reducir a 0)
  return Math.max(0, fortitude);
}

/**
 * Obtener el bonus de dano de un enemigo (Flecha Corrosiva, etc.).
 * Suma todos los modificadores DAMAGE_BONUS del enemigo.
 */
export function getEnemyDamageBonus(enemy: EnemyState): number {
  let bonus = 0;
  for (const mod of enemy.modifiers) {
    if (mod.layer === 'DAMAGE_BONUS') bonus += mod.amount;
  }
  return bonus;
}

/**
 * Obtener el bonus de dano saliente de un enemigo (Puerto de Eque, etc.).
 * Suma todos los modificadores ENEMY_OUTGOING_DAMAGE del enemigo.
 */
export function getEnemyOutgoingDamageBonus(enemy: EnemyState): number {
  let bonus = 0;
  for (const mod of enemy.modifiers) {
    if (mod.layer === 'ENEMY_OUTGOING_DAMAGE') bonus += mod.amount;
  }
  return bonus;
}

/**
 * Aplicar una capa espec├¡fica de modificadores.
 */
function applyLayer(state: GameState, layer: ModifierLayer): GameState {
  switch (layer) {
    case 'BASE_CHARACTERISTICS':
      // Los valores base ya est├ín en el estado, no hay que hacer nada
      return state;

    case 'FORTITUDE_MODIFIERS':
      return applyFortitudeModifiers(state);

    case 'DAMAGE_BONUS':
      // Los modificadores de da├▒o se aplican durante la resoluci├│n de cartas
      // No modifican el estado global, sino que se consultan en applyDamageModifiers
      return state;

    case 'ENEMY_OUTGOING_DAMAGE':
      // El da├▒o saliente del enemigo se consulta via getEnemyOutgoingDamageBonus
      // durante el ataque de la Horda. No modifica el estado global aqu├¡.
      return state;

    case 'PREVENTION':
      // La prevenci├│n se aplica durante el ataque de la Horda
      // No modifica el estado global aqu├¡
      return state;

    case 'CANCELLATION':
      // La cancelaci├│n se aplica durante el ataque de la Horda
      // No modifica el estado global aqu├¡
      return state;

    case 'MARKET_COST':
      // Los modificadores de coste de mercado se aplican via state.marketCostModifier
      // que ya se actualiza en applyEvent al recibir MODIFIER_ADDED con layer=MARKET_COST
      return state;

    default:
      return state;
  }
}

/**
 * Aplicar modificadores de fortaleza a todos los enemigos.
 */
function applyFortitudeModifiers(state: GameState): GameState {
  const battlefield = state.battlefield.map((enemy: EnemyState) => {
    let fortitude = enemy.baseFortitude;
    for (const mod of enemy.modifiers) {
      if (mod.layer !== 'FORTITUDE_MODIFIERS') continue;
      fortitude += mod.amount;
    }
    // Roghkiller: +1 a orcos si est├í activo
    if (enemy.isOrc && state.orcFortitudeBonus > 0) {
      fortitude += state.orcFortitudeBonus;
    }
    return {
      ...enemy,
      // Almacenar el valor efectivo en effectiveFortitude
      effectiveFortitude: Math.max(0, fortitude),
    };
  });

  return {
    ...state,
    battlefield,
  };
}

/**
 * Calcular la fortaleza efectiva de un enemigo (base + modificadores).
 */
export function effectiveFortitude(enemy: EnemyState, state: GameState): number {
  let fortitude = enemy.baseFortitude;
  for (const mod of enemy.modifiers) {
    if (mod.layer === 'FORTITUDE_MODIFIERS') {
      fortitude += mod.amount;
    }
  }
  if (enemy.isOrc && state.orcFortitudeBonus > 0) {
    fortitude += state.orcFortitudeBonus;
  }
  // D373: Permitir fortaleza 0 (Ruinas de Brunmar puede reducir a 0)
  return Math.max(0, fortitude);
}

/**
 * Calcular el da├▒o efectivo de una carta (base + modificadores de DAMAGE_BONUS).
 */
export function effectiveDamage(
  baseDamage: number,
  cardName: string,
  player: PlayerState,
  _targetEnemyId?: string,
): number {
  let damage = baseDamage;
  for (const mod of player.modifiers) {
    if (mod.layer !== 'DAMAGE_BONUS') continue;
    // Filtrar por nombre de carta si el modificador lo especifica
    if (mod.filter?.name && mod.filter.name !== cardName) continue;
    damage += mod.amount;
  }
  return Math.max(0, damage);
}

/**
 * Calcular el da├▒o efectivo del ataque de la Horda despu├®s de prevenci├│n.
 */
export function effectiveHordeDamage(
  baseDamage: number,
  player: PlayerState,
): number {
  // Capa CANCELLATION: si hay cancelaci├│n activa, el da├▒o es 0
  if (player.damageCancellation) {
    return 0;
  }

  // Capa PREVENTION: restar la prevenci├│n
  let damage = baseDamage - player.prevention;
  if (player.shields > 0) {
    damage -= player.shields;
  }

  return Math.max(0, damage);
}

/**
 * Calcular el da├▒o de un enemigo espec├¡fico despu├®s de prevenci├│n.
 */
export function effectiveEnemyDamage(
  enemy: EnemyState,
  baseDamage: number,
  player: PlayerState,
): number {
  // Si el enemigo tiene el da├▒o deshabilitado, no causa da├▒o
  if (enemy.damageDisabled) {
    return 0;
  }

  // Capa PREVENTION: si hay escudos, restar
  let damage = baseDamage;
  if (player.shields > 0) {
    const absorbed = Math.min(player.shields, damage);
    damage -= absorbed;
  }

  return Math.max(0, damage);
}

/**
 * Expirar modificadores que han terminado su duraci├│n.
 * Se llama al final del turno o despu├®s del ataque de la Horda.
 */
export function expireModifiers(
  state: GameState,
  trigger: 'END_OF_TURN' | 'HORDE_ATTACK_END',
): GameState {
  const players: Record<string, PlayerState> = {};
  for (const [id, player] of Object.entries(state.players)) {
    const p = player as PlayerState;
    const remainingModifiers = p.modifiers.filter(mod => {
      if (mod.duration === 'UNTIL_END_OF_TURN' && trigger === 'END_OF_TURN') {
        return false;
      }
      if (mod.duration === 'HORDE_ATTACK' && trigger === 'HORDE_ATTACK_END') {
        return false;
      }
      if (mod.duration === 'NEXT_HORDE_ATTACK' && trigger === 'HORDE_ATTACK_END') {
        return false;
      }
      return true;
    });

    // Reset prevenci├│n y escudos si termina el ataque de la Horda
    const newPlayer: PlayerState = {
      ...p,
      modifiers: remainingModifiers,
    };
    if (trigger === 'HORDE_ATTACK_END') {
      newPlayer.prevention = 0;
      newPlayer.shields = 0;
      newPlayer.damageCancellation = false;
    }

    players[id] = newPlayer;
  }

  // Expirar modificadores de enemigos
  const battlefield = state.battlefield.map((enemy: EnemyState) => {
    const remainingModifiers = enemy.modifiers.filter(mod => {
      if (mod.duration === 'HORDE_ATTACK' && trigger === 'HORDE_ATTACK_END') {
        return false;
      }
      if (mod.duration === 'NEXT_HORDE_ATTACK' && trigger === 'HORDE_ATTACK_END') {
        return false;
      }
      // UNTIL_END_OF_TURN en enemigos (ej. Puerto de Eque) expira al final del turno
      if (mod.duration === 'UNTIL_END_OF_TURN' && trigger === 'END_OF_TURN') {
        return false;
      }
      // WHILE_SOURCE_ACTIVE: la limpieza se maneja manualmente cuando la fuente
      // es derrotada/descartada (resolver.ts, scenarios/index.ts, applyEvent.ts).
      // No eliminar autom├íticamente aqu├¡ porque sourceId puede ser un escenario,
      // un warlord, o un string fijo como 'roghkiller'.
      return true;
    });

    const newEnemy: EnemyState = {
      ...enemy,
      modifiers: remainingModifiers,
    };
    if (trigger === 'HORDE_ATTACK_END') {
      newEnemy.damageDisabled = false;
    }
    return newEnemy;
  });

  return {
    ...state,
    players,
    battlefield,
  };
}

/**
 * PhaseEngine ÔÇö motor de fases que procesa transiciones automaticas.
 *
 * Algunas fases requieren accion del jugador (PLAYER_ATTACK, MARKET, ATTACK_CHOICE).
 * Otras son automaticas (HORDE_ATTACK, RESTORATION, BATTLEFIELD_REPLENISHMENT,
 * SCENARIO_TRANSITION, TURN_END, GAME_END_CHECK).
 *
 * Este modulo ejecuta las fases automaticas y devuelve los eventos generados.
 */

import type {
  GameState,
  GameEvent,
  EnemyState,
  Zone,
  PendingChoice,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import { feldonDamageReduction } from '../heroes/abilities.js';
import { applyEvent, mapPlayerState } from '../events/applyEvent.js';
import { getEffectiveFortitude, getEnemyOutgoingDamageBonus, expireModifiers } from '../modifiers/index.js';
import { applyScenarioEffects, clearScenarioEffects, onTurnStart } from '../scenarios/index.js';
import { EffectRegistry, registerCoreEffects } from '../effects/registry.js';
import { processHordeAttackTriggers } from '../effects/resolver.js';
import { calculateSoloScore } from '../modes/solo.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

let phaseSeq = 0;
function nextSeq(): number {
  return ++phaseSeq;
}

export function resetPhaseSeq(): void {
  phaseSeq = 0;
}

export interface PhaseResult {
  state: GameState;
  events: GameEvent[];
  rng: DeterministicRng;
  /** Si la fase requiere accion del jugador, indica cual */
  pendingPhase: 'PLAYER_ATTACK' | 'MARKET' | 'ATTACK_CHOICE' | 'FINISHED' | null;
}

/**
 * Procesar la fase actual del estado y avanzar automaticamente
 * hasta llegar a una fase que requiera accion del jugador.
 */
export function processPhases(
  state: GameState,
  rng: DeterministicRng,
  catalog: CatalogLoadResult,
): PhaseResult {
  let current = state;
  const allEvents: GameEvent[] = [];
  let pending: PhaseResult['pendingPhase'] = null;

  // Maximo 20 iteraciones para evitar bucles infinitos
  for (let i = 0; i < 20; i++) {
    switch (current.phase) {
      case 'HORDE_ATTACK': {
        // D371: Ventana de reacci├│n ÔÇö antes del ataque, otros h├®roes pueden
        // usar pericias reactivas (Val├¿rys, Lisavette) o pasar
        const hasReactionChoice = current.pendingChoices.some(
          c => c.type === 'REACTION_WINDOW'
        );
        if (!hasReactionChoice) {
          const reactionChoices = buildReactionWindow(current);
          if (reactionChoices.length > 0) {
            current = {
              ...current,
              pendingChoices: [...current.pendingChoices, ...reactionChoices],
            };
            allEvents.push({
              type: 'PHASE_CHANGED',
              phase: 'HORDE_ATTACK',
              seq: nextSeq(),
            });
            // Detener: esperar a que los jugadores reaccionen
            return { events: allEvents, state: current, rng, pendingPhase: null };
          }
        }
        // Si todav├¡a hay elecciones de reacci├│n pendientes, esperar
        const pendingReactions = current.pendingChoices.filter(
          c => c.type === 'REACTION_WINDOW'
        );
        if (pendingReactions.length > 0) {
          return { events: allEvents, state: current, rng, pendingPhase: null };
        }

        // Primero procesar disparadores reactivos (Trampa) antes del ataque
        const reg = new EffectRegistry();
        registerCoreEffects(reg);
        const triggerResult = processHordeAttackTriggers(current, rng, reg, catalog);
        // Si hay eleccion pendiente (empate de Trampa), detener y esperar al jugador
        if (triggerResult.pendingChoice) {
          current = {
            ...triggerResult.state,
            pendingChoices: [...triggerResult.state.pendingChoices, triggerResult.pendingChoice],
          };
          allEvents.push(...triggerResult.events);
          // Detener el procesamiento de fases: el jugador debe resolver la eleccion
          return { events: allEvents, state: current, rng, pendingPhase: null };
        }
        current = triggerResult.events.reduce((s, e) => applyEvent(s, e), triggerResult.state);
        allEvents.push(...triggerResult.events);
        // Luego procesar el ataque de la Horda
        const result = processHordeAttack(current, rng, catalog);
        // Aplicar eventos al estado para sincronizar
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        break;
      }

      case 'RESTORATION': {
        const result = processRestoration(current, rng, catalog);
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        break;
      }

      case 'BATTLEFIELD_REPLENISHMENT': {
        const result = processBattlefieldReplenishment(current, rng, catalog);
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        break;
      }

      case 'SCENARIO_TRANSITION': {
        const result = processScenarioTransition(current, rng, catalog);
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        break;
      }

      case 'TURN_END': {
        const result = processTurnEnd(current, rng);
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        break;
      }

      case 'GAME_END_CHECK': {
        const result = processGameEndCheck(current, rng, catalog);
        current = result.events.reduce((s, e) => applyEvent(s, e), result.state);
        allEvents.push(...result.events);
        if (current.phase === 'FINISHED') {
          pending = 'FINISHED';
        }
        break;
      }

      case 'PLAYER_ATTACK':
      case 'ATTACK_CHOICE':
      case 'MARKET':
        pending = current.phase;
        break;

      case 'FINISHED':
        pending = 'FINISHED';
        break;

      default:
        // Fases que requieren accion o no se procesan aqui
        pending = null;
        break;
    }

    if (pending !== null) break;
  }

  return { state: current, events: allEvents, rng, pendingPhase: pending };
}

// ============================================================================
// D371: Ventana de reacci├│n ÔÇö construir elecciones para h├®roes reactivos
// ============================================================================

function buildReactionWindow(state: GameState): PendingChoice[] {
  const choices: PendingChoice[] = [];
  const activePlayerId = state.activePlayerId;

  for (const playerId of state.playerOrder) {
    if (playerId === activePlayerId) continue;
    const player = state.players[playerId];
    if (!player || player.heroUsesRemaining <= 0) continue;

    const heroDef = state.players[playerId]?.heroId;
    // Verificar si el h├®roe tiene una pericia reactiva (Val├¿rys o Lisavette)
    // En una implementaci├│n completa, esto vendr├¡a del cat├ílogo
    const reactiveHeroes = ['hero.valerys', 'hero.valerys-female', 'hero.valerys-male',
                            'hero.lisavette', 'hero.lisavette-female', 'hero.lisavette-male'];
    if (!reactiveHeroes.includes(heroDef ?? '')) continue;

    // Lisavette: solo ofrecer reacci├│n si tiene carta "Escudo" (warrior.shield) en mano
    const isLisavette = heroDef?.includes('lisavette') ?? false;
    if (isLisavette && !player.hand.some(c => c.definitionId === 'warrior.shield')) continue;

    // Verificar que el jugador no tenga ya una elecci├│n pendiente
    const hasExisting = state.pendingChoices.some(
      c => c.playerId === playerId && c.type === 'REACTION_WINDOW'
    );
    if (hasExisting) continue;

    choices.push({
      choiceId: `reaction-${playerId}-${nextSeq()}`,
      playerId,
      type: 'REACTION_WINDOW',
      prompt: `Reacci├│n: ┬┐Usar pericia de h├®roe o pasar?`,
      options: ['USE_ABILITY', 'PASS'],
      minSelections: 1,
      maxSelections: 1,
    });
  }

  return choices;
}

// ============================================================================
// HORDE_ATTACK ÔÇö la Horda ataca al jugador activo
// ============================================================================

function processHordeAttack(
  state: GameState,
  rng: DeterministicRng,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  const player = state.players[state.activePlayerId];

  // Calcular dano total de la Horda
  // Especificacion 3.4: Dano = Suma(Fortaleza - Heridas) de cada enemigo vivo
  // Especificacion 3.6: Anti-Magia: enemigos con este icono hacen menos dano
  // a heroes con capacidad MAGIC (restar valor indicado de la Fortaleza)
  const heroHasMagic = player.capabilities.includes('MAGIC');
  let totalDamage = 0;
  for (const enemy of state.battlefield) {
    if (enemy.damageDisabled) continue;
    // El dano de cada enemigo = Fortaleza efectiva - Heridas (minimo 0)
    let enemyDamage = Math.max(0, getEffectiveFortitude(enemy, state) - enemy.wounds);
    // Anti-Magia: si el heroe tiene Magia y el enemigo tiene ANTI_MAGIC,
    // restar el valor indicado (por defecto 1) de la Fortaleza al calcular dano
    if (heroHasMagic && enemy.specialIcons?.includes('ANTI_MAGIC')) {
      const enemyDef = catalog.byId.get(enemy.definitionId);
      const antiMagicValue = enemyDef?.antiMagicValue ?? 1;
      enemyDamage = Math.max(0, enemyDamage - antiMagicValue);
    }
    // Puerto de Eque: +1 dano del enemigo (modificador ENEMY_OUTGOING_DAMAGE en enemigo)
    enemyDamage += getEnemyOutgoingDamageBonus(enemy);
    totalDamage += enemyDamage;
  }

  // Aplicar prevencion y escudos
  let effectiveDamage = totalDamage;
  // Valerys: si el dano fue interceptado, skip defensas del objetivo original
  const interceptorId = player.interceptedBy;
  if (!interceptorId) {
    if (player.prevention > 0) {
      effectiveDamage = Math.max(0, effectiveDamage - player.prevention);
    }
    // Escudos: absorben da├▒o de la Horda
    if (player.shields > 0) {
      effectiveDamage = Math.max(0, effectiveDamage - player.shields);
    }
    if (player.damageCancellation) {
      effectiveDamage = 0;
    }

    // Feldon: pierde mitad de cartas (usar funcion exportada de heroes)
    const damageBeforeFeldon = effectiveDamage;
    effectiveDamage = feldonDamageReduction(state, player.playerId, effectiveDamage);
    // Consumir un uso de Pericia de Feldon si se activo la reduccion
    if (effectiveDamage < damageBeforeFeldon) {
      events.push({
        type: 'HERO_ABILITY_USED',
        playerId: player.playerId,
        usesRemaining: Math.max(0, (player.heroUsesRemaining ?? 0) - 1),
        seq: nextSeq(),
      });
    }
  }

  events.push({
    type: 'HORDE_ATTACKED',
    playerId: state.activePlayerId,
    totalDamage: effectiveDamage,
    seq: nextSeq(),
  });

  // Valerys: si el dano fue interceptado, redirigir al interceptor
  if (interceptorId && effectiveDamage > 0) {
    const interceptor = state.players[interceptorId];
    if (interceptor) {
      // Limpiar la intercepcion del objetivo (el evento DAMAGE_INTERCEPTED ya se emitio en valerysAbility)
      state = mapPlayerState(state, state.activePlayerId, p => ({
        ...p,
        interceptedBy: null,
      }));
      // D372: Recalcular dano de la Horda usando las capacidades del interceptor
      // (Anti-Magia depende del heroe que recibe el dano, no del objetivo original)
      const interceptorHasMagic = interceptor.capabilities.includes('MAGIC');
      let interceptorTotalDamage = 0;
      for (const enemy of state.battlefield) {
        if (enemy.damageDisabled) continue;
        let enemyDamage = Math.max(0, getEffectiveFortitude(enemy, state) - enemy.wounds);
        if (interceptorHasMagic && enemy.specialIcons?.includes('ANTI_MAGIC')) {
          const enemyDef = catalog.byId.get(enemy.definitionId);
          const antiMagicValue = enemyDef?.antiMagicValue ?? 1;
          enemyDamage = Math.max(0, enemyDamage - antiMagicValue);
        }
        enemyDamage += getEnemyOutgoingDamageBonus(enemy);
        interceptorTotalDamage += enemyDamage;
      }
      // Aplicar dano al interceptor con reciclaje + herida si el mazo se agota
      // Recalcular defensas del interceptor (prevention, shields, damageCancellation)
      let interceptorDamage = interceptorTotalDamage;
      if (interceptor.damageCancellation) {
        interceptorDamage = 0;
      } else {
        interceptorDamage = Math.max(0, interceptorDamage - interceptor.prevention);
        interceptorDamage = Math.max(0, interceptorDamage - interceptor.shields);
        // D373: Feldon como interceptor tambien aplica su reduccion de mitad de cartas
        const beforeFeldon = interceptorDamage;
        interceptorDamage = feldonDamageReduction(state, interceptorId, interceptorDamage);
        if (interceptorDamage < beforeFeldon) {
          events.push({
            type: 'HERO_ABILITY_USED',
            playerId: interceptorId,
            usesRemaining: (interceptor.heroUsesRemaining ?? 0) - 1,
            seq: nextSeq(),
          });
        }
      }
      if (interceptorDamage === 0) {
        // El interceptor bloquea todo el dano; pasar a Mercado
        state = expireModifiers(state, 'HORDE_ATTACK_END');
        events.push({
          type: 'PHASE_CHANGED',
          phase: 'MARKET',
          seq: nextSeq(),
        });
        return { state, events };
      }
      let remainingDamage = interceptorDamage;
      let currentDeck = [...interceptor.abilityDeck];
      let currentWear = [...interceptor.wearPile];
      let wounds = interceptor.wounds;
      const allLost: string[] = [];
      let pendingLost: string[] = [];

      while (remainingDamage > 0) {
        if (currentDeck.length === 0) {
          if (pendingLost.length > 0) {
            allLost.push(...pendingLost);
            events.push({
              type: 'CARDS_LOST',
              playerId: interceptorId,
              count: pendingLost.length,
              cardInstanceIds: pendingLost,
              seq: nextSeq(),
            });
            pendingLost = [];
          }
          // D351: Si no hay Desgaste que reciclar, el da├▒o restante se ignora (sin herida)
          if (currentWear.length === 0) break;
          wounds++;
          events.push({
            type: 'HERO_WOUNDED',
            playerId: interceptorId,
            woundCount: wounds,
            seq: nextSeq(),
          });
          currentDeck = rng.shuffle([...currentWear]);
          currentWear = [];
          events.push({
            type: 'DECK_RESHUFFLED',
            playerId: interceptorId,
            newDeckSize: currentDeck.length,
            newOrder: currentDeck.map(c => c.instanceId),
            seq: nextSeq(),
          });
        }
        const lost = currentDeck.slice(0, remainingDamage).map(c => c.instanceId);
        pendingLost.push(...lost);
        const lostCards = currentDeck.slice(0, remainingDamage);
        currentWear = [...currentWear, ...lostCards.map(c => ({ ...c, zone: 'WEAR_PILE' as Zone }))];
        currentDeck = currentDeck.slice(lost.length);
        remainingDamage -= lost.length;
      }
      if (pendingLost.length > 0) {
        allLost.push(...pendingLost);
        events.push({
          type: 'CARDS_LOST',
          playerId: interceptorId,
          count: pendingLost.length,
          cardInstanceIds: pendingLost,
          seq: nextSeq(),
        });
      }
      // No pre-aplicar el estado del interceptor: los eventos (CARDS_LOST, HERO_WOUNDED,
      // DECK_RESHUFFLED) se aplicar├ín posteriormente via applyEvent en processPhases.
      // El objetivo no sufre perdida de cartas, pero hay que pasar a Mercado
      state = expireModifiers(state, 'HORDE_ATTACK_END');
      events.push({
        type: 'PHASE_CHANGED',
        phase: 'MARKET',
        seq: nextSeq(),
      });
      return { state, events };
    }
  }

  // El dano se convierte en perdida de cartas del mazo
  // Si el mazo se agota, el heroe sufre una herida, recicla Desgaste y sigue
  if (effectiveDamage > 0) {
    let remainingDamage = effectiveDamage;
    let currentDeck = [...player.abilityDeck];
    let currentWear = [...player.wearPile];
    let wounds = player.wounds;
    const allLost: string[] = [];
    let pendingLost: string[] = []; // Cartas perdidas sin emitir a├║n

    while (remainingDamage > 0) {
      if (currentDeck.length === 0) {
        // Emitir CARDS_LOST pendientes antes del reciclaje (mover a wearPile del estado)
        if (pendingLost.length > 0) {
          events.push({
            type: 'CARDS_LOST',
            playerId: state.activePlayerId,
            count: pendingLost.length,
            cardInstanceIds: pendingLost,
            seq: nextSeq(),
          });
          allLost.push(...pendingLost);
          pendingLost = [];
        }
        // D351: Si no hay Desgaste que reciclar, el da├▒o restante se ignora (sin herida)
        if (currentWear.length === 0) {
          break;
        }
        // Mazo agotado: herida + reciclar Desgaste
        wounds++;
        events.push({
          type: 'HERO_WOUNDED',
          playerId: state.activePlayerId,
          woundCount: wounds,
          seq: nextSeq(),
        });
        // Reciclar Desgaste como nuevo mazo (barajado)
        currentDeck = rng.shuffle([...currentWear]);
        currentWear = [];
        events.push({
          type: 'DECK_RESHUFFLED',
          playerId: state.activePlayerId,
          newDeckSize: currentDeck.length,
          newOrder: currentDeck.map(c => c.instanceId),
          seq: nextSeq(),
        });
      }
      const lost = currentDeck.slice(0, remainingDamage).map(c => c.instanceId);
      pendingLost.push(...lost);
      // Las cartas perdidas van a Desgaste (actualizar currentWear para reciclajes futuros)
      const lostCards = currentDeck.slice(0, remainingDamage);
      currentWear = [...currentWear, ...lostCards.map(c => ({ ...c, zone: 'WEAR_PILE' as Zone }))];
      currentDeck = currentDeck.slice(lost.length);
      remainingDamage -= lost.length;
    }

    // Emitir CARDS_LOST pendientes finales
    if (pendingLost.length > 0) {
      allLost.push(...pendingLost);
      events.push({
        type: 'CARDS_LOST',
        playerId: state.activePlayerId,
        count: pendingLost.length,
        cardInstanceIds: pendingLost,
        seq: nextSeq(),
      });
    }

    if (allLost.length > 0) {
      // Ya se emitieron los CARDS_LOST arriba; no duplicar
    }
  }

  // Expirar modificadores de HORDE_ATTACK y resetear defensa tras el ataque
  state = expireModifiers(state, 'HORDE_ATTACK_END');

  // Pasar a Mercado
  events.push({
    type: 'PHASE_CHANGED',
    phase: 'MARKET',
    seq: nextSeq(),
  });

  return {
    state: { ...state, phase: 'MARKET' },
    events,
  };
}

// ============================================================================
// RESTORATION ÔÇö ajustar mano y limpiar modificadores de turno
// ============================================================================

function processRestoration(
  state: GameState,
  rng: DeterministicRng,
  _catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  const player = state.players[state.activePlayerId];

  // Guardar valores iniciales para el estado retornado
  // (los eventos transformaran estos valores al estado final)
  const initialHand = [...player.hand];
  const initialDeck = [...player.abilityDeck];
  const initialWearPile = [...player.wearPile];

  // Ajustar mano a 4 cartas (especificacion 3.6.1)
  // Si tiene menos de 4, robar hasta 4
  // Si tiene mas de 4, descartar las extras
  let newHand = [...player.hand];
  let newDeck = [...player.abilityDeck];
  let newWearPile = [...player.wearPile];

  // Descartar extras a Desgaste
  while (newHand.length > 4) {
    const card = newHand.pop()!;
    newWearPile.push({ ...card, zone: 'WEAR_PILE' as Zone });
    events.push({
      type: 'CARD_MOVED',
      cardInstanceId: card.instanceId,
      from: 'HAND' as Zone,
      to: 'WEAR_PILE' as Zone,
      seq: nextSeq(),
    });
  }

  while (newHand.length < 4 && newDeck.length > 0) {
    const card = newDeck[0];
    newDeck = newDeck.slice(1);
    newHand.push({ ...card, zone: 'HAND' as Zone });
    events.push({
      type: 'CARDS_DRAWN',
      playerId: state.activePlayerId,
      count: 1,
      cardInstanceIds: [card.instanceId],
      seq: nextSeq(),
    });
  }

  // Si el mazo se agota al robar, reciclar desgaste barajando y herir
  if (newHand.length < 4 && newDeck.length === 0 && newWearPile.length > 0) {
    events.push({
      type: 'HERO_WOUNDED',
      playerId: state.activePlayerId,
      woundCount: player.wounds + 1,
      seq: nextSeq(),
    });
    // Barajar el desgaste antes de reciclar (especificacion: mazo como vida)
    const shuffledWear = rng.shuffle(newWearPile);
    const newOrder = shuffledWear.map(c => c.instanceId);
    events.push({
      type: 'DECK_RESHUFFLED',
      playerId: state.activePlayerId,
      newDeckSize: shuffledWear.length,
      newOrder,
      seq: nextSeq(),
    });
    newDeck = shuffledWear.map(c => ({ ...c, zone: 'ABILITY_DECK' as Zone }));
    newWearPile = [];
    while (newHand.length < 4 && newDeck.length > 0) {
      const card = newDeck[0];
      newDeck = newDeck.slice(1);
      newHand.push({ ...card, zone: 'HAND' as Zone });
      events.push({
        type: 'CARDS_DRAWN',
        playerId: state.activePlayerId,
        count: 1,
        cardInstanceIds: [card.instanceId],
        seq: nextSeq(),
      });
    }
  }

  // Limpiar modificadores de fin de turno
  // Nota: hand/abilityDeck/wearPile se retornan con valores iniciales
  // para que applyEvent(CARDS_MOVED/CARDS_DRAWN/DECK_RESHUFFLED) los transforme correctamente
  const newPlayers = {
    ...state.players,
    [state.activePlayerId]: {
      ...player,
      hand: initialHand,
      abilityDeck: initialDeck,
      wearPile: initialWearPile,
      prevention: 0,
      damageCancellation: false,
      interceptedBy: null,
      shields: 0,
    },
  };

  // Limpiar damageDisabled de enemigos y heridas temporales
  // Especificacion 3.6: las Heridas de enemigos con icono TEMPORARY_WOUNDS
  // se descartan al final del Restablecimiento
  const newBattlefield = state.battlefield.map(e => ({
    ...e,
    damageDisabled: false,
    // Resetear heridas si el enemigo tiene icono de heridas temporales
    wounds: e.specialIcons?.includes('TEMPORARY_WOUNDS') ? 0 : e.wounds,
    modifiers: e.modifiers.filter(m => m.duration !== 'UNTIL_END_OF_TURN' && m.duration !== 'HORDE_ATTACK' && m.duration !== 'NEXT_HORDE_ATTACK'),
  }));

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'BATTLEFIELD_REPLENISHMENT',
    seq: nextSeq(),
  });

  return {
    state: {
      ...state,
      players: newPlayers,
      battlefield: newBattlefield,
      phase: 'BATTLEFIELD_REPLENISHMENT',
    },
    events,
  };
}

// ============================================================================
// BATTLEFIELD_REPLENISHMENT ÔÇö reponer enemigos derrotados
// ============================================================================

function processBattlefieldReplenishment(
  state: GameState,
  _rng: DeterministicRng,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];

  // D354: Si el campo est├í vac├¡o, primero hacer transici├│n de escenario
  // (descartar el actual y revelar uno nuevo), y LUEGO reponer enemigos.
  // La spec dice: cuando el campo queda vac├¡o, se descarta el escenario actual
  // y se revela uno nuevo antes de robar nuevos enemigos.
  if (state.battlefield.length === 0 && state.scenarioDeck.length > 0 && !state.warlordRevealed) {
    // Descartar escenario actual
    if (state.scenario) {
      // Solitario: transferir scenarioCoins al jugador antes de descartar (spec ┬º4.1)
      if (state.mode === 'SOLO' && state.scenarioCoins > 0) {
        events.push({
          type: 'COINS_GAINED',
          playerId: state.activePlayerId,
          amount: state.scenarioCoins,
          seq: nextSeq(),
        });
      }
      events.push({
        type: 'SCENARIO_DISCARDED',
        scenarioInstanceId: state.scenario.instanceId,
        seq: nextSeq(),
      });
      // Limpiar efectos continuos del escenario descartado
      const clearResult = clearScenarioEffects(state, state.scenario.definitionId);
      state = clearResult.state;
      events.push(...clearResult.events);
    }

    // Revelar nuevo escenario
    const newScenario = state.scenarioDeck[0];
    events.push({
      type: 'SCENARIO_REVEALED',
      scenarioInstanceId: newScenario.instanceId,
      definitionId: newScenario.definitionId,
      seq: nextSeq(),
    });

    state = {
      ...state,
      scenario: {
        instanceId: newScenario.instanceId,
        definitionId: newScenario.definitionId,
        ownerId: newScenario.ownerId,
        zone: 'SCENARIO_ACTIVE' as const,
      } as any,
      scenarioDeck: state.scenarioDeck.slice(1),
      scenarioCoins: state.mode === 'SOLO' ? 1 : 0,
    };

    // Aplicar efectos del nuevo escenario a los enemigos actuales (campo vac├¡o = no hay)
    const scenarioResult = applyScenarioEffects(state, newScenario.definitionId, catalog);
    state = scenarioResult.state;
    events.push(...scenarioResult.events);
  }

  // Reponer enemigos segun especificacion 3.6.2:
  // 0 enemigos ÔåÆ robar 3
  // 1-2 enemigos ÔåÆ robar 1
  // 3 enemigos ÔåÆ no robar
  // El Se├▒or de la Guerra cuenta como un enemigo normal para la reposici├│n
  const currentCount = state.battlefield.length;
  let needed: number;
  if (currentCount === 0) {
    needed = 3;
  } else if (currentCount <= 2) {
    needed = 1;
  } else {
    needed = 0;
  }

  let newHordeDeck = [...state.hordeDeck];
  let newBattlefield = [...state.battlefield];

  for (let i = 0; i < needed && newHordeDeck.length > 0; i++) {
    // Robar desde la parte inferior del mazo (especificacion 3.2.5)
    const enemyCard = newHordeDeck[newHordeDeck.length - 1];
    newHordeDeck = newHordeDeck.slice(0, -1);

    const enemyDef = catalog.byId.get(enemyCard.definitionId);
    if (!enemyDef) continue;

    const enemy: EnemyState = {
      instanceId: enemyCard.instanceId,
      definitionId: enemyCard.definitionId,
      baseFortitude: enemyDef.printedFortitude ?? 1,
      wounds: 0,
      reward: enemyDef.reward ?? null,
      modifiers: [],
      isWarlord: enemyDef.type === 'WARLORD',
      isOrc: enemyDef.isOrc ?? false,
      specialIcons: enemyDef.specialIcons ?? [],
      damageDisabled: false,
    };

    // Ruinas de Brunmar: aplicar -1 fortaleza a enemigos revelados mientras el escenario est├® activo
    if (state.scenario?.definitionId === 'scenario.brunmar-ruins') {
      enemy.modifiers.push({
        id: `scenario-brunmar-${nextSeq()}`,
        sourceId: state.scenario.instanceId,
        layer: 'FORTITUDE_MODIFIERS',
        timestamp: nextSeq(),
        duration: 'WHILE_SOURCE_ACTIVE',
        amount: -1,
      });
    }

    // Roghkiller: +1 fortaleza a cada orco mientras est├® vivo en el campo
    // D374: Solo excluir al propio Roghkiller, no a todos los Warlords orcos
    // D402: Usar newBattlefield (incluye enemigos revelados en iteraciones previas del bucle)
    const roghkillerInField = newBattlefield.some(e =>
      e.isWarlord && catalog.byId.get(e.definitionId)?.name === 'Roghkiller'
    );
    const roghkillerInstanceId = newBattlefield.find(e =>
      e.isWarlord && catalog.byId.get(e.definitionId)?.name === 'Roghkiller'
    )?.instanceId;
    if (roghkillerInField && enemy.isOrc && enemy.instanceId !== roghkillerInstanceId) {
      enemy.modifiers.push({
        id: `roghkiller-${nextSeq()}`,
        sourceId: 'roghkiller',
        layer: 'FORTITUDE_MODIFIERS',
        timestamp: nextSeq(),
        duration: 'WHILE_SOURCE_ACTIVE',
        amount: 1,
      });
    }

    newBattlefield.push(enemy);

    events.push({
      type: 'ENEMY_REVEALED',
      enemyInstanceId: enemy.instanceId,
      definitionId: enemy.definitionId,
      fortitude: enemy.baseFortitude,
      seq: nextSeq(),
    });

    // Si es un Se├▒or de la Guerra, marcarlo como revelado
    if (enemy.isWarlord) {
      events.push({
        type: 'WARLORD_REVEALED',
        warlordInstanceId: enemy.instanceId,
        definitionId: enemy.definitionId,
        seq: nextSeq(),
      });
      // Especificacion 3.4: al entrar el Se├▒or de la Guerra,
      // el Escenario activo se descarta y no se reemplaza
      if (state.scenario) {
        // D357: Transferir scenarioCoins al jugador antes de descartar (spec ┬º4.2)
        if (state.mode === 'SOLO' && state.scenarioCoins > 0) {
          events.push({
            type: 'COINS_GAINED',
            playerId: state.activePlayerId,
            amount: state.scenarioCoins,
            seq: nextSeq(),
          });
        }
        events.push({
          type: 'SCENARIO_DISCARDED',
          scenarioInstanceId: state.scenario.instanceId,
          seq: nextSeq(),
        });
        // Limpiar efectos continuos del escenario descartado
        const clearResult = clearScenarioEffects(state, state.scenario.definitionId);
        state = clearResult.state;
        // Marcar escenario como descartado para que el filtro de modificadores funcione
        state = { ...state, scenario: null, scenarioCoins: 0 };
      }
      // Pericia de Roghkiller: +1 fortaleza a cada orco ya en el campo
      // D374: Solo excluir al propio Roghkiller, no a todos los Warlords orcos
      const warlordDef = catalog.byId.get(enemy.definitionId);
      if (warlordDef?.name === 'Roghkiller') {
        newBattlefield = newBattlefield.map(e => {
          if (e.isOrc && e.instanceId !== enemy.instanceId) {
            return {
              ...e,
              modifiers: [
                ...e.modifiers,
                {
                  id: `roghkiller-${nextSeq()}`,
                  sourceId: 'roghkiller',
                  layer: 'FORTITUDE_MODIFIERS',
                  timestamp: nextSeq(),
                  duration: 'WHILE_SOURCE_ACTIVE' as const,
                  amount: 1,
                },
              ],
            };
          }
          return e;
        });
      }
    }
  }

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'SCENARIO_TRANSITION',
    seq: nextSeq(),
  });

  return {
    state: {
      ...state,
      hordeDeck: newHordeDeck,
      battlefield: newBattlefield.map(e => ({
        ...e,
        // Limpiar modificadores de escenario (Brunmar) si el escenario fue descartado
        modifiers: state.scenario === null
          ? e.modifiers.filter(m => !m.id?.startsWith('scenario-'))
          : e.modifiers,
      })),
      phase: 'SCENARIO_TRANSITION',
    },
    events,
  };
}

// ============================================================================
// SCENARIO_TRANSITION ÔÇö cambiar de escenario si el campo esta vacio
// ============================================================================

function processScenarioTransition(
  state: GameState,
  _rng: DeterministicRng,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];

  // D354: Si el campo sigue vac├¡o Y el mazo de la Horda tambi├®n est├í vac├¡o,
  // la transici├│n ya se hizo en processBattlefieldReplenishment. No repetir.
  // Solo hacer transici├│n si el campo est├í vac├¡o pero el mazo NO est├í vac├¡o
  // (caso te├│rico: reposici├│n fall├│ por otra raz├│n).
  if (state.battlefield.length === 0 && state.scenarioDeck.length > 0 && state.hordeDeck.length > 0 && !state.warlordRevealed) {
    // Descartar escenario actual
    if (state.scenario) {
      // Solitario: transferir scenarioCoins al jugador antes de descartar (spec ┬º4.1)
      if (state.mode === 'SOLO' && state.scenarioCoins > 0) {
        events.push({
          type: 'COINS_GAINED',
          playerId: state.activePlayerId,
          amount: state.scenarioCoins,
          seq: nextSeq(),
        });
      }
      events.push({
        type: 'SCENARIO_DISCARDED',
        scenarioInstanceId: state.scenario.instanceId,
        seq: nextSeq(),
      });
      // Limpiar efectos continuos del escenario descartado
      const clearResult = clearScenarioEffects(state, state.scenario.definitionId);
      state = clearResult.state;
      events.push(...clearResult.events);
    }

    // Revelar nuevo escenario
    const newScenario = state.scenarioDeck[0];
    events.push({
      type: 'SCENARIO_REVEALED',
      scenarioInstanceId: newScenario.instanceId,
      definitionId: newScenario.definitionId,
      seq: nextSeq(),
    });

    state = {
      ...state,
      scenario: { ...newScenario, zone: 'SCENARIO_ACTIVE' as Zone },
      scenarioDeck: state.scenarioDeck.slice(1),
      // Solitario: colocar 1 moneda sobre el nuevo escenario (spec ┬º4.1)
      scenarioCoins: state.mode === 'SOLO' ? 1 : 0,
      phase: 'TURN_END',
    };

    // Aplicar efectos continuos del nuevo escenario
    const applyResult = applyScenarioEffects(state, newScenario.definitionId, catalog);
    state = applyResult.state;
    events.push(...applyResult.events);

    // Emitir PHASE_CHANGED a TURN_END
    events.push({
      type: 'PHASE_CHANGED',
      phase: 'TURN_END',
      seq: nextSeq(),
    });

    return { state, events };
  }

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'TURN_END',
    seq: nextSeq(),
  });

  return { state: { ...state, phase: 'TURN_END' }, events };
}

// ============================================================================
// TURN_END ÔÇö finalizar turno y pasar al siguiente jugador
// ============================================================================

function processTurnEnd(
  state: GameState,
  _rng: DeterministicRng,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];

  events.push({
    type: 'TURN_ENDED',
    playerId: state.activePlayerId,
    seq: nextSeq(),
  });

  // Limpiar modificadores del jugador con duracion UNTIL_END_OF_TURN (Piedra de Amolar)
  const player = state.players[state.activePlayerId];
  if (player) {
    const cleanedModifiers = player.modifiers.filter(m => m.duration !== 'UNTIL_END_OF_TURN');
    if (cleanedModifiers.length !== player.modifiers.length) {
      state = mapPlayerState(state, state.activePlayerId, p => ({
        ...p,
        modifiers: cleanedModifiers,
      }));
    }

    // D349/D363: Devolver cartas robadas de Apoyo seg├║n spec ┬º4.2:
    // - Carta USADA (jugada ÔåÆ est├í en Desgaste) ÔåÆ devolver al fondo de su mazo de origen
    // - Carta NO USADA (sigue en mano) ÔåÆ descartar a Desgaste
    const borrowedIds = player.borrowedSupportCardIds ?? [];
    if (borrowedIds.length > 0) {
      const usedDeckIndex = player.supportDeckIndexUsedThisTurn;
      if (usedDeckIndex !== null && usedDeckIndex !== undefined) {
        // Cartas USADAS: est├ín en la pila de Desgaste ÔåÆ volver al mazo de Apoyo
        const usedBorrowed = player.wearPile.filter(c => borrowedIds.includes(c.instanceId));
        const cleanedWearPile = player.wearPile.filter(c => !borrowedIds.includes(c.instanceId));
        // Cartas NO USADAS: siguen en la mano ÔåÆ descartar a Desgaste
        const unusedBorrowed = player.hand.filter(c => borrowedIds.includes(c.instanceId));
        const cleanedHand = player.hand.filter(c => !borrowedIds.includes(c.instanceId));
        state = mapPlayerState(state, state.activePlayerId, p => ({
          ...p,
          hand: cleanedHand,
          wearPile: [...cleanedWearPile, ...unusedBorrowed],
          supportDecks: p.supportDecks.map((d, i) =>
            i === usedDeckIndex ? [...d, ...usedBorrowed] : d
          ),
          borrowedSupportCardIds: [],
        }));
      }
    }
  }
  // Limpiar modificadores de enemigos con duracion UNTIL_END_OF_TURN (Flecha Corrosiva)
  const battlefieldChanged = state.battlefield.some(e =>
    e.modifiers.some(m => m.duration === 'UNTIL_END_OF_TURN')
  );
  if (battlefieldChanged) {
    state = {
      ...state,
      battlefield: state.battlefield.map(e => ({
        ...e,
        modifiers: e.modifiers.filter(m => m.duration !== 'UNTIL_END_OF_TURN'),
      })),
    };
  }

  // Pas al siguiente jugador (saltando jugadores eliminados)
  const currentIndex = state.playerOrder.indexOf(state.activePlayerId);
  // Filtrar jugadores no eliminados (wounds < maxWounds)
  const alivePlayers = state.playerOrder.filter(id => {
    const p = state.players[id];
    return p && p.wounds < (p.maxWounds ?? 3);
  });
  // Si no quedan jugadores vivos, el GAME_END_CHECK detectar├í derrota colectiva
  const playerList = alivePlayers.length > 0 ? alivePlayers : state.playerOrder;
  const aliveIndex = playerList.indexOf(state.activePlayerId);
  // Si el jugador actual ya no est├í vivo, buscar el siguiente desde el inicio
  const searchStart = aliveIndex >= 0 ? aliveIndex + 1 : 0;
  let nextIndex = searchStart % playerList.length;
  // Avanzar hasta encontrar un jugador distinto o volver al inicio
  if (playerList[nextIndex] === state.activePlayerId && playerList.length > 1) {
    nextIndex = (nextIndex + 1) % playerList.length;
  }
  const nextPlayerId = playerList[nextIndex];
  // Determinar si el turno incrementa: si el siguiente jugador est├í antes en el orden original
  const nextOriginalIndex = state.playerOrder.indexOf(nextPlayerId);
  const newTurnNumber = state.turnNumber + (nextOriginalIndex <= currentIndex ? 1 : 0);

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'GAME_END_CHECK',
    seq: nextSeq(),
  });

  return {
    state: {
      ...state,
      phase: 'GAME_END_CHECK',
      activePlayerId: nextPlayerId,
      turnNumber: newTurnNumber,
    },
    events,
  };
}

// ============================================================================
// GAME_END_CHECK ÔÇö comprobar si la partida ha terminado
// ============================================================================

function processGameEndCheck(
  state: GameState,
  _rng: DeterministicRng,
  _catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];

  // Especificacion 3.8: la partida termina cuando no quedan enemigos
  // en el campo tras derrotar al Se├▒or de la Guerra.
  const battlefieldEmpty = state.battlefield.length === 0;
  const warlordDefeated = state.warlordDefeated;

  // Especificacion 3.1: Derrota colectiva si todos los h├®roes quedan eliminados
  const allHeroesEliminated = state.playerOrder.every(pid => {
    const p = state.players[pid];
    return p.wounds >= (p.maxWounds ?? 999);
  });
  if (allHeroesEliminated && state.playerOrder.length > 0) {
    events.push({
      type: 'GAME_ENDED',
      winnerId: null, // Derrota colectiva
      scores: {},
      seq: nextSeq(),
    });
    return { state: { ...state, phase: 'FINISHED' }, events };
  }

  // D348: Si el mazo de la Horda se agota sin revelar al Warlord y el campo est├í vac├¡o,
  // la partida termina en derrota (estado imposible: no hay m├ís enemigos)
  if (!warlordDefeated && battlefieldEmpty && state.hordeDeck.length === 0) {
    events.push({
      type: 'GAME_ENDED',
      winnerId: null, // Derrota: Warlord no derrotado
      scores: {},
      seq: nextSeq(),
    });
    return { state: { ...state, phase: 'FINISHED' }, events };
  }

  // Especificacion 3.1: la partida termina cuando:
  // 1. Ha aparecido el Se├▒or de la Guerra
  // 2. El Se├▒or de la Guerra ha sido derrotado
  // 3. No queda ning├║n enemigo en el campo de batalla
  // D355: En multiclase (2 Se├▒ores), ambos deben ser derrotados y el mazo de la Horda debe estar vac├¡o
  const requiredWarlordKills = state.mode === 'MULTICLASS' ? 2 : 1;
  const allWarlordsDefeated = state.warlordsDefeatedCount >= requiredWarlordKills;
  if (allWarlordsDefeated && battlefieldEmpty && (state.mode !== 'MULTICLASS' || state.hordeDeck.length === 0)) {
    // Modo solitario: puntuaci├│n diferente (spec ┬º4.3)
    if (state.mode === 'SOLO' && state.playerOrder.length === 1) {
      const playerId = state.playerOrder[0];
      const solo = calculateSoloScore(state, playerId);
      events.push({
        type: 'GAME_ENDED',
        winnerId: playerId,
        scores: { [playerId]: solo.total },
        seq: nextSeq(),
      });
      return { state: { ...state, phase: 'FINISHED' }, events };
    }
    // Recuento de Gloria
    // Recuento de Gloria (especificacion 3.8):
    // 1. Fichas de Gloria acumuladas (ya incluyen Gloria de trofeos
    //    porque applyEvent la suma al derrotar enemigos)
    // 2. 1 Gloria por cada 3 Monedas
    // 3. Tenaz: +1 Gloria si llegas al final sin Heridas
    const scores: Record<string, number> = {};
    const trophyCounts: Record<string, number> = {};
    for (const playerId of state.playerOrder) {
      const player = state.players[playerId];
      let total = player.glory;
      // 1 Gloria por cada 3 Monedas
      total += Math.floor(player.coins / 3);
      // Tenaz: +1 si sin Heridas
      if (player.wounds === 0) {
        total += 1;
      }
      scores[playerId] = total;
      trophyCounts[playerId] = player.trophies.length;
    }

    // Determinar ganador (mas Gloria)
    // Empate: gana el jugador con mas cartas de enemigos derrotados (especificacion 3.8)
    let winnerId: string | null = null;
    let maxGlory = -1;
    for (const playerId of state.playerOrder) {
      const glory = scores[playerId];
      if (glory > maxGlory) {
        maxGlory = glory;
        winnerId = playerId;
      } else if (glory === maxGlory && winnerId !== null) {
        // Desempate por trofeos
        if (trophyCounts[playerId] > trophyCounts[winnerId]) {
          winnerId = playerId;
        }
      }
    }

    events.push({
      type: 'GAME_ENDED',
      winnerId,
      scores,
      seq: nextSeq(),
    });

    return { state: { ...state, phase: 'FINISHED' }, events };
  }

  // Continuar al siguiente turno
  events.push({
    type: 'TURN_STARTED',
    playerId: state.activePlayerId,
    turnNumber: state.turnNumber,
    seq: nextSeq(),
  });

  // Efectos opcionales de inicio de turno (Monta├▒as de Ur, Puerto de Eque, Yacimientos de Jade)
  if (state.scenario) {
    const turnStartChoice = onTurnStart(state, state.scenario.definitionId);
    if (turnStartChoice) {
      state = {
        ...state,
        pendingChoices: [
          ...state.pendingChoices,
          {
            choiceId: `turn-start-${state.turnNumber}`,
            playerId: state.activePlayerId,
            type: 'CONFIRM' as const,
            prompt: turnStartChoice.prompt,
            options: [],
            minSelections: 0,
            maxSelections: 1,
          },
        ],
      };
    }
  }

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'ATTACK_CHOICE',
    seq: nextSeq(),
  });

  return { state: { ...state, phase: 'ATTACK_CHOICE' }, events };
}

/**
 * Setup ÔÇö preparacion de una partida.
 *
 * Pasos:
 * 1. Construir la Horda (27 Huestes + 1 Se├▒or al final).
 * 2. Construir el mazo de Mercado (14 cartas).
 * 3. Construir el mazo de Escenarios (12 cartas, si useScenarios).
 * 4. Para cada jugador: construir mazo de Habilidad (15 cartas), barajar, robar 4.
 * 5. Colocar 3 Huestes en el campo de batalla.
 * 6. Colocar 5 cartas de Mercado.
 * 7. Revelar el primer Escenario.
 * 8. Determinar el L├¡der (puja con 1-2 cartas: mayor da├▒o sumado).
 * 9. Dar monedas iniciales (2 por jugador, 6 en solitario).
 *
 * Todo el azar pasa por el RNG sembrado para determinismo.
 */

import type {
  GameState,
  GameEvent,
  GameConfig,
  CardInstance,
  CardDefinition,
  PlayerState,
  EnemyState,
  Zone,
} from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import { applyScenarioEffects } from '../scenarios/index.js';
import { resetPhaseSeq } from './engine.js';
import { validateMulticlassDeck } from '../modes/multiclass.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

let instanceCounter = 0;

function nextInstanceId(prefix: string): string {
  return `${prefix}-${++instanceCounter}`;
}

export interface SetupResult {
  state: GameState;
  events: GameEvent[];
  rng: DeterministicRng;
  errors: string[];
}

export function setupGame(
  config: GameConfig,
  catalog: CatalogLoadResult,
): SetupResult {
  // D386/D387: Reiniciar contadores globales para determinismo de replay
  resetInstanceCounter();
  resetPhaseSeq();
  const errors: string[] = [];
  const rng = new DeterministicRng(config.seed);
  const events: GameEvent[] = [];
  let seq = 0;

  // Estado inicial vacio
  let state: GameState = {
    phase: 'SETUP',
    mode: config.mode,
    activePlayerId: '',
    turnNumber: 0,
    players: {},
    playerOrder: config.heroes.map(h => h.playerId),
    battlefield: [],
    hordeDeck: [],
    market: [],
    marketDeck: [],
    scenario: null,
    scenarioDeck: [],
    scenarioCoins: 0,
    warlordRevealed: false,
    warlordDefeated: false,
    warlordsDefeatedCount: 0,
    pendingChoices: [],
    eventLog: [],
    monotonicCounter: 0,
    rngState: rng.serialize(),
    marketCostModifier: 0,
    ignoreCoinRewards: false,
    ignoreGloryRewards: false,
    orcFortitudeBonus: 0,
  };

  // === 1. Construir la Horda ===
  const hordeCards = catalog.byType.get('HORDE') ?? [];
  const warlordCards = catalog.byType.get('WARLORD') ?? [];

  if (hordeCards.length < 27) {
    errors.push(`Expected 27 Horde cards, got ${hordeCards.length}`);
  }

  // Tamano de la Horda segun numero de jugadores (especificacion 3.2.1):
  // 4 jugadores ÔåÆ 27, 3 jugadores ÔåÆ 23, 2 jugadores ÔåÆ 19
  // Solitario ÔåÆ 22 (retirar Huestes de Fortaleza 2)
  // Multiclase: 2 jugadores ÔåÆ 23, 3 jugadores ÔåÆ 27, 4 jugadores ÔåÆ 27 (spec ┬º5.2)
  const playerCount = config.heroes.length;
  let hordeSize: number;
  if (config.mode === 'SOLO') {
    // D379: En solitario se retiran las Huestes de Fortaleza 2 (quedan 22)
    // Calcular el tamano real basado en instancias (copies), no definiciones
    const soloHordeInstances = hordeCards
      .filter(c => (c.printedFortitude ?? 0) !== 2)
      .reduce((sum, c) => sum + c.copies, 0);
    hordeSize = Math.min(soloHordeInstances, 22);
  } else if (config.mode === 'MULTICLASS') {
    // Multiclase: Horda m├ís grande (spec ┬º5.2)
    if (playerCount >= 4) {
      hordeSize = 27;
    } else if (playerCount === 3) {
      hordeSize = 27;
    } else {
      hordeSize = 23;
    }
  } else if (playerCount >= 4) {
    hordeSize = 27;
  } else if (playerCount === 3) {
    hordeSize = 23;
  } else {
    hordeSize = 19;
  }

  const hordeInstances: CardInstance[] = [];
  if (config.mode === 'SOLO') {
    // Solo Huestes con Fortaleza != 2
    for (const card of hordeCards.filter(c => (c.printedFortitude ?? 0) !== 2)) {
      for (let i = 0; i < card.copies; i++) {
        hordeInstances.push({
          instanceId: nextInstanceId('horde'),
          definitionId: card.id,
          ownerId: 'horde',
          zone: 'HORDE_DECK' as Zone,
        });
      }
    }
  } else {
    for (const card of hordeCards) {
      for (let i = 0; i < card.copies; i++) {
        hordeInstances.push({
          instanceId: nextInstanceId('horde'),
          definitionId: card.id,
          ownerId: 'horde',
          zone: 'HORDE_DECK' as Zone,
        });
      }
    }
  }

  // Barajar la Horda y recortar al tamano adecuado
  const shuffledHorde = rng.shuffle(hordeInstances).slice(0, hordeSize);
  state.hordeDeck = shuffledHorde;

  // Se├▒ores de la Guerra (especificacion 3.2.1 y 5.2):
  // - Estandar/Solitario: 1 Se├▒or al final del mazo.
  // - Multiclase 2-3 jugadores: 1 Se├▒or al final.
  // - Multiclase 4 jugadores: 1 Se├▒or barajado entre las Huestes + 1 al final.
  const warlordCount = (config.mode === 'MULTICLASS' && playerCount >= 4) ? 2 : 1;
  // Especificacion 3.2.1: escoger al azar el Se├▒or de entre los disponibles
  const shuffledWarlords = rng.shuffle([...warlordCards]);
  const selectedWarlords = shuffledWarlords.slice(0, warlordCount);
  // Especificacion 3.2.5: el mazo se roba desde la parte inferior (final del array).
  // El Se├▒or va "encima" del mazo = debe ser la ├║ltima carta en salir = al PRINCIPIO del array.
  if (config.mode === 'MULTICLASS' && playerCount >= 4 && selectedWarlords.length >= 2) {
    // El primer Se├▒or se baraja con la Horda
    state.hordeDeck.push({
      instanceId: nextInstanceId('warlord'),
      definitionId: selectedWarlords[0].id,
      ownerId: 'horde',
      zone: 'HORDE_DECK' as Zone,
    });
    state.hordeDeck = rng.shuffle(state.hordeDeck);
    // El segundo Se├▒or va al principio (├║ltimo en salir)
    state.hordeDeck.unshift({
      instanceId: nextInstanceId('warlord'),
      definitionId: selectedWarlords[1].id,
      ownerId: 'horde',
      zone: 'HORDE_DECK' as Zone,
    });
  } else {
    for (const warlord of selectedWarlords) {
      state.hordeDeck.unshift({
        instanceId: nextInstanceId('warlord'),
        definitionId: warlord.id,
        ownerId: 'horde',
        zone: 'HORDE_DECK' as Zone,
      });
    }
  }

  // === 2. Construir el mazo de Mercado ===
  const marketCardsAll = catalog.byType.get('MARKET') ?? [];
  // D364: En multiclase, filtrar mercado por capabilities de los jugadores
  let marketCards = marketCardsAll;
  if (config.mode === 'MULTICLASS') {
    const playerCapabilities = new Set<string>();
    for (const heroConfig of config.heroes) {
      const heroDef = catalog.byId.get(heroConfig.heroId);
      if (heroDef?.capabilities) {
        for (const cap of heroDef.capabilities) playerCapabilities.add(cap);
      }
      // Incluir capabilities de la segunda clase
      const secondDeckIdParts = heroConfig.secondDeckId?.split('.');
      const secondClass = secondDeckIdParts?.[0]?.toUpperCase();
      if (secondClass === 'EXPLORER') { playerCapabilities.add('RANGED'); playerCapabilities.add('EXPERTISE'); }
      if (secondClass === 'WARRIOR') { playerCapabilities.add('MELEE'); playerCapabilities.add('EXPERTISE'); }
      if (secondClass === 'MAGE') { playerCapabilities.add('MAGIC'); }
      if (secondClass === 'ROGUE') { playerCapabilities.add('EXPERTISE'); }
    }
    // D377: Filtrar mercado considerando tambien penaltyCapabilities
    // (un hero multiclase puede comprar cartas con penalizacion si tiene el icono penalizado)
    marketCards = marketCardsAll.filter(card => {
      if (!card.requiredCapabilities || card.requiredCapabilities.length === 0) return true;
      // Puede comprar si tiene todos los required, o si puede sustituir con penalty
      return card.requiredCapabilities.every(cap =>
        playerCapabilities.has(cap) ||
        (card.penaltyCapabilities?.some(p => p.icon === cap && playerCapabilities.has(p.icon)) ?? false)
      );
    });
  }
  const marketInstances: CardInstance[] = [];
  if (config.mode === 'SOLO') {
    // Solitario: m├íx 1 copia de cada carta (spec ┬º4.1)
    for (const card of marketCards) {
      marketInstances.push({
        instanceId: nextInstanceId('market'),
        definitionId: card.id,
        ownerId: 'market',
        zone: 'MARKET_DECK' as Zone,
      });
    }
  } else {
    for (const card of marketCards) {
      for (let i = 0; i < card.copies; i++) {
        marketInstances.push({
          instanceId: nextInstanceId('market'),
          definitionId: card.id,
          ownerId: 'market',
          zone: 'MARKET_DECK' as Zone,
        });
      }
    }
  }
  state.marketDeck = rng.shuffle(marketInstances);

  // === 3. Construir el mazo de Escenarios ===
  if (config.useScenarios) {
    let scenarioCards = catalog.byType.get('SCENARIO') ?? [];
    // Solitario: retirar escenarios no v├ílidos (spec ┬º4.1)
    if (config.mode === 'SOLO') {
      scenarioCards = scenarioCards.filter(s => s.id !== 'scenario.tears-of-aradiel' && s.id !== 'scenario.cemenmar-wastes');
    }
    const scenarioInstances: CardInstance[] = scenarioCards.map(card => ({
      instanceId: nextInstanceId('scenario'),
      definitionId: card.id,
      ownerId: 'scenario',
      zone: 'SCENARIO_DECK' as Zone,
    }));
    state.scenarioDeck = rng.shuffle(scenarioInstances);
  }

  // === 4. Para cada jugador: construir mazo, barajar, robar 4 ===
  for (const heroConfig of config.heroes) {
    const heroDef = catalog.byId.get(heroConfig.heroId);
    if (!heroDef) {
      errors.push(`Hero not found: ${heroConfig.heroId}`);
      continue;
    }

    // Construir mazo de habilidad desde el deckId
    // deckId formato: "explorer.default" ÔåÆ clase explorer
    // Usar deckId del config (respeta la elecci├│n de clase del jugador)
    const deckIdParts = heroConfig.deckId.split('.');
    const deckClass = deckIdParts[0]?.toUpperCase() as 'EXPLORER' | 'WARRIOR' | 'MAGE' | 'ROGUE' | undefined;
    // Fallback: si deckId no tiene clase v├ílida, inferir de capabilities del h├®roe
    const heroClass = deckClass && catalog.byClass.has(deckClass)
      ? deckClass
      : heroDef.capabilities?.includes('RANGED') ? 'EXPLORER'
        : heroDef.capabilities?.includes('MELEE') ? 'WARRIOR'
        : heroDef.capabilities?.includes('MAGIC') ? 'MAGE'
        : 'ROGUE';

    const classCards = catalog.byClass.get(heroClass) ?? [];

    // D365-D366: Multiclase ÔÇö construir mazo con 2 clases si secondDeckId est├í presente
    const secondDeckIdParts = heroConfig.secondDeckId?.split('.');
    const secondClass = secondDeckIdParts?.[0]?.toUpperCase() as 'EXPLORER' | 'WARRIOR' | 'MAGE' | 'ROGUE' | undefined;
    const secondClassCards = (secondClass && catalog.byClass.has(secondClass))
      ? (catalog.byClass.get(secondClass) ?? [])
      : [];

    const deckInstances: CardInstance[] = [];
    if (secondClassCards.length > 0 && config.mode === 'MULTICLASS') {
      // Multiclase: m├¡nimo 5 de cada clase, 15 total
      // Tracker de copias usadas por definitionId para evitar duplicar copias
      const usedCopies = new Map<string, number>();
      const addCard = (card: CardDefinition): CardInstance => {
        usedCopies.set(card.id, (usedCopies.get(card.id) ?? 0) + 1);
        return {
          instanceId: nextInstanceId('ability'),
          definitionId: card.id,
          ownerId: heroConfig.playerId,
          zone: 'ABILITY_DECK' as Zone,
          name: card.name,
        };
      };
      const remainingCopies = (card: CardDefinition): number =>
        card.copies - (usedCopies.get(card.id) ?? 0);

      // Paso 1: tomar exactamente 5 de la 1┬¬ clase
      let firstAdded = 0;
      const firstMin = 5;
      for (const card of classCards) {
        if (firstAdded >= firstMin) break;
        for (let i = 0; i < card.copies && firstAdded < firstMin; i++) {
          deckInstances.push(addCard(card));
          firstAdded++;
        }
      }
      // Paso 2: tomar exactamente 5 de la 2┬¬ clase
      let secondAdded = 0;
      const secondMin = 5;
      for (const card of secondClassCards) {
        if (secondAdded >= secondMin) break;
        for (let i = 0; i < card.copies && secondAdded < secondMin; i++) {
          deckInstances.push(addCard(card));
          secondAdded++;
        }
      }
      // Paso 3: completar hasta 15 con copias restantes de cualquiera de las 2 clases
      const remaining = 15 - firstAdded - secondAdded;
      if (remaining > 0) {
        // Alternar entre ambas clases para equilibrar, respetando el l├¡mite de copias
        let firstIdx = 0;
        let secondIdx = 0;
        for (let r = 0; r < remaining; r++) {
          // Buscar la siguiente carta de la 1┬¬ clase con copias disponibles
          while (firstIdx < classCards.length && remainingCopies(classCards[firstIdx]) <= 0) {
            firstIdx++;
          }
          // Buscar la siguiente carta de la 2┬¬ clase con copias disponibles
          while (secondIdx < secondClassCards.length && remainingCopies(secondClassCards[secondIdx]) <= 0) {
            secondIdx++;
          }
          // Intentar a├▒adir de la 1┬¬ clase; si no hay, de la 2┬¬
          if (firstIdx < classCards.length) {
            deckInstances.push(addCard(classCards[firstIdx]));
          } else if (secondIdx < secondClassCards.length) {
            deckInstances.push(addCard(secondClassCards[secondIdx]));
          } else {
            break; // No hay m├ís cartas disponibles
          }
        }
      }
      // D364: Validar que el mazo cumple las reglas multiclase
      const validation = validateMulticlassDeck(
        deckInstances.map(c => c.definitionId),
        catalog,
      );
      if (!validation.ok) {
        errors.push(`Multiclass deck validation failed for ${heroConfig.playerId}: ${validation.errors.join(', ')}`);
      }
    } else {
      // Una sola clase: usar todas las cartas de la clase
      for (const card of classCards) {
        for (let i = 0; i < card.copies; i++) {
          deckInstances.push({
            instanceId: nextInstanceId('ability'),
            definitionId: card.id,
            ownerId: heroConfig.playerId,
            zone: 'ABILITY_DECK' as Zone,
            name: card.name,
          });
        }
      }
    }

    const shuffledDeck = rng.shuffle(deckInstances);

    // Robar 4 cartas (mano inicial)
    const hand = shuffledDeck.slice(0, 4).map(c => ({ ...c, zone: 'HAND' as Zone }));
    const remainingDeck = shuffledDeck.slice(4);

    // Monedas iniciales
    const initialCoins = config.mode === 'SOLO' ? 6 : 2;

    // Solitario: sin pericia de h├®roe (spec ┬º4.1)
    const heroUses = config.mode === 'SOLO' ? 0 : (heroDef.heroAbility?.uses ?? 0);

    // D366: En multiclase, las capabilities son la uni├│n de ambas clases
    // Especificacion ┬º7.1: Guerrero=Melee+Pericia, Explorador=Ranged+Pericia,
    // Picaro=Pericia (puede usar Ranged con penalizacion -1), Mago=Magia
    const classToCaps: Record<string, ('MELEE' | 'RANGED' | 'EXPERTISE' | 'MAGIC')[]> = {
      EXPLORER: ['RANGED', 'EXPERTISE'],
      WARRIOR: ['MELEE', 'EXPERTISE'],
      MAGE: ['MAGIC'],
      ROGUE: ['EXPERTISE'],
    };
    const playerCaps = new Set<'MELEE' | 'RANGED' | 'EXPERTISE' | 'MAGIC'>(heroDef.capabilities ?? []);
    if (secondClass && config.mode === 'MULTICLASS') {
      for (const cap of classToCaps[secondClass] ?? []) {
        playerCaps.add(cap);
      }
    }
    const playerCapabilities = Array.from(playerCaps);

    const player: PlayerState = {
      playerId: heroConfig.playerId,
      heroId: heroConfig.heroId,
      heroFace: heroConfig.heroFace,
      heroUsesRemaining: heroUses,
      heroMaxUses: heroUses,
      glory: 0,
      coins: initialCoins,
      wounds: 0,
      maxWounds: heroDef.maxWounds ?? 3,
      capabilities: playerCapabilities,
      abilityDeck: remainingDeck,
      hand,
      wearPile: [],
      trophies: [],
      shields: 0,
      prevention: 0,
      damageCancellation: false,
      interceptedBy: null,
      modifiers: [],
      cardsPlayedThisTurn: {},
      cardsPlayedAgainstEnemy: {},
      oncePerTurnUsed: new Set(),
      persistentCards: [],
      supportDecks: [],
      playerAge: heroConfig.playerAge,
    };

    // Solitario: rellenar mazos de Apoyo (spec ┬º4.2)
    if (config.mode === 'SOLO' && config.soloSupportHeroIds) {
      for (const supportHeroId of config.soloSupportHeroIds) {
        const supportHeroDef = catalog.byId.get(supportHeroId);
        if (!supportHeroDef) continue;
        const supportClass = supportHeroDef.capabilities?.includes('RANGED') ? 'EXPLORER'
          : supportHeroDef.capabilities?.includes('MELEE') ? 'WARRIOR'
          : supportHeroDef.capabilities?.includes('MAGIC') ? 'MAGE'
          : 'ROGUE';
        const supportClassCards = catalog.byClass.get(supportClass) ?? [];
        const supportDeck: CardInstance[] = [];
        for (const card of supportClassCards) {
          for (let i = 0; i < card.copies; i++) {
            supportDeck.push({
              instanceId: `solo-support-${supportHeroId}-${card.id}-${i}`,
              definitionId: card.id,
              ownerId: heroConfig.playerId,
              zone: 'ABILITY_DECK' as Zone,
            });
          }
        }
        player.supportDecks.push(rng.shuffle(supportDeck));
      }
    }

    state.players[heroConfig.playerId] = player;

    // Evento: cartas robadas
    events.push({
      type: 'CARDS_DRAWN',
      playerId: heroConfig.playerId,
      count: hand.length,
      cardInstanceIds: hand.map(c => c.instanceId),
      seq: ++seq,
    });
  }

  // === 5. Colocar 3 Huestes en el campo de batalla ===
  // Especificacion 3.2.5: el mazo de Horda se roba desde la parte inferior
  const enemiesInField = state.hordeDeck.slice(-3);
  state.hordeDeck = state.hordeDeck.slice(0, -3);

  for (const enemyCard of enemiesInField) {
    const enemyDef = catalog.byId.get(enemyCard.definitionId);
    if (!enemyDef) continue;

    const enemy: EnemyState = {
      instanceId: enemyCard.instanceId,
      definitionId: enemyCard.definitionId,
      baseFortitude: enemyDef.printedFortitude ?? 1,
      wounds: 0,
      // Recompensa oculta: se carga del cat├ílogo pero no se revela al jugador
      // hasta derrotar al enemigo. El motor la usa internamente.
      reward: enemyDef.reward ?? null,
      modifiers: [],
      isWarlord: enemyDef.type === 'WARLORD',
      isOrc: enemyDef.isOrc ?? false,
      specialIcons: enemyDef.specialIcons ?? [],
      damageDisabled: false,
    };

    state.battlefield.push(enemy);

    // D401: Si el enemigo es Warlord, emitir WARLORD_REVEALED y marcarlo
    if (enemy.isWarlord) {
      events.push({
        type: 'WARLORD_REVEALED',
        warlordInstanceId: enemy.instanceId,
        definitionId: enemy.definitionId,
        seq: ++seq,
      });
      state.warlordRevealed = true;
    } else {
      events.push({
        type: 'ENEMY_REVEALED',
        enemyInstanceId: enemy.instanceId,
        definitionId: enemy.definitionId,
        fortitude: enemy.baseFortitude,
        seq: ++seq,
      });
    }
  }

  // D375: Aplicar bonus de Roghkiller a los 3 enemigos iniciales si est├í en el campo
  const roghkillerInField = state.battlefield.some(e =>
    e.isWarlord && catalog.byId.get(e.definitionId)?.name === 'Roghkiller'
  );
  if (roghkillerInField) {
    const roghkillerInstanceId = state.battlefield.find(e =>
      e.isWarlord && catalog.byId.get(e.definitionId)?.name === 'Roghkiller'
    )?.instanceId;
    state.battlefield = state.battlefield.map(e => {
      if (e.isOrc && e.instanceId !== roghkillerInstanceId) {
        return {
          ...e,
          modifiers: [
            ...e.modifiers,
            {
              id: `roghkiller-setup-${++seq}`,
              sourceId: 'roghkiller',
              layer: 'FORTITUDE_MODIFIERS',
              timestamp: seq,
              duration: 'WHILE_SOURCE_ACTIVE' as const,
              amount: 1,
            },
          ],
        };
      }
      return e;
    });
  }

  // === 6. Colocar 5 cartas de Mercado ===
  const marketInField = state.marketDeck.slice(0, 5);
  state.marketDeck = state.marketDeck.slice(5);
  // D378: En modo solitario, las cartas no seleccionadas no se usan (spec ┬º4.1: no se reponen)
  if (config.mode === 'SOLO') {
    state.marketDeck = [];
  }
  state.market = marketInField.map(c => ({ ...c, zone: 'MARKET' as Zone }));

  // === 7. Revelar el primer Escenario ===
  // D401: Si un Warlord ya est├í en el campo inicial, no se revela escenario (spec: "Cuando entre el Se├▒or de la Guerra, el escenario activo se descarta")
  if (config.useScenarios && state.scenarioDeck.length > 0 && !state.warlordRevealed) {
    const scenarioCard = state.scenarioDeck[0];
    state.scenarioDeck = state.scenarioDeck.slice(1);
    state.scenario = { ...scenarioCard, zone: 'SCENARIO_ACTIVE' as Zone };

    events.push({
      type: 'SCENARIO_REVEALED',
      scenarioInstanceId: state.scenario.instanceId,
      definitionId: state.scenario.definitionId,
      seq: ++seq,
    });

    // Aplicar efectos continuos del escenario (L├Âtharion, Ska├árg, Brunmar, etc.)
    const scenarioResult = applyScenarioEffects(state, state.scenario.definitionId, catalog);
    state = scenarioResult.state;

    // Solitario: 1 moneda sobre el escenario activo (spec ┬º4.1)
    if (config.mode === 'SOLO') {
      state.scenarioCoins = 1;
    }
  }

  // === 8. Determinar el L├¡der (puja con 1-2 cartas boca abajo) ===
  // Especificacion 3.2.6: cada jugador escoge 1 o 2 cartas de su mano,
  // se revelan simultaneamente y se comparan los valores de Dano (sumados).
  // El mayor es el L├¡der. Empate: jugador de mas edad (orden de turnos).
  // Las cartas usadas se colocan al FONDO del mazo. Luego roban hasta 4.
  //
  // D370: En solitario (1 jugador), no hay puja: el jugador es el L├¡der autom├íticamente.
  // En multijugador, se crean pendingChoices para que cada jugador elija sus cartas.
  // Si todos los jugadores env├¡an CHOOSE_LEADER_CARDS, se resuelve la puja.
  // Como fallback determinista (tests, IA), se usa heur├¡stica de mayor da├▒o.
  if (state.playerOrder.length === 1) {
    state.activePlayerId = state.playerOrder[0];
    events.push({
      type: 'LEADER_DETERMINED',
      playerId: state.playerOrder[0],
      seq: ++seq,
    });
  } else {
    // Crear pendingChoices para cada jugador: elegir 1-2 cartas de la mano
    for (const playerId of state.playerOrder) {
      const player = state.players[playerId];
      if (!player) continue;
      state.pendingChoices.push({
        choiceId: `leader-bid-${playerId}`,
        playerId,
        type: 'SELECT_CARDS_FOR_LEADER',
        prompt: 'Elige 1 o 2 cartas de tu mano para la puja de L├¡der',
        options: player.hand.map(c => c.instanceId),
        minSelections: 1,
        maxSelections: 2,
      });
    }
    // Fallback determinista: usar heur├¡stica para que el estado sea jugable
    // sin intervenci├│n del jugador (tests, IA). El comando CHOOSE_LEADER_CARDS
    // puede override esto cuando los jugadores elijan manualmente.
    let leaderId = state.playerOrder[0];
    let maxDamage = -1;
    for (const playerId of state.playerOrder) {
      const player = state.players[playerId];
      if (!player) continue;
      const sortedHand = [...player.hand].sort((a, b) => {
        const defA = catalog.byId.get(a.definitionId);
        const defB = catalog.byId.get(b.definitionId);
        return (defB?.printedAttack ?? 0) - (defA?.printedAttack ?? 0);
      });
      const bidCount = Math.min(2, sortedHand.length);
      const bidCards = sortedHand.slice(0, bidCount);
      let bidDamage = 0;
      for (const card of bidCards) {
        const cardDef = catalog.byId.get(card.definitionId);
        bidDamage += cardDef?.printedAttack ?? 0;
      }
      if (bidDamage > maxDamage) {
        maxDamage = bidDamage;
        leaderId = playerId;
      } else if (bidDamage === maxDamage) {
        // Empate: gana el jugador con mayor edad (spec ┬º3.2.6)
        const currentLeader = state.players[leaderId];
        const challenger = state.players[playerId];
        const currentAge = currentLeader?.playerAge ?? 0;
        const challengerAge = challenger?.playerAge ?? 0;
        if (challengerAge > currentAge) {
          leaderId = playerId;
        }
      }
      // Retirar las cartas pujadas y ponerlas al fondo
      const bidIds = new Set(bidCards.map(c => c.instanceId));
      state.players[playerId] = {
        ...state.players[playerId],
        hand: state.players[playerId].hand.filter(c => !bidIds.has(c.instanceId)),
        abilityDeck: [...state.players[playerId].abilityDeck, ...bidCards.map(c => ({ ...c, zone: 'ABILITY_DECK' as Zone }))],
      };
    }
    // Robar hasta 4
    for (const playerId of state.playerOrder) {
      const player = state.players[playerId];
      if (!player) continue;
      while (player.hand.length < 4 && player.abilityDeck.length > 0) {
        const drawn = player.abilityDeck[0];
        player.abilityDeck = player.abilityDeck.slice(1);
        player.hand = [...player.hand, { ...drawn, zone: 'HAND' as Zone }];
      }
    }
    state.activePlayerId = leaderId;
    events.push({
      type: 'LEADER_DETERMINED',
      playerId: leaderId,
      seq: ++seq,
    });
  }

  // === 9. Pasar a fase de seleccion inicial / primer turno ===
  state.phase = 'INITIAL_PLAYER_SELECTION';
  events.push({
    type: 'PHASE_CHANGED',
    phase: 'INITIAL_PLAYER_SELECTION',
    seq: ++seq,
  });

  // Actualizar rngState en el estado
  state.rngState = rng.serialize();

  return { state, events, rng, errors };
}

/**
 * Resolver la puja de L├¡der cuando todos los jugadores han elegido sus cartas.
 * Se llama desde execute.ts al recibir CHOOSE_LEADER_CARDS.
 */
export function resolveLeaderBid(
  state: GameState,
  catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  let seq = 0;

  // Recoger las cartas pujadas por cada jugador desde las pendingChoices resueltas
  // Las cartas elegidas se guardan en state.pendingChoices como relatedCardIds
  // tras ser resueltas. Aqu├¡ leemos el estado actual.
  let leaderId = state.playerOrder[0];
  let maxDamage = -1;

  for (const playerId of state.playerOrder) {
    const player = state.players[playerId];
    if (!player) continue;

    // Buscar las cartas pujadas: est├ín marcadas en player.leaderBidCards
    const bidCardIds = (player as any).leaderBidCards as string[] | undefined;
    if (!bidCardIds || bidCardIds.length === 0) continue;

    const bidCards = player.hand.filter(c => bidCardIds.includes(c.instanceId));
    let bidDamage = 0;
    for (const card of bidCards) {
      const cardDef = catalog.byId.get(card.definitionId);
      bidDamage += cardDef?.printedAttack ?? 0;
    }

    // Empate: gana el jugador con mayor edad (spec ┬º3.2.6)
    if (bidDamage > maxDamage) {
      maxDamage = bidDamage;
      leaderId = playerId;
    } else if (bidDamage === maxDamage) {
      const currentLeader = state.players[leaderId];
      const challenger = state.players[playerId];
      const currentAge = currentLeader?.playerAge ?? 0;
      const challengerAge = challenger?.playerAge ?? 0;
      if (challengerAge > currentAge) {
        leaderId = playerId;
      }
    }

    // Retirar las cartas pujadas de la mano y ponerlas al fondo del mazo
    const bidIds = new Set(bidCards.map(c => c.instanceId));
    state.players[playerId] = {
      ...state.players[playerId],
      hand: state.players[playerId].hand.filter(c => !bidIds.has(c.instanceId)),
      abilityDeck: [...state.players[playerId].abilityDeck, ...bidCards.map(c => ({ ...c, zone: 'ABILITY_DECK' as Zone }))],
    };
  }

  // Robar hasta tener 4 cartas en mano
  for (const playerId of state.playerOrder) {
    const player = state.players[playerId];
    if (!player) continue;
    while (player.hand.length < 4 && player.abilityDeck.length > 0) {
      const drawn = player.abilityDeck[0];
      state.players[playerId] = {
        ...state.players[playerId],
        abilityDeck: state.players[playerId].abilityDeck.slice(1),
        hand: [...state.players[playerId].hand, { ...drawn, zone: 'HAND' as Zone }],
      };
    }
  }

  state.activePlayerId = leaderId;
  events.push({
    type: 'LEADER_DETERMINED',
    playerId: leaderId,
    seq: ++seq,
  });

  // Limpiar pendingChoices de l├¡der
  state.pendingChoices = state.pendingChoices.filter(c => !c.choiceId.startsWith('leader-bid-'));

  return { state, events };
}

/**
 * Iniciar el primer turno despues de la seleccion inicial.
 */
export function startFirstTurn(state: GameState, _rng: DeterministicRng): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  let seq = 0;

  const newState: GameState = {
    ...state,
    phase: 'TURN_START',
    turnNumber: 1,
  };

  events.push({
    type: 'TURN_STARTED',
    playerId: newState.activePlayerId,
    turnNumber: 1,
    seq: ++seq,
  });

  events.push({
    type: 'PHASE_CHANGED',
    phase: 'ATTACK_CHOICE',
    seq: ++seq,
  });

  newState.phase = 'ATTACK_CHOICE';

  return { state: newState, events };
}

/** Reset del contador de instancias (para tests) */
export function resetInstanceCounter(): void {
  instanceCounter = 0;
}

/**
 * Fases del juego ÔÇö definicion de transiciones validas.
 *
 * Flujo principal:
 *   SETUP ÔåÆ INITIAL_PLAYER_SELECTION ÔåÆ TURN_START ÔåÆ ATTACK_CHOICE
 *     ÔåÆ PLAYER_ATTACK ÔåÆ HORDE_ATTACK ÔåÆ MARKET ÔåÆ RESTORATION
 *     ÔåÆ BATTLEFIELD_REPLENISHMENT ÔåÆ SCENARIO_TRANSITION ÔåÆ TURN_END
 *     ÔåÆ GAME_END_CHECK ÔåÆ (TURN_START | FINISHED)
 *
 * Excepciones:
 *   - ATTACK_CHOICE puede ir a MARKET directamente (Evasion)
 *   - PLAYER_ATTACK puede volver a si mismo (mas cartas) o a HORDE_ATTACK (End Attack)
 *   - Si no hay enemigos en campo, PLAYER_ATTACK ÔåÆ BATTLEFIELD_REPLENISHMENT
 */

import type { Phase } from '@nt4h/schema';

const TRANSITIONS: Record<Phase, Phase[]> = {
  SETUP: ['INITIAL_PLAYER_SELECTION'],
  INITIAL_PLAYER_SELECTION: ['TURN_START'],
  TURN_START: ['ATTACK_CHOICE'],
  ATTACK_CHOICE: ['PLAYER_ATTACK', 'HORDE_ATTACK', 'MARKET'],
  PLAYER_ATTACK: ['PLAYER_ATTACK', 'HORDE_ATTACK', 'BATTLEFIELD_REPLENISHMENT'],
  RESOLVING_CARD: ['PLAYER_ATTACK', 'WAITING_FOR_CHOICE'],
  WAITING_FOR_CHOICE: ['PLAYER_ATTACK', 'HORDE_ATTACK'],
  HORDE_ATTACK: ['MARKET'],
  MARKET: ['RESTORATION'],
  RESTORATION: ['BATTLEFIELD_REPLENISHMENT'],
  BATTLEFIELD_REPLENISHMENT: ['SCENARIO_TRANSITION'],
  SCENARIO_TRANSITION: ['TURN_END'],
  TURN_END: ['GAME_END_CHECK'],
  GAME_END_CHECK: ['TURN_START', 'FINISHED'],
  FINISHED: [],
};

export function canTransition(from: Phase, to: Phase): boolean {
  return TRANSITIONS[from]?.includes(to) ?? false;
}

export function nextPhases(from: Phase): Phase[] {
  return TRANSITIONS[from] ?? [];
}

/** Valida y devuelve la nueva fase, o null si la transicion es invalida */
export function validateTransition(from: Phase, to: Phase): { ok: true } | { ok: false; reason: string } {
  if (canTransition(from, to)) return { ok: true };
  return {
    ok: false,
    reason: `Invalid phase transition: ${from} ÔåÆ ${to}. Valid: ${(TRANSITIONS[from] ?? []).join(', ')}`,
  };
}

/**
 * projection ÔÇö proyecci├│n del estado por jugador (ocultaci├│n de informaci├│n).
 *
 * En online, cada jugador recibe una vista del estado que oculta:
 * - Manos ajenas
 * - Orden de los mazos
 * - Recompensas no reveladas de enemigos
 * - Elecciones secretas
 *
 * Implementaci├│n de projectForPlayer (secci├│n 51.11 de la especificaci├│n).
 */

import type {
  GameState,
  GameEvent,
  EnemyState,
  PlayerState,
} from '@nt4h/schema';

/** Eventos que contienen informaci├│n privada */
const PRIVATE_EVENT_TYPES = new Set([
  'CARDS_DRAWN',
  'CARDS_LOST',
  'CARDS_RECOVERED',
  'DECK_SHUFFLED',
  'DECK_RESHUFFLED',
  'CARDS_REVEALED_TO_PLAYER',
]);

export interface PlayerGameState {
  phase: string;
  activePlayerId: string;
  turnNumber: number;
  mode: string;
  playerOrder: string[];

  battlefield: Array<{
    instanceId: string;
    definitionId: string;
    baseFortitude: number;
    wounds: number;
    isWarlord: boolean;
    isOrc: boolean;
    damageDisabled: boolean;
    /** La recompensa solo es visible si el enemigo ya fue derrotado */
    reward: { coins: number; glory: number } | null;
  }>;

  players: Record<string, {
    heroId: string;
    heroFace: string;
    glory: number;
    coins: number;
    wounds: number;
    maxWounds: number;
    heroUsesRemaining: number;
    heroMaxUses: number;
    deckSize: number;
    handSize: number;
    wearPileSize: number;
    trophyCount: number;
    shields: number;
    prevention: number;
    damageCancellation: boolean;
    /** Solo el propio jugador ve su mano */
    hand?: Array<{
      instanceId: string;
      definitionId: string;
    }>;
    capabilities: string[];
    persistentCards: Array<{
      instanceId: string;
      definitionId: string;
      persistentTrigger: string;
    }>;
  }>;

  market: Array<{
    instanceId: string;
    definitionId: string;
  }>;
  marketDeckSize: number;

  hordeDeckSize: number;

  scenario: { instanceId: string; definitionId: string } | null;
  scenarioDeckSize: number;

  warlordRevealed: boolean;
  warlordDefeated: boolean;
  warlordsDefeatedCount: number;

  pendingChoices: Array<{
    choiceId: string;
    playerId: string;
    type: string;
    prompt: string;
    options: string[];
    relatedCardIds?: string[];
  }>;

  eventLog: GameEvent[];
  marketCostModifier: number;
  ignoreCoinRewards: boolean;
  ignoreGloryRewards: boolean;
}

/**
 * Proyectar el estado completo para un jugador espec├¡fico.
 * viewerId = null significa espectador (no ve ninguna mano).
 */
export function projectForPlayer(
  state: GameState,
  viewerId: string | null,
): PlayerGameState {
  const battlefield = state.battlefield.map((e: EnemyState) => ({
    instanceId: e.instanceId,
    definitionId: e.definitionId,
    baseFortitude: e.baseFortitude,
    wounds: e.wounds,
    isWarlord: e.isWarlord,
    isOrc: e.isOrc,
    damageDisabled: e.damageDisabled,
    // La recompensa solo es visible si el enemigo fue derrotado
    // (en ese caso ya no est├í en el battlefield, pero por consistencia)
    reward: null,
  }));

  const players: PlayerGameState['players'] = {};
  for (const [id, p] of Object.entries(state.players)) {
    const playerState = p as PlayerState;
    players[id] = {
      heroId: playerState.heroId,
      heroFace: playerState.heroFace,
      glory: playerState.glory,
      coins: playerState.coins,
      wounds: playerState.wounds,
      maxWounds: playerState.maxWounds,
      heroUsesRemaining: playerState.heroUsesRemaining,
      heroMaxUses: playerState.heroMaxUses,
      deckSize: playerState.abilityDeck.length,
      handSize: playerState.hand.length,
      wearPileSize: playerState.wearPile.length,
      trophyCount: playerState.trophies.length,
      shields: playerState.shields,
      prevention: playerState.prevention,
      damageCancellation: playerState.damageCancellation,
      capabilities: playerState.capabilities,
      persistentCards: playerState.persistentCards.map(c => ({
        instanceId: c.instanceId,
        definitionId: c.definitionId,
        persistentTrigger: c.persistentTrigger ?? '',
      })),
    };

    // Solo el propio jugador ve su mano
    if (id === viewerId) {
      players[id].hand = playerState.hand.map(c => ({
        instanceId: c.instanceId,
        definitionId: c.definitionId,
      }));
    }
  }

  const market = state.market.map(c => ({
    instanceId: c.instanceId,
    definitionId: c.definitionId,
  }));

  const scenario = state.scenario
    ? { instanceId: state.scenario.instanceId, definitionId: state.scenario.definitionId }
    : null;

  // Filtrar elecciones pendientes: solo las del viewer (espectador no ve ninguna)
  const pendingChoices = (state.pendingChoices ?? [])
    .filter(c => viewerId !== null && c.playerId === viewerId)
    .map(c => ({
      choiceId: c.choiceId,
      playerId: c.playerId,
      type: c.type,
      prompt: c.prompt,
      options: c.options,
      relatedCardIds: c.relatedCardIds,
    }));

  // Filtrar eventos privados del log
  const eventLog = (state.eventLog ?? []).filter(
    (e: GameEvent) => !isPrivateEvent(e, viewerId),
  );

  return {
    phase: state.phase,
    activePlayerId: state.activePlayerId,
    turnNumber: state.turnNumber,
    mode: state.mode,
    playerOrder: state.playerOrder,
    battlefield,
    players,
    market,
    marketDeckSize: state.marketDeck.length,
    hordeDeckSize: state.hordeDeck.length,
    scenario,
    scenarioDeckSize: state.scenarioDeck.length,
    warlordRevealed: state.warlordRevealed,
    warlordDefeated: state.warlordDefeated,
    warlordsDefeatedCount: state.warlordsDefeatedCount,
    pendingChoices,
    eventLog,
    marketCostModifier: state.marketCostModifier,
    ignoreCoinRewards: state.ignoreCoinRewards,
    ignoreGloryRewards: state.ignoreGloryRewards,
  };
}

/**
 * Determinar si un evento contiene informaci├│n privada que no debe
 * revelarse a un viewer espec├¡fico.
 */
function isPrivateEvent(event: GameEvent, viewerId: string | null): boolean {
  if (!PRIVATE_EVENT_TYPES.has(event.type)) return false;

  // CARDS_DRAWN, CARDS_LOST, CARDS_RECOVERED: solo visibles para el jugador afectado
  if (event.type === 'CARDS_DRAWN' || event.type === 'CARDS_LOST' || event.type === 'CARDS_RECOVERED') {
    const ev = event as { playerId?: string };
    return ev.playerId !== viewerId;
  }

  // DECK_SHUFFLED, DECK_RESHUFFLED: el orden del mazo es secreto para todos
  // (ni siquiera el due├▒o deber├¡a ver newOrder)
  if (event.type === 'DECK_SHUFFLED' || event.type === 'DECK_RESHUFFLED') {
    return true;
  }

  // CARDS_REVEALED_TO_PLAYER: solo visible para el jugador receptor
  if (event.type === 'CARDS_REVEALED_TO_PLAYER') {
    const ev = event as { playerId?: string };
    return ev.playerId !== viewerId;
  }

  return false;
}

/**
 * Proyectar una lista de eventos para un viewer, filtrando los privados.
 */
export function projectEventsForPlayer(
  events: GameEvent[],
  viewerId: string | null,
): GameEvent[] {
  return events.filter(e => !isPrivateEvent(e, viewerId));
}

/**
 * replay ÔÇö serializaci├│n, snapshots y replay de partidas.
 *
 * Implementaci├│n de GameSnapshot, ReplayEnvelope, replay() y stateHash()
 * (secci├│n 51.12 de la especificaci├│n).
 *
 * El replay permite reconstruir cualquier partida a partir de:
 * - Estado inicial (snapshot)
 * - Semilla del RNG
 * - Secuencia de comandos
 * - Versiones del contenido
 */

import type { GameState, Command, GameEvent } from '@nt4h/schema';
import { DeterministicRng } from '../rng/index.js';
import { EffectRegistry, registerCoreEffects } from '../effects/registry.js';
import { execute } from '../commands/execute.js';
import { replayEvents } from '../events/applyEvent.js';
import { processPhases } from '../phases/engine.js';
import type { CatalogLoadResult } from '@nt4h/catalog';

/** Versi├│n del esquema de snapshot */
export const SNAPSHOT_VERSION = 1;

/** Versi├│n actual del motor */
export const ENGINE_VERSION = '0.1.0';

export interface GameSnapshot {
  version: number;
  engineVersion: string;
  seed: string;
  rngState: number;
  state: GameState;
  eventCount: number;
  takenAt: number;
}

export interface ReplayEnvelope {
  version: '1.0';
  gameType: string;
  seed: string;
  engineVersion: string;
  contentVersions: Record<string, string>;
  initialState: GameSnapshot;
  commands: Command[];
}

export interface CommandResult {
  accepted: boolean;
  reason?: string;
  events: GameEvent[];
  newState: GameState;
}

/**
 * Crear un snapshot del estado actual.
 */
export function createSnapshot(
  state: GameState,
  rng: DeterministicRng,
  eventCount: number,
): GameSnapshot {
  const rngSerialized = rng.serialize();
  return {
    version: SNAPSHOT_VERSION,
    engineVersion: ENGINE_VERSION,
    seed: rngSerialized.seed,
    rngState: rngSerialized.state,
    state,
    eventCount,
    takenAt: state.monotonicCounter,
  };
}

/**
 * Reconstruir una partida desde un ReplayEnvelope.
 * Reproduce exactamente el mismo estado final.
 */
export function replay(envelope: ReplayEnvelope, catalog?: CatalogLoadResult): GameState {
  const snapshot = envelope.initialState;
  let state = snapshot.state;
  const rng = DeterministicRng.deserialize({
    seed: snapshot.seed,
    state: snapshot.rngState,
  });
  const registry = new EffectRegistry();
  registerCoreEffects(registry);

  for (const cmd of envelope.commands) {
    const result = execute(state, cmd, rng, registry, catalog);
    if (!result.accepted) {
      // En replay, los comandos rechazados se ignoran
      continue;
    }
    state = result.newState;
    // Ejecutar fases autom├íticas tras cada comando (D343)
    if (catalog) {
      state = processPhases(state, rng, catalog).state;
    }
  }

  return state;
}

/**
 * Reconstruir desde un snapshot + eventos posteriores.
 */
export function replayFromSnapshot(
  snapshot: GameSnapshot,
  events: GameEvent[],
): GameState {
  let state = snapshot.state;
  state = replayEvents(state, events);
  return state;
}

/**
 * Hash determinista del estado para verificaci├│n.
 * Usa un hash estable que no depende del orden de claves del objeto.
 */
export function stateHash(state: GameState, rngState?: number): string {
  const data = rngState !== undefined ? { state, rngState } : { state };
  return deterministicJsonHash(data);
}

/**
 * Hash JSON determinista.
 * Ordena las claves de los objetos alfab├®ticamente para garantizar
 * que el mismo estado produzca siempre el mismo hash.
 */
function deterministicJsonHash(data: unknown): string {
  const json = stableStringify(data);
  // FNV-1a hash de 32 bits
  let hash = 0x811c9dc5;
  for (let i = 0; i < json.length; i++) {
    hash ^= json.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

/**
 * JSON.stringify con claves ordenadas establemente.
 */
function stableStringify(value: unknown): string {
  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    return '[' + value.map(stableStringify).join(',') + ']';
  }

  // Set se serializa como array ordenado
  if (value instanceof Set) {
    return stableStringify(Array.from(value).sort());
  }

  // Map se serializa como array de pares ordenados por clave
  if (value instanceof Map) {
    const entries = Array.from(value.entries()).sort((a, b) =>
      String(a[0]).localeCompare(String(b[0]))
    );
    return stableStringify(entries);
  }

  const keys = Object.keys(value).sort();
  const pairs = keys.map(k => JSON.stringify(k) + ':' + stableStringify((value as Record<string, unknown>)[k]));
  return '{' + pairs.join(',') + '}';
}

/**
 * Crear un ReplayEnvelope desde una partida jugada.
 */
export function createReplay(
  gameType: string,
  seed: string,
  initialState: GameState,
  commands: Command[],
  contentVersions: Record<string, string> = {},
  rng?: DeterministicRng,
): ReplayEnvelope {
  const rngState = rng ? rng.serialize().state : (initialState.rngState?.state ?? 0);
  return {
    version: '1.0',
    gameType,
    seed,
    engineVersion: ENGINE_VERSION,
    contentVersions,
    initialState: {
      version: SNAPSHOT_VERSION,
      engineVersion: ENGINE_VERSION,
      seed,
      rngState,
      state: initialState,
      eventCount: 0,
      takenAt: initialState.monotonicCounter,
    },
    commands,
  };
}

/**
 * RNG determinista sembrado.
 *
 * Reglas:
 * - Misma semilla ÔåÆ misma secuencia de numeros.
 * - Estado serializable para snapshots y replay.
 * - Sin dependencias de Math.random() ni Date.now().
 * - Algoritmo: LCG (Linear Congruential Generator) con parametros de Numerical Recipes.
 */

import seedrandom from 'seedrandom';

export class DeterministicRng {
  private state: number;
  readonly seed: string;

  constructor(seed: string) {
    this.seed = seed;
    // Usar seedrandom solo para inicializar el estado inicial
    const sr = seedrandom(seed);
    this.state = Math.floor(sr() * 0x7fffffff) || 1;
  }

  private next(): number {
    // LCG con parametros de Numerical Recipes
    // X_{n+1} = (a * X_n + c) mod m
    const a = 1664525;
    const c = 1013904223;
    const m = 0x100000000; // 2^32
    this.state = (a * this.state + c) % m;
    return this.state / m;
  }

  /** Entero entre min y max inclusive */
  nextInt(min: number, max: number): number {
    if (min > max) throw new Error(`nextInt: min (${min}) > max (${max})`);
    return min + Math.floor(this.next() * (max - min + 1));
  }

  /** Float entre 0 (inclusive) y 1 (exclusive) */
  nextFloat(): number {
    return this.next();
  }

  /** Barajar array (Fisher-Yates) sin mutar el original */
  shuffle<T>(array: readonly T[]): T[] {
    const result = [...array];
    for (let i = result.length - 1; i > 0; i--) {
      const j = this.nextInt(0, i);
      [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
  }

  /** Elegir un elemento aleatorio */
  pick<T>(array: readonly T[]): T {
    if (array.length === 0) throw new Error('pick: empty array');
    return array[this.nextInt(0, array.length - 1)];
  }

  /** Serializar estado para snapshots */
  serialize(): { seed: string; state: number } {
    return { seed: this.seed, state: this.state };
  }

  /** Restaurar desde snapshot */
  static deserialize(data: { seed: string; state: number }): DeterministicRng {
    const rng = new DeterministicRng(data.seed);
    rng.state = data.state;
    return rng;
  }
}

/**
 * Scenarios ÔÇö efectos de las 12 cartas de Escenario.
 *
 * Los escenarios modifican las reglas mientras estan activos.
 * Algunos tienen efectos continuos (Ruinas de Brunmar, Mercado de Lotharion)
 * y otros tienen efectos disparados (Campo de Batalla, Pantano Umbr├¡o).
 *
 * Cuando el campo de batalla queda vacio, se descarta el escenario actual
 * y se revela uno nuevo del mazo de Escenarios.
 */

import type {
  GameState,
  GameEvent,
  ResolutionContext,
  EnemyState,
  PendingChoice,
} from '@nt4h/schema';
import type { CatalogLoadResult } from '@nt4h/catalog';
import { evalValue, EffectRegistry, registerCoreEffects } from '../effects/registry.js';
import { resolveCard } from '../effects/resolver.js';
import { DeterministicRng } from '../rng/index.js';

let scenarioSeq = 0;
function nextSeq(): number {
  return ++scenarioSeq;
}
export function resetScenarioSeq(): void {
  scenarioSeq = 0;
}

/**
 * Aplicar los efectos continuos de un escenario al estado.
 * Se llama cuando un escenario se revela.
 */
export function applyScenarioEffects(
  state: GameState,
  scenarioDefId: string,
  _catalog: CatalogLoadResult,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  let newState = state;

  switch (scenarioDefId) {
    case 'scenario.brunmar-ruins':
      // Ruinas de Brunmar: -1 fortaleza a todos los enemigos (via modificador), ignora Gloria
      newState = {
        ...newState,
        ignoreGloryRewards: true,
        battlefield: newState.battlefield.map(e => ({
          ...e,
          // NO mutar baseFortitude; el modificador se aplica via getEffectiveFortitude
          modifiers: [
            ...e.modifiers,
            {
              id: `scenario-brunmar-${nextSeq()}`,
              sourceId: newState.scenario?.instanceId ?? 'scenario',
              layer: 'FORTITUDE_MODIFIERS',
              timestamp: nextSeq(),
              duration: 'WHILE_SOURCE_ACTIVE',
              amount: -1,
            },
          ],
        })),
      };
      break;

    case 'scenario.lotharion-market':
      // Mercado de Lotharion: -1 al coste de mercado
      newState = {
        ...newState,
        marketCostModifier: newState.marketCostModifier - 1,
      };
      break;

    case 'scenario.skaarg-plains':
      // Planicie de Skaarg: ignora recompensas de monedas
      newState = {
        ...newState,
        ignoreCoinRewards: true,
      };
      break;

    default:
      // Escenarios con efectos disparados no modifican el estado continuamente
      break;
  }

  return { state: newState, events };
}

/**
 * Limpiar los efectos de un escenario al descartarlo.
 */
export function clearScenarioEffects(
  state: GameState,
  scenarioDefId: string,
): { state: GameState; events: GameEvent[] } {
  const events: GameEvent[] = [];
  let newState = state;

  switch (scenarioDefId) {
    case 'scenario.brunmar-ruins':
      newState = {
        ...newState,
        ignoreGloryRewards: false,
        // Solo quitar modificadores del escenario (baseFortitude no fue mutado)
        battlefield: newState.battlefield.map(e => ({
          ...e,
          modifiers: e.modifiers.filter(m => !m.id.startsWith('scenario-brunmar')),
        })),
      };
      break;

    case 'scenario.lotharion-market':
      newState = {
        ...newState,
        marketCostModifier: newState.marketCostModifier + 1,
      };
      break;

    case 'scenario.skaarg-plains':
      newState = {
        ...newState,
        ignoreCoinRewards: false,
      };
      break;

    default:
      break;
  }

  return { state: newState, events };
}

/**
 * Procesar el efecto disparado ON_ENEMY_DEFEATED de un escenario.
 * Lee condition.fortitudeGte del JSON del escenario en lugar de hardcodear.
 */
export function onEnemyDefeated(
  state: GameState,
  scenarioDefId: string,
  defeatingPlayerId: string,
  enemyFortitude: number,
  catalog?: CatalogLoadResult,
): GameEvent[] {
  const events: GameEvent[] = [];

  // Intentar leer los efectos del escenario desde el cat├ílogo
  const scenarioDef = catalog?.byId.get(scenarioDefId);
  const onDefeatEffect = scenarioDef?.effects?.find(
    (e: any) => e.type === 'ON_ENEMY_DEFEATED'
  ) as any;

  if (onDefeatEffect) {
    // Evaluar condition.fortitudeGte si existe
    const fortitudeGte = onDefeatEffect.condition?.fortitudeGte;
    if (fortitudeGte !== undefined && enemyFortitude < fortitudeGte) {
      return events; // No cumple la condici├│n
    }
    // Contexto m├¡nimo para evalValue
    const ctx: ResolutionContext = {
      activePlayerId: defeatingPlayerId,
      currentCardId: '',
      currentCardName: '',
      currentCardInstanceId: '',
      selectedEnemyId: null,
      cardsPlayedThisTurn: {},
      cardsPlayedAgainstEnemy: {},
      drawnCardInstanceId: null,
      sourceZone: 'HAND',
      enemiesDefeatedThisResolution: [],
      depth: 0,
      lastDefeatedEnemyFortitude: enemyFortitude,
    };
    // Ejecutar los efectos internos declarativamente con evalValue
    for (const innerEffect of onDefeatEffect.effects ?? []) {
      if (innerEffect.type === 'GAIN_COINS') {
        const amount = innerEffect.amount
          ? evalValue(innerEffect.amount, ctx, state)
          : 1;
        events.push({
          type: 'COINS_GAINED',
          playerId: defeatingPlayerId,
          amount,
          seq: nextSeq(),
        });
      } else if (innerEffect.type === 'GAIN_GLORY') {
        const amount = innerEffect.amount
          ? evalValue(innerEffect.amount, ctx, state)
          : 1;
        events.push({
          type: 'GLORY_GAINED',
          playerId: defeatingPlayerId,
          amount,
          seq: nextSeq(),
        });
      } else if (innerEffect.type === 'DRAW_CARDS') {
        const amount = innerEffect.amount
          ? evalValue(innerEffect.amount, ctx, state)
          : 1;
        const player = state.players[defeatingPlayerId];
        const drawn = player
          ? player.abilityDeck.slice(0, amount).map(c => c.instanceId)
          : [];
        if (drawn.length > 0) {
          events.push({
            type: 'CARDS_DRAWN',
            playerId: defeatingPlayerId,
            count: drawn.length,
            cardInstanceIds: drawn,
            seq: nextSeq(),
          });
        }
      } else if (innerEffect.type === 'LOSE_CARDS') {
        const amount = innerEffect.amount
          ? evalValue(innerEffect.amount, ctx, state)
          : 1;
        const player = state.players[defeatingPlayerId];
        const lost = player
          ? player.abilityDeck.slice(0, amount).map(c => c.instanceId)
          : [];
        if (lost.length > 0) {
          events.push({
            type: 'CARDS_LOST',
            playerId: defeatingPlayerId,
            count: lost.length,
            cardInstanceIds: lost,
            seq: nextSeq(),
          });
        }
      }
    }
    return events;
  }

  // Fallback: comportamiento hardcodeado si no hay cat├ílogo
  switch (scenarioDefId) {
    case 'scenario.battlefield':
      events.push({
        type: 'COINS_GAINED',
        playerId: defeatingPlayerId,
        amount: 1,
        seq: nextSeq(),
      });
      break;

    case 'scenario.umbrous-swamp':
      if (enemyFortitude >= 3) {
        events.push({
          type: 'COINS_GAINED',
          playerId: defeatingPlayerId,
          amount: 1,
          seq: nextSeq(),
        });
      }
      break;

    default:
      break;
  }

  return events;
}

/**
 * Procesar el efecto opcional ON_TURN_START de un escenario.
 * Devuelve null si el escenario no tiene efecto de inicio de turno,
 * o una descripcion del efecto para que el jugador decida.
 */
export function onTurnStart(
  _state: GameState,
  scenarioDefId: string,
): { optional: boolean; prompt: string } | null {
  switch (scenarioDefId) {
    case 'scenario.ur-mountains':
      return {
        optional: true,
        prompt: 'Monta├▒as de Ur: ┬┐Robar 1 carta y revelar un enemigo de la Horda?',
      };

    case 'scenario.eque-port':
      return {
        optional: true,
        prompt: 'Puerto de Eque: ┬┐Descartar 1 carta, robar 1 y +1 al dano del enemigo?',
      };

    case 'scenario.kalern-mud':
      // Lodazal de Kalern: el jugador a la izquierda elige un enemigo y lo devuelve al fondo de la Horda
      return {
        optional: false,
        prompt: 'Lodazal de Kalern: El jugador a tu izquierda elige un enemigo para devolverlo al fondo del mazo de la Horda',
      };

    case 'scenario.ulthar-portal':
      // Portal de Ulthar: opcional, pagar 1 Gloria o 2 Monedas para devolver Hueste y colocar trofeo
      return {
        optional: true,
        prompt: 'Portal de Ulthar: ┬┐Pagar 1 Gloria (o 2 Monedas) para devolver una Hueste al mazo y colocar un trofeo en el campo?',
      };

    case 'scenario.tears-of-aradiel':
      // L├ígrimas de Aradiel: una vez por turno, pagar 1 Gloria a otro h├®roe y jugar carta aleatoria suya
      // Solo multijugador (_notValidInSolo)
      if (_state.playerOrder.length <= 1) return null;
      return {
        optional: true,
        prompt: 'L├ígrimas de Aradiel: ┬┐Pagar 1 Gloria a otro h├®roe y jugar una carta aleatoria suya?',
      };

    case 'scenario.jade-deposits':
      return {
        optional: true,
        prompt: 'Yacimientos de Jade: ┬┐Descartar toda la mano, robar 4 y ganar 3 monedas?',
      };

    default:
      return null;
  }
}

/**
 * Ejecutar el efecto opcional de un escenario de inicio de turno.
 */
export function executeTurnStartEffect(
  state: GameState,
  scenarioDefId: string,
  playerId: string,
  accepted: boolean,
  catalog?: CatalogLoadResult,
  rng?: DeterministicRng,
): { state: GameState; events: GameEvent[]; pendingChoice?: PendingChoice } {
  const events: GameEvent[] = [];
  let newState = state;

  if (!accepted) return { state: newState, events };

  const player = newState.players[playerId];

  switch (scenarioDefId) {
    case 'scenario.ur-mountains': {
      // Robar 1 carta
      if (player.abilityDeck.length > 0) {
        const drawn = player.abilityDeck[0];
        events.push({
          type: 'CARDS_DRAWN',
          playerId,
          count: 1,
          cardInstanceIds: [drawn.instanceId],
          seq: nextSeq(),
        });
      }
      // Revelar enemigo del FONDO del mazo de la Horda y anadirlo al campo
      if (newState.hordeDeck.length > 0 && catalog) {
        const enemyCard = newState.hordeDeck[newState.hordeDeck.length - 1];
        const enemyDef = catalog.byId.get(enemyCard.definitionId);
        if (enemyDef) {
          // Crear EnemyState y anadirlo al battlefield
          const newEnemy: EnemyState = {
            instanceId: enemyCard.instanceId,
            definitionId: enemyCard.definitionId,
            baseFortitude: enemyDef.printedFortitude ?? 1,
            wounds: 0,
            reward: enemyDef.reward ?? null,
            modifiers: [],
            isWarlord: enemyDef.type === 'WARLORD',
            isOrc: enemyDef.isOrc ?? false,
            specialIcons: enemyDef.specialIcons ?? [],
            damageDisabled: false,
          };
          newState = {
            ...newState,
            battlefield: [...newState.battlefield, newEnemy],
            hordeDeck: newState.hordeDeck.slice(0, -1),
          };
          events.push({
            type: 'ENEMY_REVEALED',
            enemyInstanceId: enemyCard.instanceId,
            definitionId: enemyCard.definitionId,
            fortitude: enemyDef.printedFortitude ?? 1,
            seq: nextSeq(),
          });
          // Si el enemigo revelado es el Se├▒or de la Guerra, emitir WARLORD_REVEALED
          // y descartar el escenario (spec: termina al revelar Warlord)
          if (newEnemy.isWarlord) {
            events.push({
              type: 'WARLORD_REVEALED',
              warlordInstanceId: enemyCard.instanceId,
              definitionId: enemyCard.definitionId,
              seq: nextSeq(),
            });
            // D360: Transferir scenarioCoins al jugador antes de descartar (spec ┬º4.2)
            if (newState.mode === 'SOLO' && newState.scenarioCoins > 0) {
              events.push({
                type: 'COINS_GAINED',
                playerId: newState.activePlayerId,
                amount: newState.scenarioCoins,
                seq: nextSeq(),
              });
            }
            events.push({
              type: 'SCENARIO_DISCARDED',
              scenarioInstanceId: newState.scenario!.instanceId,
              seq: nextSeq(),
            });
            newState = {
              ...newState,
              scenario: null,
              scenarioCoins: 0,
            };
          }
        }
      }
      break;
    }

    case 'scenario.eque-port': {
      // Puerto de Eque: el jugador elige qu├® carta descartar, luego roba 1 y +1 da├▒o
      if (player.hand.length === 0) break;
      // Crear eleccion pendiente para que el jugador elija la carta a descartar
      const choice: PendingChoice = {
        choiceId: `eque-port-card-${nextSeq()}`,
        playerId,
        type: 'SELECT_CARD_FROM_HAND',
        prompt: 'Puerto de Eque: Elige una carta de tu mano para descartar',
        options: player.hand.map(c => c.instanceId),
        minSelections: 1,
        maxSelections: 1,
      };
      return { state: newState, events, pendingChoice: choice };
    }

    case 'scenario.jade-deposits': {
      // Descartar toda la mano
      for (const card of player.hand) {
        events.push({
          type: 'CARD_MOVED',
          cardInstanceId: card.instanceId,
          from: 'HAND',
          to: 'WEAR_PILE',
          seq: nextSeq(),
        });
      }
      // Robar 4 cartas
      const drawn = player.abilityDeck.slice(0, 4).map(c => c.instanceId);
      if (drawn.length > 0) {
        events.push({
          type: 'CARDS_DRAWN',
          playerId,
          count: drawn.length,
          cardInstanceIds: drawn,
          seq: nextSeq(),
        });
      }
      // Ganar 3 monedas
      events.push({
        type: 'COINS_GAINED',
        playerId,
        amount: 3,
        seq: nextSeq(),
      });
      break;
    }

    case 'scenario.kalern-mud': {
      // Lodazal de Kalern: el jugador a la izquierda elige un enemigo y lo devuelve al fondo de la Horda
      if (newState.battlefield.length === 0) break;
      // Crear eleccion pendiente para que el jugador elija el enemigo a devolver
      const choice: PendingChoice = {
        choiceId: `kalern-mud-enemy-${nextSeq()}`,
        playerId,
        type: 'SELECT_ENEMY',
        prompt: 'Lodazal de Kalern: Elige un enemigo para devolverlo al fondo del mazo de la Horda',
        options: newState.battlefield.map(e => e.instanceId),
        minSelections: 1,
        maxSelections: 1,
      };
      return { state: newState, events, pendingChoice: choice };
    }

    case 'scenario.tears-of-aradiel': {
      // L├ígrimas de Aradiel: pagar 1 Gloria a otro h├®roe, jugar carta suya, devolverla, el due├▒o roba 1
      // El h├®roe objetivo se elige aleatoriamente (spec: "otro h├®roe elegido al azar")
      if (!accepted) break;
      if (player.glory < 1) break;
      const others = newState.playerOrder.filter(id => id !== playerId);
      if (others.length === 0) break;
      const rngToUse = rng ?? new DeterministicRng('tears');
      const targetId = rngToUse.pick(others);
      const targetPlayer = newState.players[targetId];
      // Verificar si el h├®roe objetivo tiene cartas antes de pagar Gloria
      if (targetPlayer.hand.length === 0) break;
      // Pagar 1 Gloria al otro h├®roe
      events.push({
        type: 'GLORY_LOST',
        playerId,
        amount: 1,
        seq: nextSeq(),
      });
      events.push({
        type: 'GLORY_GAINED',
        playerId: targetId,
        amount: 1,
        seq: nextSeq(),
      });
      // Jugar carta del otro h├®roe (aleatoria usando rng determinista)
      const randomIdx = rngToUse.nextInt(0, targetPlayer.hand.length - 1);
      const borrowedCard = targetPlayer.hand[randomIdx];
      // Resolver la carta prestada como si la jugara el jugador activo
      if (catalog) {
        const borrowedDef = catalog.byId.get(borrowedCard.definitionId);
        if (borrowedDef) {
          const tempReg = new EffectRegistry();
          registerCoreEffects(tempReg);
          const resolveResult = resolveCard(
            newState, borrowedCard, borrowedDef, null,
            newState.players[playerId], rngToUse, tempReg, catalog,
          );
          events.push(...resolveResult.events);
          // No asignar newState = resolveResult.newState; execute.ts aplicar├í los eventos
        }
      }
      // resolveCard ya mueve la carta a desgaste (no emitir CARD_MOVED duplicado)
      // El due├▒o roba 1 carta
      if (targetPlayer.abilityDeck.length > 0) {
        events.push({
          type: 'CARDS_DRAWN',
          playerId: targetId,
          count: 1,
          cardInstanceIds: [targetPlayer.abilityDeck[0].instanceId],
          seq: nextSeq(),
        });
      }
      break;
    }

    case 'scenario.ulthar-portal': {
      // Portal de Ulthar: pagar 1 Gloria o 2 Monedas, devolver Hueste al mazo y colocar trofeo
      // Verificar primero que hay trofeos disponibles
      if (player.trophies.length === 0) {
        return { state: newState, events };
      }
      // D381: Permitir al jugador elegir entre Gloria o Monedas (spec: "1 ficha de Gloria o 2 Monedas")
      const canPayGlory = player.glory >= 1;
      const canPayCoins = player.coins >= 2;
      if (canPayGlory && canPayCoins) {
        // Crear eleccion pendiente para que el jugador decida el pago
        const choice: PendingChoice = {
          choiceId: `ulthar-pay-${nextSeq()}`,
          playerId,
          type: 'CONFIRM',
          prompt: 'Portal de Ulthar: paga 1 Gloria o 2 Monedas',
          options: ['glory', 'coins'],
          minSelections: 1,
          maxSelections: 1,
        };
        return { state: newState, events, pendingChoice: choice };
      } else if (canPayGlory) {
        events.push({ type: 'GLORY_LOST', playerId, amount: 1, seq: nextSeq() });
      } else if (canPayCoins) {
        events.push({ type: 'COINS_GAINED', playerId, amount: -2, seq: nextSeq() });
      } else {
        return { state: newState, events };
      }
      // Tras el pago autom├ítico, crear eleccion para elegir Hueste a devolver
      if (newState.battlefield.length > 0) {
        const nonWarlordEnemies = newState.battlefield.filter(e => !e.isWarlord);
        if (nonWarlordEnemies.length > 0) {
          const enemyChoice: PendingChoice = {
            choiceId: `ulthar-enemy-${nextSeq()}`,
            playerId,
            type: 'SELECT_ENEMY',
            prompt: 'Portal de Ulthar: Elige una Hueste para devolverla al mazo',
            options: nonWarlordEnemies.map(e => e.instanceId),
            minSelections: 1,
            maxSelections: 1,
          };
          return { state: newState, events, pendingChoice: enemyChoice };
        }
      }
      break;
    }

    default:
      break;
  }

  return { state: newState, events };
}

/**
 * Nivel 4: Pruebas individuales por carta.
 *
 * Para cada carta del catalogo oficial, verifica:
 * - La carta tiene un definitionId valido en el catalogo
 * - La carta se puede jugar mediante el comando PLAY_CARD
 * - La carta produce al menos un evento al ser jugada
 * - La carta no deja el estado en un estado invalido
 *
 * Las cartas se agrupan por tipo para legibilidad.
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { execute } from '../../src/commands/execute.js';
import { setupGame, startFirstTurn, resetInstanceCounter } from '../../src/phases/setup.js';
import { resetPhaseSeq } from '../../src/phases/engine.js';
import { resetResolveSeq } from '../../src/effects/resolver.js';
import { DeterministicRng } from '../../src/rng/index.js';
import { EffectRegistry, registerCoreEffects } from '../../src/effects/registry.js';
import { loadCatalog } from '@nt4h/catalog';
import type { GameState, Command, CardDefinition } from '@nt4h/schema';

const catalog = loadCatalog();

function makeGame(seed: string): GameState {
  const config = {
    mode: 'STANDARD' as const,
    playerCount: 2,
    seed,
    heroes: [
      { playerId: 'p1', heroId: 'hero.aranel', heroFace: 'FEMALE' as const, deckId: 'explorer.default' },
      { playerId: 'p2', heroId: 'hero.feldon', heroFace: 'MALE' as const, deckId: 'warrior.default' },
    ],
    useScenarios: false,
  };
  const setup = setupGame(config, catalog);
  const turnResult = startFirstTurn(setup.state, new DeterministicRng(seed));
  return turnResult.state;
}

/**
 * Encontrar una carta en la mano del jugador activo que coincida con el definitionId.
 * Si no esta en la mano, buscar en el abilityDeck y ponerla en la mano.
 */
function ensureCardInHand(state: GameState, definitionId: string): GameState {
  const activeId = state.activePlayerId;
  const player = state.players[activeId];
  // Ya esta en la mano?
  if (player.hand.some(c => c.definitionId === definitionId)) {
    return state;
  }
  // Buscar en el abilityDeck y moverla a la mano
  const deckIdx = player.abilityDeck.findIndex(c => c.definitionId === definitionId);
  if (deckIdx >= 0) {
    const card = player.abilityDeck[deckIdx];
    const newDeck = [...player.abilityDeck];
    newDeck.splice(deckIdx, 1);
    const newHand = [...player.hand, card];
    return {
      ...state,
      players: {
        ...state.players,
        [activeId]: {
          ...player,
          abilityDeck: newDeck,
          hand: newHand,
        },
      },
    };
  }
  // Crear una carta nueva si no existe en el mazo
  const newCard = {
    instanceId: `test-${definitionId}-${Date.now()}`,
    definitionId,
    ownerId: activeId,
    zone: 'HAND' as const,
  };
  return {
    ...state,
    players: {
      ...state.players,
      [activeId]: {
        ...player,
        hand: [...player.hand, newCard],
      },
    },
  };
}

describe('Nivel 4 - Pruebas individuales por carta', () => {
  let registry: EffectRegistry;
  let rng: DeterministicRng;

  beforeEach(() => {
    resetInstanceCounter();
    resetPhaseSeq();
    resetResolveSeq();
    registry = new EffectRegistry();
    registerCoreEffects(registry);
  });

  // Agrupar cartas por tipo
  const cardsByType = new Map<string, CardDefinition[]>();
  for (const card of catalog.cards) {
    const list = cardsByType.get(card.type) ?? [];
    list.push(card);
    cardsByType.set(card.type, list);
  }

  // Probar cada carta de Habilidad
  describe('Cartas de Habilidad (ABILITY)', () => {
    const abilities = cardsByType.get('ABILITY') ?? [];

    for (const card of abilities) {
      it(`${card.id} (${card.name}) se puede jugar y produce eventos`, () => {
        const seed = `card-${card.id}`;
        rng = new DeterministicRng(seed);
        let state = makeGame(seed);
        state = ensureCardInHand(state, card.id);

        const activeId = state.activePlayerId;
        const player = state.players[activeId];
        const cardInstance = player.hand.find(c => c.definitionId === card.id);
        expect(cardInstance).toBeDefined();

        const targetEnemy = state.battlefield[0];
        const cmd: Command = {
          type: 'PLAY_CARD',
          cid: 'test',
          cardInstanceId: cardInstance!.instanceId,
          targetEnemyId: targetEnemy?.instanceId,
        };

        const result = execute(state, cmd, rng, registry, catalog);

        // La carta debe ser aceptada (puede fallar por coste, pero la mayoria no)
        // Al menos no debe crashear
        if (result.accepted) {
          expect(result.events.length).toBeGreaterThan(0);
        }
      });
    }
  });

  // Probar cada carta de Mercado
  describe('Cartas de Mercado (MARKET)', () => {
    const market = cardsByType.get('MARKET') ?? [];

    for (const card of market) {
      it(`${card.id} (${card.name}) esta en el catalogo y tiene estructura valida`, () => {
        // Las cartas de mercado se compran, no se juegan directamente
        // Verificar estructura
        expect(card.printedCost).toBeDefined();
        expect(card.printedCost!).toBeGreaterThan(0);
        expect(card.effects).toBeDefined();
      });
    }
  });

  // Probar cada Hueste
  describe('Cartas de Hueste (HORDE)', () => {
    const horde = cardsByType.get('HORDE') ?? [];

    for (const card of horde) {
      it(`${card.id} (${card.name}) tiene fortaleza y recompensa`, () => {
        expect(card.printedFortitude).toBeDefined();
        expect(card.printedFortitude!).toBeGreaterThanOrEqual(1);
        expect(card.reward).toBeDefined();
        // Algunas Huestes pueden tener recompensa 0 (sin coins ni glory)
        expect(card.reward!.coins).toBeGreaterThanOrEqual(0);
        expect(card.reward!.glory).toBeGreaterThanOrEqual(0);
      });
    }
  });

  // Probar cada Senor de la Guerra
  describe('Cartas de Warlord (WARLORD)', () => {
    const warlords = cardsByType.get('WARLORD') ?? [];

    for (const card of warlords) {
      it(`${card.id} (${card.name}) tiene fortaleza >= 6`, () => {
        expect(card.printedFortitude).toBeDefined();
        expect(card.printedFortitude!).toBeGreaterThanOrEqual(6);
      });
    }
  });

  // Probar cada Escenario
  describe('Cartas de Escenario (SCENARIO)', () => {
    const scenarios = cardsByType.get('SCENARIO') ?? [];

    for (const card of scenarios) {
      it(`${card.id} (${card.name}) tiene estructura valida`, () => {
        expect(card.name).toBeDefined();
        expect(card.name.length).toBeGreaterThan(0);
      });
    }
  });

  // Resumen: todas las cartas tienen ID unico
  describe('Resumen del catalogo', () => {
    it('todas las cartas tienen un definitionId resolvable en el catalogo', () => {
      for (const card of catalog.cards) {
        expect(catalog.byId.has(card.id)).toBe(true);
        expect(catalog.byId.get(card.id)?.id).toBe(card.id);
      }
    });

    it('el numero total de cartas unicas es correcto', () => {
      const total = Array.from(cardsByType.values()).reduce((s, c) => s + c.length, 0);
      expect(total).toBe(catalog.totalCards);
    });
  });
});

